window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0235", [{"word":"heat wave","ipa_uk":"/ˈhiːt weɪv/","ipa_us":"/ˈhiːt weɪv/","definition_zh":"热浪；持续多日的异常酷热天气；突然集中爆发的热潮","definition_en":"a spell of unusually hot weather lasting several days, or a sudden widespread surge of something","core_image":"暑气在城市上空积成一层厚盖，柏油路面整夜不凉，墙外的空调外机不停滴水","scene":"入夏第三个星期，柏油路面整夜不凉，气象站连续多日测到异常高温。The heat wave held the city for twelve days without a storm.","sceneCN":"这里指连续多日不散的异常高温（第 1 个义项：持续多日高温）；句意为这场热浪围住城市十二天，一场雷雨也没来。图中可辨识物件：柏油路、温度计、空调外机、稀疏树荫。","pos":[{"tag":"n.","zh":"热浪；持续高温期；集中的热潮"}],"collocations":[{"phrase":"a heat wave","zh":"一场热浪"},{"phrase":"during the heat wave","zh":"热浪期间"},{"phrase":"heat wave warning","zh":"热浪警报"},{"phrase":"a record heat wave","zh":"创纪录的热浪"},{"phrase":"heat wave conditions","zh":"热浪天气状况"},{"phrase":"a marine heat wave","zh":"海洋热浪"},{"phrase":"a summer heat wave","zh":"夏季热浪"}],"forms":[{"label":"单数","form":"heat wave"},{"label":"复数","form":"heat waves"},{"label":"复合形容词","form":"heat-wave"},{"label":"加冠词形式","form":"a heat wave"},{"label":"合写形式","form":"heatwave"},{"label":"介词短语形式","form":"during a heat wave"}],"derivatives":[{"word":"heatwave","pos":"n.","zh":"由「热」与「浪」两个成分合写成一词构成，义为「热浪」"},{"word":"heated","pos":"adj.","zh":"由「热」加已然词尾构成，义为「加热的；激烈的」"},{"word":"heating","pos":"n.","zh":"由「热」的动词加名词尾构成，义为「供暖；加热」"},{"word":"heat","pos":"v.","zh":"由同一名词转作动词构成，义为「加热」"},{"word":"hot spell","pos":"n.","zh":"由「热」与「一段时期」组合成的同义说法，义为「酷热期」"}],"senses":[{"no":"01","title":"A spell of lasting heat","titleCN":"持续多日的高温","definition":"a period of abnormally hot weather that lasts several days and nights","definitionCN":"连续数日数夜异常炎热的天气时段","example":"The heat wave lasted ten days and broke the July record.","exampleCN":"这场热浪持续十天，打破了七月的纪录。","why":"The two halves of the compound simply name heat and a rolling swell, so the phrase begins as weather seen as something rolling in.","whyCN":"这个复合词的两半只是「热」与「涌动的浪」，所以它最初把天气看成一波涌来的东西。"},{"no":"02","title":"A recorded heat event","titleCN":"被记录的热浪事件","definition":"a heat wave that has been measured, dated and entered in climate records","definitionCN":"已被测量、标注日期并录入气候记录的热浪","example":"The nineteen thirty-six heat wave is still the benchmark for the region.","exampleCN":"一九三六年的那场热浪至今仍是该地区的基准。","why":"Once weather stations keep daily logs, a spell of heat becomes an event with dates and numbers.","whyCN":"气象站一旦逐日记录，一段高温就变成有日期、有数字的事件。"},{"no":"03","title":"An official heat alert","titleCN":"官方热浪警报","definition":"a public warning issued when a heat wave is expected to endanger health","definitionCN":"预计热浪将危害健康时发布的公共警报","example":"The weather service issued a heat wave alert for the whole province.","exampleCN":"气象部门向全省发布了热浪警报。","why":"Forecasting made the phrase a trigger for action, so it now names the warning as well as the weather.","whyCN":"预报使这个说法成为行动的信号，于是它既指天气，也指那条警报。"},{"no":"04","title":"Heat trapped in a city","titleCN":"城市热浪","definition":"the intensified heat that a city experiences because concrete, asphalt and traffic hold the day's warmth","definitionCN":"城市因混凝土、柏油与车流存住白天的热量而承受的更强炎热","example":"The city heat wave kept night-time temperatures above thirty degrees.","exampleCN":"城市热浪使夜间气温一直高于三十度。","why":"The same phrase shifts from the air above a region to the air inside a built-up area, where surfaces store heat.","whyCN":"同一个说法从区域上空转到建成区内部，那里的地表把热量存了下来。"},{"no":"05","title":"A warm spell in the sea","titleCN":"海洋热浪","definition":"a prolonged period when sea surface temperatures stay far above the long-term average","definitionCN":"海表温度长时间远高于长期平均值的时段","example":"A marine heat wave bleached the reef in a single season.","exampleCN":"一场海洋热浪在一个季节里就使珊瑚礁白化。","why":"Oceanographers borrowed the weather phrase because warm water spreads and lingers like a dome of hot air.","whyCN":"海洋学家借用了这个天气说法，因为暖水扩散、滞留的样子像一顶热空气罩。"},{"no":"06","title":"A sudden surge of anything","titleCN":"比喻集中的热潮","definition":"a short period in which an activity, feeling or rumour spreads widely and fast","definitionCN":"某种活动、情绪或传闻在短时间内广泛迅速扩散的时期","example":"A heat wave of rumours swept the office before the audit.","exampleCN":"审计之前，一阵传闻的热潮扫过办公室。","why":"Nineteenth-century usage let wave mean any surging movement, and the compound followed it into figurative weather.","whyCN":"十九世纪的用法让「浪」可以指任何涌动的势头，这个复合词便跟着进入比喻性的天气。"},{"no":"07","title":"A summer remembered by its deaths","titleCN":"被命名的致命盛夏","definition":"a heat wave so severe that a city or country names it and remembers its death toll","definitionCN":"严重到被城市或国家命名、并被记住死亡人数的热浪","example":"The named heat wave killed hundreds of elderly residents.","exampleCN":"那场被命名的热浪夺走了数百名老年居民的生命。","why":"Extreme events enter public memory with a name, the way storms do, so a deadly summer becomes a proper event.","whyCN":"极端事件会像风暴一样带着名字进入公共记忆，于是致命的盛夏成了一个专名事件。"},{"no":"08","title":"A public health crisis period","titleCN":"公共卫生冲击期","definition":"a stretch of heat during which hospitals, power grids and emergency services are strained","definitionCN":"医院、电网与急救系统都承受压力的一段高温时期","example":"During the heat wave hospitals admitted twice the usual number of patients.","exampleCN":"热浪期间，医院收治的病人是平常的两倍。","why":"The phrase ends up naming not the temperature but the burden it places on a whole society.","whyCN":"这个说法最终指的不是温度本身，而是它压在整个社会身上的负担。"}],"etymology":{"intro":{"en":"Heat wave is a native English compound. Its first half comes from Old English hǣtu, heat, and its second half from Old English wǣg, a moving swell of water. The compound itself is a mid-nineteenth-century formation; the exact year of first use is uncertain.","cn":"这是英语本族复合词。前一半来自古英语「hǣtu」「热」，后一半来自古英语「wǣg」「移动的水浪」。复合词本身是十九世纪中叶的构造，确切首见年代不确定。"},"items":[{"era":"OLD ENGLISH HEAT","en":"Old English hǣtu named heat itself, a native Germanic word with no Latin ancestor.","cn":"古英语「hǣtu」指热本身，是日耳曼语本族词，没有拉丁语祖先。"},{"era":"OLD ENGLISH WAVE WORD","en":"Old English wǣg first meant a moving swell of water, the ridge that rolls and lifts.","cn":"古英语「wǣg」最初指移动的水浪，即起伏涌起的那道浪脊。"},{"era":"NINETEENTH CENTURY SHIFT","en":"In the nineteenth century wave extended from water to any surging movement, including a spell of weather.","cn":"十九世纪，这个「浪」词从水面扩展到任何涌动的势头，包括一段天气。"},{"era":"COMPOUND FORMATION","en":"Heat wave appeared as a compound in the mid-nineteenth century; the exact year of first use is uncertain.","cn":"「热浪」这个复合词在十九世纪中叶出现，确切首见年代不确定。"},{"era":"WEATHER SERVICE ERA","en":"Weather services later turned the phrase into an official category with thresholds, forecasts and warnings.","cn":"气象部门后来把这个说法变成带有阈值、预报与警报的官方类别。"},{"era":"CLIMATE AND METAPHOR","en":"Climate research extended it to ocean heat waves, and everyday speech lent it to any sudden surge.","cn":"气候研究把它扩展到海洋热浪，日常说法又把它借给任何突然的涌潮。"}]},"similar":{"note":{"en":"The first group looks or sounds like heat wave; the second group names neighbouring ideas of hot spells and heat warnings.","cn":"第一组在形音上与「heat wave」相近；第二组是与「酷热期、高温警报」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"heatwave","ipa":"/ˈhiːtweɪv/","tag":"same root","definition":"The same weather event written as one word, a spelling that became common in the twentieth century.","definitionCN":"同一个天气事件的合写形式，这种拼法在二十世纪变得常见。"},{"word":"heat","ipa":"/hiːt/","tag":"same root","definition":"High temperature itself, the first half of the compound.","definitionCN":"指高温本身，是复合词的前一半。"},{"word":"wave","ipa":"/weɪv/","tag":"same root","definition":"A raised ridge moving across water, and by extension any surging movement.","definitionCN":"指在水面移动的浪脊，引申指任何涌动的势头。"},{"word":"heated","ipa":"/ˈhiːtɪd/","tag":"same root","definition":"Made warm, or made intense and angry, as in a heated argument.","definitionCN":"指被加热的，也指激烈愤怒的，如激烈的争论。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hot spell","ipa":"/ˈhɒt spel/","tag":"near meaning","definition":"A stretch of hot weather, usually shorter and less technical than a heat wave.","definitionCN":"指一段炎热天气，通常比热浪短，也更口语。"},{"word":"heat dome","ipa":"/ˈhiːt dəʊm/","tag":"near meaning","definition":"A persistent high-pressure system that traps hot air beneath it and causes a heat wave.","definitionCN":"指滞留的高压系统把热空气压在下方，从而造成热浪。"},{"word":"scorcher","ipa":"/ˈskɔːtʃə/","tag":"near meaning","definition":"An informal word for an extremely hot day.","definitionCN":"指极热一天的口语说法。"},{"word":"heat alert","ipa":"/ˈhiːt əˈlɜːt/","tag":"near meaning","definition":"A public notice that dangerous heat is expected, close to the official sense of the phrase.","definitionCN":"指预报危险高温的公共通告，接近这个词的官方义。"},{"word":"marine heat wave","ipa":"/məˈriːn ˈhiːt weɪv/","tag":"near meaning","definition":"The ocean version of the phenomenon, with water instead of air as the hot medium.","definitionCN":"指这一现象的海洋版本，热的介质是水而不是空气。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two native halves of the compound, its real records and its real weather phrases.","cn":"正常联想使用这个复合词两个本族成分、真实记录与真实气象搭配。"},"normal":[{"en":"Heat plus wave: hot air arriving like a swell that rolls over a city and will not retreat.","cn":"热加浪：热空气像一道涌浪压过城市，迟迟不退。"},{"en":"Both halves are Old English, so the phrase is native rather than borrowed from Latin.","cn":"两个成分都来自古英语，所以这个说法是本族的，不是从拉丁语借来的。"},{"en":"A heat wave warning is the fixed phrase you hear on the radio before a dangerous summer day.","cn":"热浪警报是危险夏日来临前收音机里会出现的固定说法。"},{"en":"Marine heat wave is the scientific use, measuring warm ocean water rather than hot air.","cn":"海洋热浪是科学用法，量的是温暖海水而不是热空气。"},{"en":"The compound is only a mid-nineteenth-century formation, younger than the two words inside it.","cn":"这个复合词只是十九世纪中叶才形成的，比它里面的两个词年轻得多。"}],"abstract":[{"en":"A heat wave is weather with a lid on it: the air cannot rise and cannot leave.","cn":"热浪是被盖住的天气：空气既升不上去，也走不掉。"},{"en":"A city in a heat wave becomes an oven that keeps its own warmth after sunset.","cn":"热浪中的城市成了一口日落后仍存着自己热量的烤箱。"},{"en":"Any rumour can arrive as a heat wave: brief, wide, and impossible to escape while it lasts.","cn":"任何传闻都可能像热浪一样到来：短暂、广泛，在它持续时无处可躲。"}]},"examples":[{"en":"The heat wave forced the city to open cooling centres.","cn":"这场热浪迫使城市开放避暑中心。"},{"en":"Scientists counted a marine heat wave off the coast last summer.","cn":"科学家去年夏天记录了近岸的一场海洋热浪。"},{"en":"A heat wave of protest followed the announcement.","cn":"公告发布之后，一阵抗议的热潮随之而来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「希特 威夫」——热到空气都翻起了浪：热浪，也用来说一阵突然涌来的热潮。","word":"heat wave"},"root":"英语本族复合词：前一半来自古英语「hǣtu」「热」，后一半来自古英语「wǣg」「移动的水浪」；「wave」在十九世纪扩展为「一阵涌动」，复合词于十九世纪中叶出现，确切首见年代不确定。两个成分皆属日耳曼语，没有拉丁同族词。","sensesIntro":{"en":"Eight senses move from a plain weather spell to the official alert, the city and the ocean, a figurative surge, a named deadly summer, and a period of public health strain.","cn":"八个义项从单纯的天气时段走向官方警报、城市与海洋、比喻性的涌潮、被命名的致命盛夏，以及公共卫生承压的时期。"},"semanticMap":{"core":{"en":"CORE IMAGE: a broad dome of hot air sits over a city for days while the pavement never cools.","cn":"核心意象：一顶宽大的热空气罩连日压在城上，路面始终不凉。"},"chain":["HOT AIR ARRIVES","DAY AFTER DAY","CITY KEEPS THE HEAT","OFFICIAL ALERT","OCEAN WARMS","SUDDEN SURGE"],"branches":[{"senses":"01","en":"THE SPELL: hot air arrives and stays, day and night, until records fall.","cn":"高温时段：热空气来了就留下，日夜不退，直到纪录被打破。"},{"senses":"02 · 03","en":"THE RECORD AND THE WARNING: the spell is measured, dated and then announced to the public.","cn":"记录与警报：这段高温被测量、标注日期，随后向公众发布。"},{"senses":"04 · 05","en":"THE BUILT AND THE WATERY: surfaces store heat in a city, and warm water spreads across a reef.","cn":"建成区与水域：城市地表存住热量，暖水则铺过珊瑚礁。"},{"senses":"06","en":"THE FIGURATIVE SURGE: rumour or feeling spreads like hot air, wide and fast.","cn":"比喻涌潮：传闻或情绪像热空气一样广而快地散开。"},{"senses":"07 · 08","en":"THE DEADLY SUMMER: a named event, its death toll, and the hospitals and grids under strain.","cn":"致命盛夏：被命名的事件、它的死亡人数，以及承压的医院与电网。"}]},"affixes":{"intro":{"en":"Heat wave is a Germanic compound, so its parts are native English words rather than Latin stems.","cn":"这是一个日耳曼语复合词，各部分是本族英语词，而不是拉丁词干。"},"latinIntro":{"en":"Both components are inherited Germanic words, so there is no Latin counterpart to list here.","cn":"两个成分都是日耳曼语继承下来的本族词，因此这里没有可列的拉丁同族。"},"items":[{"word":"hǣtu","structure":"Old English noun","meaning":"heat, hotness","meaningCN":"热；炎热","example":"The word named the feeling of fire and summer.","exampleCN":"这个词指火与夏天带来的那种感觉。"},{"word":"wǣg","structure":"Old English noun","meaning":"moving wave, swell","meaningCN":"移动的浪；涌浪","example":"It described water lifting and rolling forward.","exampleCN":"它描述水面抬升、向前翻卷的样子。"},{"word":"heat","structure":"Modern English noun from hǣtu","meaning":"high temperature","meaningCN":"高温","example":"The first half of the compound is this everyday noun.","exampleCN":"复合词的前一半就是这个日常名词。"},{"word":"wave","structure":"Modern English noun from wǣg","meaning":"a raised ridge on water; a surge","meaningCN":"水面上的浪脊；一阵涌动","example":"The second half carries the idea of rolling movement.","exampleCN":"后一半带着翻滚移动的意思。"},{"word":"heat wave","structure":"English compound","meaning":"a lasting spell of hot weather","meaningCN":"持续多日的炎热天气","example":"The compound is the ordinary name for the event.","exampleCN":"这个复合词是这一事件的日常名称。"},{"word":"heatwave","structure":"solid-spelling compound","meaning":"the same event written as one word","meaningCN":"同一事件写成一词的形式","example":"Newspapers often close the compound up.","exampleCN":"报纸常把这个复合词合写。"},{"word":"-s","structure":"plural ending","meaning":"more than one spell","meaningCN":"不止一段高温","example":"It marks the plural of the whole phrase.","exampleCN":"它标出整个词组里的复数。"},{"word":"hot","structure":"English adjective from Old English hāt","meaning":"having high temperature","meaningCN":"温度高的","example":"The adjective supplies the family word for hot days.","exampleCN":"这个形容词提供了表示炎热日子的同族词。"},{"word":"spell","structure":"English noun","meaning":"a stretch of time","meaningCN":"一段时期","example":"It names the period that the heat fills.","exampleCN":"它指被高温填满的那段时期。"}],"latinEntries":[],"derivatives":[{"word":"heatwave","pos":"n.","zh":"由「热」与「浪」合写成一词构成，义为「热浪」"},{"word":"heated","pos":"adj.","zh":"由「热」加已然词尾构成，义为「加热的；激烈的」"},{"word":"heating","pos":"n.","zh":"由「热」的动词加名词尾构成，义为「供暖；加热」"},{"word":"heat","pos":"v.","zh":"由同一名词转作动词构成，义为「加热」"}]}},{"word":"paleoclimate","ipa_uk":"/ˌpeɪliəˈklaɪmət/","ipa_us":"/ˌpeɪliəˈklaɪmət/","definition_zh":"古气候；遥远地质时期的气候","definition_en":"the climate of a distant period in Earth's past, studied from preserved records and from models","core_image":"钻机从冰盖深处提上一截冰芯，气泡里封着十万年前的空气，实验室把它切成薄片","scene":"钻机从冰盖深处提上一截冰芯，气泡里封着几万年前的空气。Ice cores let scientists read the paleoclimate of the last ice age.","sceneCN":"这里指遥远过去时期的气候（第 1 个义项：遥远过去的气候）；句意为冰芯让科学家读出末次冰期的古气候。图中可辨识物件：钻机、冰芯、切割台、显微镜。","pos":[{"tag":"n.","zh":"古气候；地质时期的气候状态"}],"collocations":[{"phrase":"study the paleoclimate","zh":"研究古气候"},{"phrase":"paleoclimate record","zh":"古气候记录"},{"phrase":"paleoclimate model","zh":"古气候模型"},{"phrase":"regional paleoclimate","zh":"区域古气候"},{"phrase":"paleoclimate reconstruction","zh":"古气候重建"},{"phrase":"paleoclimate data","zh":"古气候数据"},{"phrase":"ancient paleoclimate","zh":"远古气候"}],"forms":[{"label":"单数","form":"paleoclimate"},{"label":"复数","form":"paleoclimates"},{"label":"形容词","form":"paleoclimatic"},{"label":"学科名词","form":"paleoclimatology"},{"label":"加冠词形式","form":"a paleoclimate"},{"label":"研究对象形式","form":"the paleoclimate of a region"}],"derivatives":[{"word":"paleoclimatic","pos":"adj.","zh":"由「古气候」加形容词词尾构成，义为「古气候的」"},{"word":"paleoclimatology","pos":"n.","zh":"由「古气候」加表示学科的名词尾构成，义为「古气候学」"},{"word":"paleoclimatologist","pos":"n.","zh":"由古气候学名词加表示研究者的词尾构成，义为「古气候学家」"},{"word":"climatology","pos":"n.","zh":"由「气候」加表示学科的名词尾构成，义为「气候学」"},{"word":"climate","pos":"n.","zh":"由同一希腊词干经拉丁语进入英语，义为「气候」"}],"senses":[{"no":"01","title":"Climate of the distant past","titleCN":"遥远过去的气候","definition":"the overall weather conditions of a period long before instrumental records","definitionCN":"仪器记录出现很久之前某一时期的总体天气状况","example":"The paleoclimate of the Jurassic was far warmer than today.","exampleCN":"侏罗纪的古气候远比今天温暖。","why":"The first half of the word means ancient, so the noun begins as climate pushed back beyond memory.","whyCN":"这个词的前一半意为「古老」，所以它最初指被推回记忆之外的气候。"},{"no":"02","title":"A specific ancient climate state","titleCN":"某一时期的具体气候状态","definition":"the particular temperature, rainfall and wind pattern that prevailed in a chosen interval","definitionCN":"在某一选定时间段内占主导的具体温度、降水与风型","example":"The paleoclimate of that basin was dry and windy.","exampleCN":"那个盆地在当时的古气候干燥多风。","why":"Once a time window is fixed, the word stops naming a vague past and names one describable state.","whyCN":"一旦时间窗口固定，这个词就不再指模糊的过去，而指一个可描述的状态。"},{"no":"03","title":"An object of scientific study","titleCN":"学科研究对象","definition":"the subject matter that paleoclimatologists reconstruct and compare","definitionCN":"古气候学家加以重建与比较的研究对象","example":"Paleoclimate is the central object of study in this laboratory.","exampleCN":"古气候是这间实验室的核心研究对象。","why":"A field needs a name for what it studies, and the noun becomes that name.","whyCN":"一个学科需要为它所研究的东西命名，这个词就成了那个名字。"},{"no":"04","title":"A preserved ancient record","titleCN":"留存的古气候记录","definition":"the traces of old climate kept in ice, sediment, tree rings or fossils","definitionCN":"保存在冰、沉积物、树木年轮或化石中的旧气候痕迹","example":"Tree rings preserve a paleoclimate record spanning three centuries.","exampleCN":"树木年轮保存着跨越三个世纪的古气候记录。","why":"Because the climate itself is gone, the word often shifts to the material that still carries its signal.","whyCN":"气候本身已经消失，因此这个词常转到仍然携带其信号的材料上。"},{"no":"05","title":"A simulated ancient climate","titleCN":"模拟出的古气候","definition":"a climate of the past produced by a computer model rather than measured directly","definitionCN":"由计算机模型生成而非直接测量得到的过去气候","example":"The simulated paleoclimate shows a sudden cooling at the poles.","exampleCN":"模拟出的古气候显示两极曾突然变冷。","why":"Models produce a climate that never leaves a direct reading, so the same noun covers the output.","whyCN":"模型产生的气候从未留下直接读数，因此同一个名词也指这种输出。"},{"no":"06","title":"Regional difference in ancient climate","titleCN":"区域古气候差异","definition":"the contrast between the ancient climates of different regions at the same time","definitionCN":"同一时期不同地区古代气候之间的差别","example":"Regional paleoclimate differs sharply between the coast and the interior.","exampleCN":"沿海与内陆的区域古气候差异很大。","why":"Climate is always uneven, so the word multiplies into regional versions that must be compared.","whyCN":"气候从来不均匀，于是这个词分化为必须相互比较的区域版本。"},{"no":"07","title":"Climate of another planet","titleCN":"其他行星古气候","definition":"the ancient climate of a world other than Earth, inferred from its surface and atmosphere","definitionCN":"从地表与大气推断出的地球以外世界的古代气候","example":"Mars has its own paleoclimate, written in ice and dust layers.","exampleCN":"火星有自己的古气候，写在冰层与尘层里。","why":"The prefix means ancient rather than earthly, so planetary scientists can borrow the word freely.","whyCN":"前缀只表示「古老」而不表示「地球」，因此行星科学家可以自由借用这个词。"},{"no":"08","title":"An ancient baseline for comparison","titleCN":"作对照基准的古气候","definition":"a past climate used as a reference against which present or modelled conditions are judged","definitionCN":"用来衡量当前状况或模型状况的过去气候参照","example":"The modern climate serves as a paleoclimate benchmark for the model.","exampleCN":"现代气候充当该模型的古气候基准。","why":"Comparison needs a fixed older state, and the noun takes on the role of the yardstick.","whyCN":"比较需要一个固定的较旧状态，这个词便承担起尺子的角色。"}],"etymology":{"intro":{"en":"Paleoclimate joins Greek palaios, ancient, to Greek klima, a slope or zone, the word that reached English as climate through Latin clima. Paleo- became a scientific prefix in the nineteenth century, and the whole word belongs to the twentieth century; the exact year of first use is uncertain.","cn":"这个词把希腊语「palaios」「古老」与希腊语「klima」「倾斜、地带」结合起来，后者经拉丁语「clima」进入英语作「climate」。前缀在十九世纪成为科学构词成分，整词属于二十世纪，确切首见年代不确定。"},"items":[{"era":"GREEK PALAIOS","en":"Palaios meant ancient or long ago, and it became the first element of many scientific words.","cn":"这个词意为古老的、很久以前的，后来成为许多科学词的第一成分。"},{"era":"GREEK KLIMA","en":"Klima first named a slope or a zone of the earth, because the angle of the sun was thought to shape each region.","cn":"这个词最初指斜坡或地表的地带，因为太阳的角度被认为塑造了每个区域。"},{"era":"LATIN CLIMA","en":"Latin took klima as clima, keeping the sense of a zone and the conditions that went with it.","cn":"拉丁语把这个希腊词取作「clima」，保留了地带以及与之相伴的状况之意。"},{"era":"ENGLISH CLIMATE","en":"English climate descends from Latin clima and gradually narrowed to the weather of a region.","cn":"英语的「climate」源自拉丁语「clima」，逐渐收窄为某一地区的天气。"},{"era":"PALEO AS A PREFIX","en":"In the nineteenth century paleo- became a productive scientific prefix meaning ancient or prehistoric.","cn":"十九世纪，这个表示「古老」的成分成为能产的科技术语前缀，义为远古的。"},{"era":"TWENTIETH CENTURY WORD","en":"The whole word paleoclimate is a twentieth-century formation; the exact year of first use is uncertain.","cn":"整词「paleoclimate」是二十世纪的构造，确切首见年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like paleoclimate; the second group names neighbouring ideas of ancient environments and climate records.","cn":"第一组在形音上与「paleoclimate」相近；第二组是与「古环境、气候记录」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"paleoclimatic","ipa":"/ˌpeɪliəˈklaɪmətɪk/","tag":"same root","definition":"The adjective meaning of or relating to an ancient climate.","definitionCN":"指与古气候有关的形容词。"},{"word":"paleoclimatology","ipa":"/ˌpeɪliəˌklaɪməˈtɒlədʒi/","tag":"same root","definition":"The science that reconstructs ancient climates from natural records.","definitionCN":"指从自然记录重建古代气候的学科。"},{"word":"paleoclimatologist","ipa":"/ˌpeɪliəˌklaɪməˈtɒlədʒɪst/","tag":"same root","definition":"A researcher who works in that science.","definitionCN":"指从事这门学科的研究者。"},{"word":"climate","ipa":"/ˈklaɪmət/","tag":"same root","definition":"The long-term weather pattern of a region, the second half of the compound.","definitionCN":"指一个地区的长期天气型，是复合词的后一半。"},{"word":"paleoecology","ipa":"/ˌpeɪliəˈkɒlədʒi/","tag":"different root","definition":"The study of ancient ecosystems; it shares the prefix but not the climate element.","definitionCN":"指对古代生态系统的研究；共用前缀，但不含气候成分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"past climate","ipa":"/pɑːst ˈklaɪmət/","tag":"near meaning","definition":"A plainer phrase for climate before the present, without the scientific prefix.","definitionCN":"指当前之前的气候，说法更朴素，不带科学前缀。"},{"word":"paleoenvironment","ipa":"/ˌpeɪliənˈvaɪrənmənt/","tag":"near meaning","definition":"The whole ancient setting, including land, water and air, of which climate is one part.","definitionCN":"指完整的古代环境，包括陆地、水与空气，气候只是其中一部分。"},{"word":"proxy record","ipa":"/ˈprɒksi ˈrekɔːd/","tag":"near meaning","definition":"A natural archive such as ice or sediment that stands in for direct measurements.","definitionCN":"指冰、沉积物等代替直接测量的自然档案。"},{"word":"climate history","ipa":"/ˈklaɪmət ˈhɪstəri/","tag":"near meaning","definition":"The sequence of climates through time, close to the recorded sense of the word.","definitionCN":"指气候随时间变化的序列，接近这个词的记录义。"},{"word":"climate model","ipa":"/ˈklaɪmət ˈmɒdl/","tag":"near meaning","definition":"A computer simulation of climate, including versions run for ancient periods.","definitionCN":"指气候的计算机模拟，也包括为古代时期运行的版本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Greek pieces inside the word, its real records and its real research phrases.","cn":"正常联想使用这个词内部的希腊成分、真实记录与真实研究搭配。"},"normal":[{"en":"Paleo- means ancient and climate means climate, so the word says ancient climate outright.","cn":"前成分意为「古老」，后成分意为「气候」，词义直接就是古气候。"},{"en":"Greek palaios gave the ancient half, and Greek klima, a zone, gave the climate half.","cn":"希腊语的「palaios」给出「古老」那一半，希腊语的「klima」「地带」给出「气候」那一半。"},{"en":"A paleoclimate record is read from ice cores, tree rings, corals and lake sediment.","cn":"古气候记录是从冰芯、树木年轮、珊瑚与湖泊沉积物中读出来的。"},{"en":"Regional paleoclimate reminds you that one date can hold several different climates.","cn":"区域古气候提醒你，同一个年代可以有好几种不同的气候。"},{"en":"Paleoclimatology and paleoclimatologist are the science and the person built on the same stem.","cn":"古气候学与古气候学家是同一词干上长出的学科与人。"}],"abstract":[{"en":"A paleoclimate is a climate with no thermometer, read from what the earth kept by accident.","cn":"古气候是一种没有温度计的气候，只能从大地偶然留下的东西里读。"},{"en":"Ice remembers air the way paper remembers ink, and the word names that memory as climate.","cn":"冰记住空气，就像纸记住墨，而这个词把那段记忆称作气候。"},{"en":"Every model of the future is checked against a paleoclimate, a past used as a ruler.","cn":"每一个关于未来的模型都要对照一个古气候，把过去当作尺子。"}]},"examples":[{"en":"Researchers used tree rings to infer the paleoclimate of the plateau.","cn":"研究人员用树木年轮推断高原的古气候。"},{"en":"The model reproduces the paleoclimate of the last glacial maximum.","cn":"该模型重现了末次冰盛期的古气候。"},{"en":"Mars missions search for evidence of a warmer paleoclimate.","cn":"火星探测任务在寻找更温暖古气候的证据。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「佩里欧 克莱美特」——「佩里欧」听成「怕离欧」，远古的欧陆早已远离：古气候。","word":"paleoclimate"},"root":"希腊语「palaios」「古老」加希腊语「klima」「倾斜、地带」，后者经拉丁语「clima」进入英语作「climate」；「paleo-」是十九世纪的科学构词成分，整词属二十世纪，确切首见年代不确定。","sensesIntro":{"en":"Eight senses move from a distant climate to a fixed ancient state, a field of study, a preserved record, a simulated output, a regional contrast, another planet and a baseline for comparison.","cn":"八个义项从遥远气候走向某一固定古代状态、学科对象、留存记录、模拟输出、区域差异、其他行星，以及用作比较的基准。"},"semanticMap":{"core":{"en":"CORE IMAGE: a drill lifts an ice core and the bubbles inside it hold air from a hundred thousand years ago.","cn":"核心意象：钻机提上一截冰芯，里面的气泡封着十万年前的空气。"},"chain":["ANCIENT AIR","A FIXED PERIOD","PROXY EVIDENCE","COMPUTER MODEL","REGIONAL PATTERN","OTHER PLANET"],"branches":[{"senses":"01","en":"THE DISTANT CLIMATE: weather pushed back beyond any thermometer or written log.","cn":"遥远气候：被推到任何温度计与文字记录之外的天气。"},{"senses":"02","en":"THE FIXED STATE: one chosen interval with its own temperature, rain and wind.","cn":"固定状态：一个选定的时间段，带着自己的温度、降水与风。"},{"senses":"03 · 04","en":"THE SCIENCE AND ITS EVIDENCE: what the field studies, and the ice, rings and sediment that carry it.","cn":"学科与证据：该领域研究的东西，以及携带它的冰、年轮与沉积物。"},{"senses":"05 · 08","en":"THE MODEL AND THE RULER: a simulated past climate, and a past climate used to judge the present.","cn":"模型与尺子：模拟出的过去气候，以及用来衡量当下的过去气候。"},{"senses":"06 · 07","en":"THE UNEVEN AND THE ALIEN: one date with different regional climates, and a climate beyond Earth.","cn":"不均匀与异星：同一年代的不同区域气候，以及地球之外的气候。"}]},"affixes":{"intro":{"en":"Paleoclimate is built from two Greek elements that English still uses to make new technical words.","cn":"这个词由两个希腊成分构成，英语至今仍用它们造新的技术词。"},"latinIntro":{"en":"Greek klima passed into Latin as clima before English took it, so Latin clima belongs to this family.","cn":"希腊语「klima」先进入拉丁语作「clima」，英语才借用，因此拉丁语「clima」属于这一族。"},"items":[{"word":"palaios","structure":"Greek adjective","meaning":"ancient, long ago","meaningCN":"古老的；很久以前的","example":"The word supplied the ancient half of the compound.","exampleCN":"这个词提供了复合词中表示「古老」的那一半。"},{"word":"klima","structure":"Greek noun","meaning":"slope, zone of the earth","meaningCN":"斜坡；地表地带","example":"The zone word later became the climate word.","exampleCN":"这个表示地带的词后来变成了表示气候的词。"},{"word":"clima","structure":"Latin noun from Greek","meaning":"zone, region, climate","meaningCN":"地带；区域；气候","example":"Latin carried the Greek zone word into Europe.","exampleCN":"拉丁语把这个希腊地带词带到了欧洲。"},{"word":"climate","structure":"English noun from Latin clima","meaning":"long-term weather of a region","meaningCN":"一个地区的长期天气","example":"It forms the second half of the compound.","exampleCN":"它构成复合词的后一半。"},{"word":"paleo-","structure":"Greek combining form","meaning":"ancient, prehistoric","meaningCN":"古老的；史前的","example":"The prefix marks the great age of the subject.","exampleCN":"这个前缀标出研究对象的久远年代。"},{"word":"paleoclimate","structure":"English compound","meaning":"ancient climate","meaningCN":"古气候","example":"The compound is the ordinary technical name.","exampleCN":"这个复合词是普通的专业名称。"},{"word":"paleoclimatic","structure":"English adjective","meaning":"relating to an ancient climate","meaningCN":"与古气候有关的","example":"The adjective describes data or evidence.","exampleCN":"这个形容词用来描述数据或证据。"},{"word":"paleoclimatology","structure":"English noun","meaning":"the science of ancient climates","meaningCN":"古气候学","example":"The suffix turns the subject into a field.","exampleCN":"词尾把研究对象变成一个学科。"},{"word":"-logy","structure":"Greek suffix","meaning":"study of","meaningCN":"……学","example":"It builds the name of the discipline.","exampleCN":"它构成学科的名称。"}],"latinEntries":[{"word":"clima","structure":"Latin noun from Greek klima","meaning":"zone, region, climate","meaningCN":"地带；区域；气候"}],"derivatives":[{"word":"paleoclimatic","pos":"adj.","zh":"由「古气候」加形容词词尾构成，义为「古气候的」"},{"word":"paleoclimatology","pos":"n.","zh":"由「古气候」加表示学科的名词尾构成，义为「古气候学」"},{"word":"paleoclimatologist","pos":"n.","zh":"由古气候学名词加表示研究者的词尾构成，义为「古气候学家」"},{"word":"climatology","pos":"n.","zh":"由「气候」加表示学科的名词尾构成，义为「气候学」"},{"word":"climate","pos":"n.","zh":"由同一希腊词干经拉丁语而来，义为「气候」"}]}},{"word":"climate reconstruction","ipa_uk":"/ˈklaɪmət ˌriːkənˈstrʌkʃn/","ipa_us":"/ˈklaɪmət ˌriːkənˈstrʌkʃn/","definition_zh":"气候重建；依据代用资料复原过去气候的工作及其结果","definition_en":"the work of rebuilding the climate of a past period from proxy evidence, or the series produced by that work","core_image":"长桌上摊着年轮切片、冰芯管与珊瑚薄片，一只手把散落的点连成一条起伏的曲线","scene":"实验室的长桌上摊着年轮切片、冰芯管与珊瑚薄片，研究员把散落的点连成一条曲线。A climate reconstruction turns scattered proxies into one long temperature curve.","sceneCN":"这里指把零散证据复原成过去气候的工作（第 1 个义项：重建工作）；句意为一次气候重建把分散的代用资料接成一条长长的温度曲线。图中可辨识物件：年轮切片、冰芯管、珊瑚薄片、坐标纸。","pos":[{"tag":"n.","zh":"气候重建；复原过去气候的工作与结果"}],"collocations":[{"phrase":"a climate reconstruction","zh":"一次气候重建"},{"phrase":"climate reconstruction method","zh":"气候重建方法"},{"phrase":"regional climate reconstruction","zh":"区域气候重建"},{"phrase":"global climate reconstruction","zh":"全球气候重建"},{"phrase":"high-resolution climate reconstruction","zh":"高分辨率气候重建"},{"phrase":"climate reconstruction data","zh":"气候重建数据"},{"phrase":"test a climate reconstruction","zh":"检验一次气候重建"}],"forms":[{"label":"单数","form":"climate reconstruction"},{"label":"复数","form":"climate reconstructions"},{"label":"复合形容词","form":"climate-reconstruction"},{"label":"相关动词","form":"reconstruct"},{"label":"相关名词","form":"reconstruction"},{"label":"加冠词形式","form":"a climate reconstruction"}],"derivatives":[{"word":"reconstruct","pos":"v.","zh":"由表示「再次」的前缀加「建造」的动词构成，义为「重建；复原」"},{"word":"reconstruction","pos":"n.","zh":"由重建动词加表示动作结果的名词尾构成，义为「重建；重建物」"},{"word":"reconstructive","pos":"adj.","zh":"由重建动词加形容词词尾构成，义为「重建的；复原性的」"},{"word":"climate","pos":"n.","zh":"由同一希腊词干经拉丁语而来，义为「气候」"},{"word":"proxy","pos":"n.","zh":"指代替直接测量使用的代用资料，是重建工作的证据来源"}],"senses":[{"no":"01","title":"The work of rebuilding a past climate","titleCN":"重建工作","definition":"the research process of assembling evidence and methods to recover the climate of a past period","definitionCN":"汇集证据与方法以复原某一过去时期气候的研究过程","example":"The climate reconstruction took five years and three field seasons.","exampleCN":"这次气候重建花了五年和三个野外季节。","why":"The noun names the activity first, because the phrase literally describes building again something that no longer exists.","whyCN":"这个名词首先指活动，因为该短语字面上就是把已经不存在的东西再次建造起来。"},{"no":"02","title":"The resulting series","titleCN":"重建结果序列","definition":"the ordered sequence of past temperatures or rainfall values produced by the work","definitionCN":"由重建工作产出的过去温度或降水数值的有序序列","example":"The published climate reconstruction runs from the tenth century to the present.","exampleCN":"发表的那条气候重建序列从十世纪一直延续到今天。","why":"A finished reconstruction is a line of numbers through time, so the same noun names the output.","whyCN":"完成的重建是一条贯穿时间的数字曲线，因此同一个名词也指成果。"},{"no":"03","title":"A proxy-based method","titleCN":"代用资料方法","definition":"a technique that converts tree rings, ice, corals or sediments into climate information","definitionCN":"把树木年轮、冰、珊瑚或沉积物转成气候信息的技术","example":"The team used a climate reconstruction built on tree rings.","exampleCN":"这个团队采用了一种建立在树木年轮上的气候重建。","why":"Since no thermometer reaches the past, the phrase often labels the method that substitutes natural archives for instruments.","whyCN":"没有温度计能抵达过去，因此这个短语常指用自然档案替代仪器的方法。"},{"no":"04","title":"A regional reconstruction","titleCN":"区域重建","definition":"a reconstruction limited to one region, such as a basin, a coast or a plateau","definitionCN":"限于一个区域的重建，如某个盆地、海岸或高原","example":"Their regional climate reconstruction covers the whole Mediterranean basin.","exampleCN":"他们的区域气候重建覆盖整个地中海盆地。","why":"Evidence is local, so the phrase is routinely narrowed to a named area before it is widened.","whyCN":"证据是局地的，所以这个短语常先收窄到某个具体地区，再向外推广。"},{"no":"05","title":"A global reconstruction","titleCN":"全球重建","definition":"a reconstruction that merges records from many regions into a single world-wide picture","definitionCN":"把许多地区的记录并成一幅全球图景的重建","example":"A global climate reconstruction combines records from every continent.","exampleCN":"一次全球气候重建把各大洲的记录合并起来。","why":"One region cannot answer a planetary question, so the phrase scales up to the whole globe.","whyCN":"一个区域回答不了行星尺度的问题，于是这个短语扩展到整个地球。"},{"no":"06","title":"A year-by-year reconstruction","titleCN":"多年分辨率重建","definition":"a reconstruction fine enough to give one value for each year or each season","definitionCN":"精细到每年或每季给出一个数值的重建","example":"The annual climate reconstruction resolves every single year.","exampleCN":"这条年度气候重建能分辨每一年。","why":"Resolution is the quality that matters most, so the phrase is modified by the time step it can resolve.","whyCN":"分辨率是最要紧的品质，因此这个短语常受它能分辨的时间步长修饰。"},{"no":"07","title":"One member of an ensemble","titleCN":"多套重建中的一套","definition":"a single reconstruction among several that differ in proxies, methods or assumptions","definitionCN":"在代用资料、方法或假设上有所不同的若干重建中的一套","example":"Each climate reconstruction in the set uses slightly different proxies.","exampleCN":"这一组里的每一套气候重建都使用了略有差异的代用资料。","why":"Science rarely trusts one curve, so the phrase is counted and compared as one member of a family.","whyCN":"科学很少只信一条曲线，因此这个短语会被当作一族中的一员来计数与比较。"},{"no":"08","title":"A reconstruction used to test models","titleCN":"用于检验模型的重建","definition":"a past-climate series employed as a target against which climate simulations are judged","definitionCN":"用作目标、用来评判气候模拟结果的过去气候序列","example":"The model was checked against a climate reconstruction of the last millennium.","exampleCN":"该模型对照过去一千年的气候重建接受了检验。","why":"A simulation needs an independent past to beat or match, and the phrase supplies the yardstick.","whyCN":"模拟需要一个独立的过去来比较，这个短语就提供了那把尺子。"}],"etymology":{"intro":{"en":"The phrase joins climate, from Greek klima through Latin clima, to reconstruction, from Latin struere, to pile up, through construere, to build, plus re-, again, and -ion, a noun ending. The whole phrase is a twentieth-century formation; the exact year of first use is uncertain.","cn":"这个短语把「climate」与「reconstruction」接在一起：前者从希腊语「klima」经拉丁语「clima」而来；后者来自拉丁语「struere」「堆起」，经「construere」「建造」，再加表示「再次」的前缀与名词词尾。整短语是二十世纪构造，确切首见年代不确定。"},"items":[{"era":"GREEK KLIMA","en":"Klima named a slope or a zone of the earth, since the sun's angle was thought to shape each region.","cn":"这个词指斜坡或地表的地带，因为太阳角度被认为塑造了每个区域。"},{"era":"LATIN CLIMA TO ENGLISH CLIMATE","en":"Latin clima kept the zone sense, and English climate slowly narrowed to the weather of a region.","cn":"拉丁语「clima」保留了地带之意，英语「climate」则慢慢收窄为某一地区的天气。"},{"era":"LATIN STRUERE","en":"Struere meant to pile up or arrange, the plain act of stacking material into a structure.","cn":"这个词意为堆起、排列，即把材料堆成结构的朴素动作。"},{"era":"LATIN CONSTRUERE","en":"Construere added the idea of bringing pieces together, and English construct came from it.","cn":"这个词加上了把各件东西聚拢的意思，英语的「construct」由此而来。"},{"era":"RE- AND -ION","en":"The prefix re- means again and the ending -ion makes a noun of action or result, giving reconstruction.","cn":"前缀表示「再次」，词尾把动作或结果变成名词，于是有了「reconstruction」。"},{"era":"TWENTIETH CENTURY PHRASE","en":"The full phrase climate reconstruction belongs to the twentieth century; the exact year of first use is uncertain.","cn":"完整的短语「climate reconstruction」属于二十世纪，确切首见年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like climate reconstruction; the second group names neighbouring ideas of past-climate evidence and model testing.","cn":"第一组在形音上与「climate reconstruction」相近；第二组是与「过去气候证据、模型检验」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reconstruction","ipa":"/ˌriːkənˈstrʌkʃn/","tag":"same root","definition":"The act or result of building something again, the noun inside the phrase.","definitionCN":"指再次建造的动作或结果，是短语内部的名词。"},{"word":"reconstruct","ipa":"/ˌriːkənˈstrʌkt/","tag":"same root","definition":"To build again from evidence, the verb behind the phrase.","definitionCN":"指依据证据重新构建，是短语背后的动词。"},{"word":"reconstructive","ipa":"/ˌriːkənˈstrʌktɪv/","tag":"same root","definition":"Serving to rebuild, often used of surgery or of historical work.","definitionCN":"指用于重建的，常用于外科手术或历史工作。"},{"word":"construction","ipa":"/kənˈstrʌkʃn/","tag":"different root sense","definition":"The act of building, without the idea of doing it a second time.","definitionCN":"指建造的动作，但不含「再一次」的意思。"},{"word":"climate","ipa":"/ˈklaɪmət/","tag":"same root","definition":"The long-term weather of a region, the first half of the phrase.","definitionCN":"指一个地区的长期天气，是短语的前一半。"}]},{"heading":"NEAR MEANING","entries":[{"word":"proxy record","ipa":"/ˈprɒksi ˈrekɔːd/","tag":"near meaning","definition":"A natural archive that stands in for direct climate measurement.","definitionCN":"指代替直接气候测量的自然档案。"},{"word":"paleoclimate","ipa":"/ˌpeɪliəˈklaɪmət/","tag":"near meaning","definition":"The ancient climate itself, which a reconstruction aims to recover.","definitionCN":"指古代气候本身，正是重建工作要复原的对象。"},{"word":"climate history","ipa":"/ˈklaɪmət ˈhɪstəri/","tag":"near meaning","definition":"The sequence of past climates, close to the result sense of the phrase.","definitionCN":"指过去气候的序列，接近这个短语的结果义。"},{"word":"hindcast","ipa":"/ˈhaɪndkɑːst/","tag":"near meaning","definition":"A model run aimed at a past period, the operation that consumes a reconstruction.","definitionCN":"指针对过去时段运行模型，正是使用重建结果的操作。"},{"word":"climate reanalysis","ipa":"/ˈklaɪmət ˌriːˈænələsɪs/","tag":"near meaning","definition":"A reconstruction of recent climate built by combining observations with models.","definitionCN":"指把观测与模型结合、重建近代气候的产品。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the literal pieces of the phrase, its real evidence and its real modelling use.","cn":"正常联想使用这个短语的字面成分、真实证据与真实建模用途。"},"normal":[{"en":"Climate plus reconstruction: you build the weather of the past a second time from what it left behind.","cn":"气候加重建：用过去留下的东西，把当年的天气再建一次。"},{"en":"The Latin struere meant to pile up, which is exactly what a reconstruction does with dated points.","cn":"拉丁语的「struere」意为堆起，而重建正是把有年代的散点堆叠起来。"},{"en":"A climate reconstruction is usually built from tree rings, ice cores, corals and lake mud.","cn":"气候重建通常由树木年轮、冰芯、珊瑚与湖泥搭成。"},{"en":"High-resolution climate reconstruction is the phrase used when every year can be told apart.","cn":"当每一年都能分辨时，用的说法就是高分辨率气候重建。"},{"en":"A reconstruction of the last millennium is the standard target for testing climate models.","cn":"过去一千年的重建是检验气候模型的标准靶子。"}],"abstract":[{"en":"A reconstruction is a bridge built from both ends: evidence from the past, questions from the present.","cn":"重建是一座从两端搭起的桥：一端是过去的证据，一端是现在的问题。"},{"en":"The past left no thermometer, only scraps; reconstruction is the act of reading a line into those scraps.","cn":"过去没有留下温度计，只留下碎片；重建就是把这些碎片读成一条线。"},{"en":"Each curve is a second building of something that can never be visited again.","cn":"每条曲线都是对一座再也无法到访的建筑的二次建造。"}]},"examples":[{"en":"The climate reconstruction relies on corals from the tropical Pacific.","cn":"这次气候重建依靠热带太平洋的珊瑚。"},{"en":"They compared every climate reconstruction available for the last two thousand years.","cn":"他们比较了过去两千年所有可用的气候重建。"},{"en":"A good climate reconstruction must state its uncertainty clearly.","cn":"一份好的气候重建必须清楚说明自身的不确定性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「克莱美特 瑞肯斯特拉克申」——气候被拆成零件，再按年代重新搭回去：气候重建。","word":"climate reconstruction"},"root":"「climate」源于希腊语「klima」「倾斜、地带」，经拉丁语「clima」进入英语；「reconstruction」来自拉丁语「struere」「堆起、建造」，经「construere」「堆在一起、建造」得「construct」，再加表示「再次」的前缀与名词词尾；整短语属二十世纪，确切首见年代不确定。","sensesIntro":{"en":"Eight senses move from the work itself to its output, its proxy method, a region, the globe, a yearly resolution, one member of an ensemble, and a yardstick for models.","cn":"八个义项从重建工作本身走向它的成果、代用资料方法、一个区域、全球、逐年分辨率、多套中的一套，以及检验模型的尺子。"},"semanticMap":{"core":{"en":"CORE IMAGE: scattered dated points on a long table are joined into one temperature curve.","cn":"核心意象：长桌上散落的有年代的点，被接成一条温度曲线。"},"chain":["SCATTERED PROXIES","DATED POINTS","JOINED CURVE","REGIONAL COVERAGE","GLOBAL GRID","MODEL CHECK"],"branches":[{"senses":"01","en":"THE WORK: hands and methods assemble evidence until a past climate can be stated.","cn":"重建工作：双手与方法汇集证据，直到过去的气候可以被陈述。"},{"senses":"02 · 03","en":"THE CURVE AND THE METHOD: the finished series, and the proxy technique that produced it.","cn":"曲线与方法：完成的序列，以及产出它的代用资料技术。"},{"senses":"04 · 05","en":"THE LOCAL AND THE PLANETARY: one basin filled in, then every continent joined together.","cn":"局地与行星：先填满一个盆地，再把各大洲接成整体。"},{"senses":"06 · 07","en":"THE FINE AND THE MANY: a year-by-year line, and one member among several competing lines.","cn":"精细与多套：逐年的曲线，以及若干竞争曲线中的一套。"},{"senses":"08","en":"THE YARDSTICK: the reconstructed past becomes the target a simulation must match.","cn":"尺子：被重建的过去成为模拟必须对上的目标。"}]},"affixes":{"intro":{"en":"Climate reconstruction joins a Greek-derived climate word to a Latin-derived building word and a noun ending.","cn":"这个短语把希腊来源的「气候」词、拉丁来源的「建造」词与一个名词词尾接在一起。"},"latinIntro":{"en":"Latin supplies clima for climate, struere and construere for building, and the prefix and ending that make reconstruction.","cn":"拉丁语提供了表示气候的「clima」、表示建造的「struere」与「construere」，以及构成「重建」的前缀与词尾。"},"items":[{"word":"klima","structure":"Greek noun","meaning":"slope, zone","meaningCN":"斜坡；地带","example":"The zone word became the climate word.","exampleCN":"这个地带词后来变成了气候词。"},{"word":"clima","structure":"Latin noun from Greek","meaning":"zone, region, climate","meaningCN":"地带；区域；气候","example":"Latin carried the word into English usage.","exampleCN":"拉丁语把这个词带进了英语的用法。"},{"word":"climate","structure":"English noun from Latin","meaning":"long-term weather of a region","meaningCN":"一个地区的长期天气","example":"It is the first half of the phrase.","exampleCN":"它是这个短语的前一半。"},{"word":"struere","structure":"Latin verb","meaning":"to pile up, arrange","meaningCN":"堆起；排列","example":"The verb names the act of stacking material.","exampleCN":"这个动词指把材料堆叠起来的动作。"},{"word":"construere","structure":"Latin verb from struere","meaning":"to build, put together","meaningCN":"建造；拼合","example":"English construct descends from this verb.","exampleCN":"英语的「construct」源自这个动词。"},{"word":"re-","structure":"Latin prefix","meaning":"again, back","meaningCN":"再次；回","example":"It marks the second building of the same thing.","exampleCN":"它标出对同一事物的第二次建造。"},{"word":"-ion","structure":"Latin noun ending","meaning":"act or result","meaningCN":"动作或结果","example":"It turns the verb into a noun.","exampleCN":"它把动词变成名词。"},{"word":"reconstruction","structure":"English noun","meaning":"a building again","meaningCN":"重建；重建物","example":"It is the second half of the phrase.","exampleCN":"它是这个短语的后一半。"},{"word":"construct","structure":"English verb from construere","meaning":"to build","meaningCN":"建造","example":"The shorter verb sits inside the longer noun.","exampleCN":"较短的动词包含在较长的名词里。"}],"latinEntries":[{"word":"clima","structure":"Latin noun from Greek klima","meaning":"zone, region, climate","meaningCN":"地带；区域；气候"},{"word":"struere","structure":"Latin verb","meaning":"to pile up, arrange","meaningCN":"堆起；排列"},{"word":"construere","structure":"Latin verb from struere","meaning":"to build, put together","meaningCN":"建造；拼合"}],"derivatives":[{"word":"reconstruct","pos":"v.","zh":"由表示「再次」的前缀加「建造」的动词构成，义为「重建；复原」"},{"word":"reconstruction","pos":"n.","zh":"由重建动词加表示动作结果的名词尾构成，义为「重建；重建物」"},{"word":"reconstructive","pos":"adj.","zh":"由重建动词加形容词词尾构成，义为「重建的；复原性的」"},{"word":"climate","pos":"n.","zh":"由同一希腊词干经拉丁语而来，义为「气候」"},{"word":"climatic","pos":"adj.","zh":"由「气候」加形容词词尾构成，义为「气候的」"}]}},{"word":"prevail","ipa_uk":"/prɪˈveɪl/","ipa_us":"/prɪˈveɪl/","definition_zh":"盛行；普遍存在；占上风；获胜；说服","definition_en":"to be widespread or dominant, to win out over opposition, or to persuade someone to act","core_image":"山口的风整日不停，一面旧旗被吹得贴住旗杆，却始终没有倒下","scene":"山口的风整日不停，一面旧旗被吹得贴住旗杆，却始终没有倒下。Westerly winds prevail over the pass for most of the year.","sceneCN":"这里指风与天气长期占主导（第 1 个义项：风与天气盛行）；句意为西风一年中大部分时间控制着这个山口。图中可辨识物件：山口、旧旗、旗杆、被风压弯的草。","pos":[{"tag":"v.","zh":"盛行；普遍存在；占上风；获胜；说服"}],"collocations":[{"phrase":"prevail over","zh":"压倒；胜过"},{"phrase":"prevail against","zh":"在与……的对抗中获胜"},{"phrase":"prevail upon someone","zh":"说服某人"},{"phrase":"prevail in court","zh":"在法庭上胜诉"},{"phrase":"the prevailing wind","zh":"盛行风"},{"phrase":"prevail on someone to act","zh":"劝说某人采取行动"},{"phrase":"a view that prevails","zh":"占上风的看法"}],"forms":[{"label":"动词原形","form":"prevail"},{"label":"第三人称单数","form":"prevails"},{"label":"过去式","form":"prevailed"},{"label":"过去分词","form":"prevailed"},{"label":"现在分词","form":"prevailing"},{"label":"形容词","form":"prevalent"},{"label":"名词","form":"prevalence"}],"derivatives":[{"word":"prevalent","pos":"adj.","zh":"由该动词加形容词词尾构成，义为「盛行的；普遍的」"},{"word":"prevalence","pos":"n.","zh":"由「盛行」的形容词加名词尾构成，义为「盛行；普遍程度」"},{"word":"prevailing","pos":"adj.","zh":"由该动词加形容词词尾构成，义为「占优势的；盛行的」"},{"word":"prevailingly","pos":"adv.","zh":"由「占优势的」形容词加副词词尾构成，义为「占优势地」"},{"word":"avail","pos":"v.","zh":"与拉丁语「valere」同族，经法语进入英语，义为「有用；有帮助」"}],"senses":[{"no":"01","title":"Of wind and weather","titleCN":"风与天气盛行","definition":"to blow steadily or to be the usual weather of a place and season","definitionCN":"指风持续地吹，或成为某地某季的常况","example":"Dry winds prevail across the plateau in winter.","exampleCN":"冬季高原上盛行干燥的风。","why":"The earliest English uses describe forces that hold the air, because prevailing is first about what dominates a place.","whyCN":"英语最早的用法描述控制空气的力量，因为「盛行」首先指在某地占主导。"},{"no":"02","title":"Of customs and ideas","titleCN":"习俗观念普遍存在","definition":"to be widely found or generally accepted among a group of people","definitionCN":"在一群人中广泛存在或被普遍接受","example":"The custom still prevails in the mountain villages.","exampleCN":"这一习俗在山村里仍然盛行。","why":"Once a usage holds a region the way weather does, the verb extends from air to habit.","whyCN":"一旦一种做法像天气那样占住一个地区，这个动词就从空气扩展到习惯。"},{"no":"03","title":"To win an argument","titleCN":"争论中占上风","definition":"to prove stronger than the opposing case in a debate or dispute","definitionCN":"在辩论或争执中证明比对方的主张更强","example":"Common sense prevailed after a long debate.","exampleCN":"经过长时间辩论，常理占了上风。","why":"Being stronger is the core of the Latin verb, and an argument is a contest of strength between claims.","whyCN":"「更强」是拉丁动词的核心，而争论正是各种主张之间的力量较量。"},{"no":"04","title":"To win a contest","titleCN":"较量中取胜","definition":"to defeat opponents in a match, a race or a struggle","definitionCN":"在比赛、竞速或斗争中击败对手","example":"The home side prevailed in the final minutes.","exampleCN":"主队在最后几分钟取胜。","why":"Sport borrowed the legal and military verb for the side that turns out stronger.","whyCN":"体育界借用了这个法律与军事动词，指最终更强的一方。"},{"no":"05","title":"To persuade someone","titleCN":"说服某人","definition":"to bring someone round to a course of action by argument or appeal","definitionCN":"通过论证或请求使某人接受某种做法","example":"She prevailed on the committee to reopen the case.","exampleCN":"她说服委员会重新审理此案。","why":"Persuasion is winning a person over, so the preposition on marks the one who is overcome.","whyCN":"说服就是把一个人争取过来，因此搭配的介词标出被说服的那一方。"},{"no":"06","title":"Of effort that succeeds at last","titleCN":"努力最终奏效","definition":"to succeed after sustained pressure, patience or repeated attempts","definitionCN":"在持续施压、耐心等待或反复尝试之后取得成功","example":"Patience and evidence finally prevailed.","exampleCN":"耐心与证据最终奏效。","why":"The verb can name an impersonal force that wins, even when no person is doing the winning.","whyCN":"这个动词可以指一种非人的力量取胜，即使并没有人在取胜。"},{"no":"07","title":"Of an old rule that outlives its reason","titleCN":"旧制度延续而缘由已失","definition":"to remain in force long after the purpose it once served has disappeared","definitionCN":"在当初的用途消失很久之后仍然有效","example":"The old rule still prevails long after its purpose vanished.","exampleCN":"那条旧规定在用途消失很久后仍然有效。","why":"What prevails simply holds its ground, whether or not anyone can still explain why.","whyCN":"「盛行」的东西只是守住自己的位置，不管还有没有人能解释缘由。"},{"no":"08","title":"To win in a court of law","titleCN":"法律上胜诉","definition":"to succeed in a legal action or to establish a right against the other party","definitionCN":"在法律诉讼中成功，或对另一方确立一项权利","example":"The tenant prevailed in the housing dispute.","exampleCN":"租户在住房纠纷中胜诉。","why":"Legal language keeps the old sense of a stronger claim carrying the day.","whyCN":"法律语言保留了旧义，即更强的主张最终获胜。"}],"etymology":{"intro":{"en":"Prevail comes from Latin prae-, before or beyond, and valere, to be strong or to be worth, forming praevalere, to be stronger. English took it through French in the fourteenth century; the family of valere also includes valid, value and avail.","cn":"这个词来自拉丁语前缀「prae-」「在前、超出」与「valere」「强、有价值」，合成「praevalere」「更强」。英语于十四世纪经法语引入；「valere」的同族词还包括「valid」「value」「avail」。"},"items":[{"era":"LATIN VALERE","en":"Valere meant to be strong or to be worth, and it described health, power and value alike.","cn":"这个词意为强壮或有价值，同时描述健康、力量与价值。"},{"era":"LATIN PRAE-","en":"The prefix prae- meant before or beyond, marking a position ahead of others.","cn":"前缀意为「在前」或「超出」，标出比别人更靠前的位置。"},{"era":"LATIN PRAEVALERE","en":"Prae plus valere gave praevalere, to be stronger, whose past stem is praevaluī.","cn":"前缀加动词得到「praevalere」「更强」，其过去词干为「praevaluī」。"},{"era":"FRENCH AND ENGLISH","en":"Old French carried the verb to English, where it was spelled and pronounced in several ways before settling.","cn":"古法语把这个动词带到英语，其拼写与读音经过几种形式才固定下来。"},{"era":"ENGLISH, FOURTEENTH CENTURY","en":"English used prevail first for holding power or influence, and soon for winning a contest.","cn":"英语最初用这个词表示掌握权力或影响力，很快也用于表示在较量中获胜。"},{"era":"LEGAL AND EVERYDAY","en":"Courts fixed the sense of winning a case, while ordinary speech kept the weather, custom and persuasion senses.","cn":"法庭固定了「胜诉」义，而日常口语保留了天气、习俗与说服诸义。"}]},"similar":{"note":{"en":"The first group looks or sounds like prevail; the second group names neighbouring ideas of dominance, victory and persuasion.","cn":"第一组在形音上与「prevail」相近；第二组是与「支配、取胜、说服」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prevailing","ipa":"/prɪˈveɪlɪŋ/","tag":"same root","definition":"The adjective for what is dominant or most common, as in the prevailing wind.","definitionCN":"指占主导或最常见的形容词，如盛行风。"},{"word":"prevalent","ipa":"/ˈprevələnt/","tag":"same root","definition":"Widespread in a place or at a time, often used of diseases or beliefs.","definitionCN":"指在某地某时广泛存在的，常用于疾病或观念。"},{"word":"prevalence","ipa":"/ˈprevələns/","tag":"same root","definition":"The fact or degree of being widespread.","definitionCN":"指广泛存在的事实或程度。"},{"word":"avail","ipa":"/əˈveɪl/","tag":"same Latin root","definition":"To be useful or helpful; it shares the Latin strength word.","definitionCN":"指有用、有帮助；共用同一个拉丁「强」词。"},{"word":"valor","ipa":"/ˈvælə/","tag":"same Latin root","definition":"Bravery in battle, from the same Latin word for strength.","definitionCN":"指战斗中的勇猛，出自同一个表示力量的拉丁词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dominate","ipa":"/ˈdɒmɪneɪt/","tag":"near meaning","definition":"To hold the most power or influence in a place or situation.","definitionCN":"指在某地或某种情境中掌握最大的权力或影响。"},{"word":"predominate","ipa":"/prɪˈdɒmɪneɪt/","tag":"near meaning","definition":"To be the largest or most noticeable element among others.","definitionCN":"指在其他要素中数量最多或最显著。"},{"word":"triumph","ipa":"/ˈtraɪʌmf/","tag":"near meaning","definition":"To win a decisive victory, often with a sense of celebration.","definitionCN":"指取得决定性胜利，常带庆祝意味。"},{"word":"persuade","ipa":"/pəˈsweɪd/","tag":"near meaning","definition":"To convince someone to believe or do something.","definitionCN":"指说服某人相信或去做某事。"},{"word":"persist","ipa":"/pəˈsɪst/","tag":"near meaning","definition":"To continue in existence or action, close to the sense of an old rule still holding.","definitionCN":"指继续存在或继续行动，接近旧规定仍然有效那一义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin strength word behind prevail, its real family and its fixed phrases.","cn":"正常联想使用这个词背后表示「强」的拉丁词、真实同族词与固定搭配。"},"normal":[{"en":"Praemia and prevail share a Latin idea: the stronger thing stands, and the stronger claim wins.","cn":"奖品与盛行共享一个拉丁观念：更强的东西站住，更强的主张获胜。"},{"en":"The prefix means before or beyond, and the stem means strong, so prevail is to be stronger than what stands in front.","cn":"前缀意为「在前、超出」，词干意为「强」，所以这个词指比挡在前面的东西更强。"},{"en":"Prevail on someone is the fixed pattern for persuasion, with the preposition on before the person.","cn":"劝说某人用的是固定模式，介词放在人前面。"},{"en":"The prevailing wind is the weather phrase, and it is the oldest kind of use.","cn":"盛行风是天气方面的说法，也是最古老的一类用法。"},{"en":"Valid, value and avail all descend from the same Latin word for being strong or worth something.","cn":"有效的、价值与有用都出自同一个表示「强或有价值」的拉丁词。"}],"abstract":[{"en":"Prevailing is not shouting loudest; it is being the thing that is still standing when the wind drops.","cn":"盛行不是喊得最响，而是风停之后仍然立着的那一个。"},{"en":"An old rule prevails because nobody remembers how to remove it, not because it is right.","cn":"旧规定之所以延续，是因为没人记得怎样废除它，而不是因为它正确。"},{"en":"To prevail is to make the world agree with you without having to raise your voice.","cn":"占上风是让世界同意你，而不必提高嗓门。"}]},"examples":[{"en":"Cooler air will prevail over the region by the weekend.","cn":"到周末，较凉的空气将控制这一地区。"},{"en":"The older interpretation prevailed among historians for a century.","cn":"较旧的解释在历史学家中盛行了整整一个世纪。"},{"en":"They tried to prevail on the minister to change the policy.","cn":"他们试图说服部长改变这项政策。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「普瑞威尔」——「普」遍都「瑞」气「威」风，处处占上风：盛行、取胜、说服。","word":"prevail"},"root":"拉丁语「prae-」「在前、超出」加「valere」「强、有价值」构成「praevalere」「更强」，其过去词干为「praevaluī」；英语十四世纪经法语引入；「valere」同族有「valid」「value」「avail」。","sensesIntro":{"en":"Eight senses move from wind holding a place, to a custom being widespread, an argument or contest won, a person persuaded, effort succeeding, an old rule surviving, and a case won in law.","cn":"八个义项从风占住一地，走向习俗广布、争论或较量取胜、说服某人、努力奏效、旧制度延续，以及法律上胜诉。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flag that bends in a steady gale but never falls, because the stronger force holds its ground.","cn":"核心意象：一面旗在稳定的大风里被压弯却从不倒下，因为更强的力量守住了位置。"},"chain":["STEADY WIND","WIDESPREAD HABIT","STRONGER CLAIM","WINNING SIDE","PATIENT EFFORT","LEGAL RULING"],"branches":[{"senses":"01","en":"THE WEATHER: one wind or one kind of weather holds a place for most of the year.","cn":"天气：一种风或一类天气在一年的大部分时间里占住一个地方。"},{"senses":"02 · 07","en":"THE LONG HABIT: a custom spreads widely, and an old rule stays after its reason is gone.","cn":"长久的习惯：习俗广泛流传，旧规定在缘由消失后仍留下。"},{"senses":"03 · 04","en":"THE STRONGER CLAIM: an argument wins out, and a side wins the match.","cn":"更强的主张：一种论点占上风，一方赢下比赛。"},{"senses":"05 · 06","en":"THE OVERCOMING: a person is persuaded, and patient effort succeeds at last.","cn":"争取与奏效：一个人被说服，耐心的努力最终成功。"},{"senses":"08","en":"THE COURT: the stronger legal right carries the case.","cn":"法庭：更强的法律权利赢得案件。"}]},"affixes":{"intro":{"en":"Prevail is a Latin verb built from a prefix of position and a stem of strength, and English keeps both pieces in a whole family.","cn":"这是一个由位置前缀与力量词干构成的拉丁动词，英语在两个成分上都保留了一整族词。"},"latinIntro":{"en":"Latin valere supplies the strength, prae- supplies the advantage, and praevalere joins them into one verb.","cn":"拉丁语「valere」提供力量，「prae-」提供优势，「praevalere」把两者合成一个动词。"},"items":[{"word":"prae-","structure":"Latin prefix","meaning":"before, beyond, in front","meaningCN":"在前；超出；在前面","example":"It marks the position of being ahead of others.","exampleCN":"它标出比别人更靠前的位置。"},{"word":"valere","structure":"Latin verb","meaning":"to be strong, to be worth","meaningCN":"强壮；有价值","example":"The stem carries health, power and worth together.","exampleCN":"这个词干同时带着健康、力量与价值。"},{"word":"praevalere","structure":"Latin verb (past stem praevaluī)","meaning":"to be stronger, prevail","meaningCN":"更强；占优势","example":"The compound verb is the direct source of the English word.","exampleCN":"这个合成动词是英语词的直接来源。"},{"word":"prevail","structure":"English verb through French","meaning":"to be dominant, win, persuade","meaningCN":"盛行；取胜；说服","example":"English shortened the Latin verb into its modern shape.","exampleCN":"英语把这个拉丁动词缩短成现代形态。"},{"word":"prevailing","structure":"English adjective","meaning":"dominant, most common","meaningCN":"占优势的；最常见的","example":"It describes the wind or the mood of a time.","exampleCN":"它描述风或一个时期的风气。"},{"word":"prevalent","structure":"English adjective","meaning":"widespread","meaningCN":"盛行的；普遍的","example":"It applies to diseases, beliefs and customs.","exampleCN":"它适用于疾病、观念与习俗。"},{"word":"prevalence","structure":"English noun","meaning":"the state of being widespread","meaningCN":"盛行；普遍程度","example":"Epidemiologists measure it as a rate.","exampleCN":"流行病学家把它当作一个比率来测量。"},{"word":"-ent","structure":"Latin adjective ending","meaning":"being or doing","meaningCN":"处于……的；做……的","example":"It forms the adjective from the verb stem.","exampleCN":"它从动词词干构成形容词。"},{"word":"-ence","structure":"Latin noun ending","meaning":"state or quality","meaningCN":"状态或性质","example":"It turns the adjective into a noun.","exampleCN":"它把形容词变成名词。"}],"latinEntries":[{"word":"valere","structure":"Latin verb","meaning":"to be strong, be worth","meaningCN":"强壮；有价值"},{"word":"prae-","structure":"Latin prefix","meaning":"before, beyond","meaningCN":"在前；超出"},{"word":"praevalere","structure":"Latin verb (past stem praevaluī)","meaning":"to be stronger, prevail","meaningCN":"更强；占优势"}],"derivatives":[{"word":"prevalent","pos":"adj.","zh":"由该动词加形容词词尾构成，义为「盛行的；普遍的」"},{"word":"prevalence","pos":"n.","zh":"由「盛行」的形容词加名词尾构成，义为「盛行；普遍程度」"},{"word":"prevailing","pos":"adj.","zh":"由该动词加形容词词尾构成，义为「占优势的；盛行的」"},{"word":"avail","pos":"v.","zh":"与拉丁语「valere」同族，经法语进入英语，义为「有用；有帮助」"},{"word":"valid","pos":"adj.","zh":"与拉丁语「valere」同族，义为「有效的；正当的」"}]}},{"word":"proliferate","ipa_uk":"/prəˈlɪfəreɪt/","ipa_us":"/prəˈlɪfəreɪt/","definition_zh":"激增；迅速扩散；增殖；繁殖；增生；使激增","definition_en":"to increase rapidly in number, to spread widely through an area, or to reproduce and multiply","core_image":"浅水塘里起初只有几簇绿藻，几天后整片水面都被覆盖，边缘还不断冒出新芽","scene":"浅水塘起初只有几簇绿藻，三天后整片水面都染成绿色，边缘还在向外蔓延。Algae proliferate across the pond within days.","sceneCN":"这里指数量在短时间内迅速变多并铺开（第 1 个义项：数量迅速激增）；句意为藻类在数日内遍布整个池塘。图中可辨识物件：浅水塘、绿色藻簇、向外扩散的水纹。","pos":[{"tag":"v.","zh":"激增；扩散；增殖；繁殖；使激增"}],"collocations":[{"phrase":"proliferate rapidly","zh":"迅速激增"},{"phrase":"proliferate unchecked","zh":"无节制地蔓延"},{"phrase":"proliferate across the region","zh":"在整个地区蔓延"},{"phrase":"proliferate in warm water","zh":"在温暖水域中大量繁殖"},{"phrase":"proliferate without limit","zh":"无限制地增殖"},{"phrase":"proliferate new vessels","zh":"使新生血管增生"}],"forms":[{"label":"动词原形","form":"proliferate"},{"label":"第三人称单数","form":"proliferates"},{"label":"过去式","form":"proliferated"},{"label":"过去分词","form":"proliferated"},{"label":"现在分词","form":"proliferating"},{"label":"名词","form":"proliferation"}],"derivatives":[{"word":"proliferation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「增殖；激增；扩散」"},{"word":"proliferative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「增殖性的」"},{"word":"proliferating","pos":"adj.","zh":"由现在分词转作形容词，义为「不断增殖的」"},{"word":"proliferator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「增殖者；促增殖物」"}],"senses":[{"no":"01","title":"To rise sharply in number","titleCN":"数量迅速激增","definition":"to increase rapidly in number within a short span of time","definitionCN":"在短时间内数量迅速变多","example":"Online orders proliferate in the weeks before the holiday.","exampleCN":"节前几周，线上订单迅速激增。","why":"The Latin verb first described offspring arriving one after another, and a sudden surge of any countable thing repeats that picture of many new copies.","whyCN":"这个拉丁动词最初描述后代接连出生，任何可计数之物突然涌来，都重复了「新副本大量出现」的画面。"},{"no":"02","title":"To spread quickly through an area","titleCN":"快速扩散蔓延","definition":"to spread over a wide area in a short time","definitionCN":"在短时间内向广大区域铺开","example":"Rumours proliferate across social platforms within hours.","exampleCN":"谣言在数小时内传遍社交平台。","why":"Once copies multiply, they also move outward, so the word covers spatial spread as well as number.","whyCN":"副本一旦增多，也会向外移动，因此这个词既指数目，也指空间上的铺开。"},{"no":"03","title":"To multiply by cell division","titleCN":"细胞增殖","definition":"to increase in number by repeated division of cells","definitionCN":"通过细胞反复分裂而数目增多","example":"The cells proliferate rapidly in the warm culture.","exampleCN":"细胞在温暖的培养液中迅速增殖。","why":"Biology took the word for producing offspring and applied it to single cells producing more of themselves.","whyCN":"生物学把这个表示「产生后代」的词用于单细胞自我复制。"},{"no":"04","title":"To breed and multiply","titleCN":"动植物繁殖增多","definition":"to reproduce and build up a larger population","definitionCN":"繁殖并使种群数量增大","example":"These fish proliferate in shallow, weed-filled ponds.","exampleCN":"这种鱼在长满水草的浅塘里大量繁殖。","why":"Plants and animals were the first subjects of the word, and population growth keeps the original sense alive.","whyCN":"动植物是这个词最早的描述对象，种群增长让本义一直延续。"},{"no":"05","title":"To grow abnormally in tissue","titleCN":"组织异常增生","definition":"to grow beyond the normal amount, especially in body tissue","definitionCN":"尤其指身体组织超出正常范围地生长","example":"Abnormal cells proliferate in the lining of the stomach.","exampleCN":"异常细胞在胃壁内层增生。","why":"When division escapes control, the same multiplying word describes a medical danger rather than healthy growth.","whyCN":"当分裂失去控制，同一个表示「增多」的词就描述医学上的危险，而非健康生长。"},{"no":"06","title":"To flood a medium with copies","titleCN":"文本与信息大量涌现","definition":"to appear in very large numbers as texts, images or reports","definitionCN":"以文本、图像或报道的形式大量出现","example":"Cheap copies of the report proliferate on the web.","exampleCN":"这份报告的廉价副本在网上大量涌现。","why":"Digital copying made the word natural for information, where every duplicate is a new offspring.","whyCN":"数字复制让这个词自然用于信息，因为每一份副本都像一个新后代。"},{"no":"07","title":"To send out new branches","titleCN":"新生分支与血管增生","definition":"to form new shoots, branches or vessels that extend from an existing structure","definitionCN":"从既有结构上长出新枝、新分支或新血管","example":"New vessels proliferate around the damaged tissue.","exampleCN":"新的血管在受损组织周围增生。","why":"Botany supplied the earliest English use, where a plant proliferates by putting out fresh growth.","whyCN":"植物学提供了这个词最早的英语用法：植物靠长出新芽而增殖。"},{"no":"08","title":"To cause to multiply","titleCN":"使增殖（及物）","definition":"to make something increase in number or amount","definitionCN":"使某物的数量或总量增多","example":"A rich medium proliferates the bacteria within hours.","exampleCN":"营养丰富的培养基能在数小时内使细菌大量增殖。","why":"The transitive use adds a cause to the picture: something supplies the conditions, and the copies follow.","whyCN":"及物用法在画面里加了一个原因：某物提供条件，副本便随之增多。"}],"etymology":{"intro":{"en":"Proliferate comes from Latin proles, offspring, and ferre, to carry or bring, through the adjective prolifer, bringing offspring, and the verb proliferare, to produce offspring.","cn":"这个词来自拉丁语「proles」后代与「ferre」携带、产生，先构成形容词「prolifer」带来后代的，再构成动词「proliferare」产生后代、繁殖。"},"items":[{"era":"LATIN PROLES","en":"Proles named offspring and descendants, the young produced by a family or a species.","cn":"这个词指后代与子孙，即家庭或物种所生育的幼体。"},{"era":"LATIN FERRE","en":"Ferre meant to carry, bring or produce, and it supplied the second half of the word.","cn":"这个词意为携带、带来或产生，构成了该词的后半部分。"},{"era":"LATIN PROLIFER","en":"The adjective described a parent or a plant that brings offspring into being.","cn":"这个形容词描述能带来后代的亲体或植物。"},{"era":"LATIN PROLIFERARE","en":"The verb meant to produce offspring and to keep breeding.","cn":"这个动词意为产生后代、不断繁殖。"},{"era":"BOTANY, 19TH CENTURY","en":"English adopted the word through botanical writing, where plants proliferate by producing new growth.","cn":"英语经植物学著作引入这个词，指植物靠长出新枝而增殖。"},{"era":"GENERAL USE, LATE 20TH CENTURY","en":"In the late twentieth century the word widened to any rapid increase, from cells to rumours.","cn":"到二十世纪后期，这个词扩展为泛指任何迅速增多，从细胞到谣言。"}]},"similar":{"note":{"en":"The first group looks like proliferate or shares its stem; the second group names neighbouring ideas of multiplying and spreading.","cn":"第一组在形音上与「proliferate」相近或共享词干；第二组是与「增多、扩散」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"proliferation","ipa":"/prəˌlɪfəˈreɪʃn/","tag":"same root","definition":"The noun for the process of multiplying or spreading.","definitionCN":"指增殖或扩散的过程。"},{"word":"proliferative","ipa":"/prəˈlɪfərətɪv/","tag":"same root","definition":"Adjective describing tissue or cells that keep dividing.","definitionCN":"形容不断分裂的组织或细胞。"},{"word":"proliferator","ipa":"/prəˈlɪfəreɪtə/","tag":"same root","definition":"A person or agent that causes something to multiply.","definitionCN":"指使某物大量增多的人或因素。"},{"word":"proliferous","ipa":"/prəˈlɪfərəs/","tag":"same root","definition":"Bearing many offspring or buds; an older adjective from the same Latin family.","definitionCN":"指多产、多芽的；是同一拉丁词族中较老的形容词。"},{"word":"prolific","ipa":"/prəˈlɪfɪk/","tag":"different root","definition":"Highly productive; its second half comes from Latin facere, to make, not from ferre.","definitionCN":"指多产的；后半出自拉丁语「facere」制造，而不是「ferre」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"multiply","ipa":"/ˈmʌltɪplaɪ/","tag":"near meaning","definition":"To grow in number by natural increase or by repeated copying.","definitionCN":"指因自然增多或反复复制而数量变大。"},{"word":"spread","ipa":"/spred/","tag":"near meaning","definition":"To extend over a wider area or among more people.","definitionCN":"指向更大范围或更多人群扩展。"},{"word":"escalate","ipa":"/ˈeskəleɪt/","tag":"near meaning","definition":"To become more intense or larger, often used of problems and conflict.","definitionCN":"指程度或规模升级，常用于问题与冲突。"},{"word":"mushroom","ipa":"/ˈmʌʃrʊm/","tag":"near meaning","definition":"To grow or appear very quickly, like mushrooms after rain.","definitionCN":"指像雨后蘑菇一样迅速生长或出现。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin offspring image, the real word family and the usual subjects of the verb.","cn":"正常联想使用拉丁语的后代意象、真实同族词与这个词的常见搭配对象。"},"normal":[{"en":"The Latin proles is offspring and ferre is to bring, so proliferate is literally to bring offspring forth.","cn":"拉丁语「proles」是后代，「ferre」是带来：这个词字面上就是「把后代带出来」。"},{"en":"Proliferation, proliferative and proliferous all keep the same picture of new copies.","cn":"增殖、增殖性的与多产的都保留着「新副本不断出现」的画面。"},{"en":"Cells proliferate, weeds proliferate and rumours proliferate: the subject only has to be countable and fast.","cn":"细胞增殖、杂草蔓延、谣言疯传：主语只要可计数且速度快就行。"},{"en":"Proliferate rapidly is the plainest collocation, and it fits algae, orders and copies alike.","cn":"「proliferate rapidly」是最朴素的搭配，藻类、订单与副本都适用。"},{"en":"Botanists used the word before economists did, so a plant putting out shoots is the cleanest picture.","cn":"植物学家比经济学家更早使用这个词，因此植物抽枝是最干净的画面。"}],"abstract":[{"en":"Every duplicate is a child of the original, and the word counts them all at once.","cn":"每一份副本都是原件的孩子，而这个词把它们一次数完。"},{"en":"Rumour proliferates because retelling is breeding; each listener becomes a new parent.","cn":"谣言会蔓延，因为复述就是繁殖；每个听者都成了新的亲本。"},{"en":"Unchecked division is growth in one frame and danger in another, and the word does not judge.","cn":"不受控制的分裂，在一个框架里是生长，在另一个框架里是危险，而这个词不作判断。"}]},"examples":[{"en":"Weeds proliferate once the field is left untended.","cn":"田地一旦无人打理，杂草便迅速蔓延。"},{"en":"False listings proliferate on auction sites before the holidays.","cn":"节前，虚假商品信息在拍卖网站上大量涌现。"},{"en":"Stem cells proliferate under the right chemical signals.","cn":"干细胞在合适的化学信号下增殖。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「普若利福瑞特」——后代一茬接一茬地生出来，数目越滚越大：激增、增殖","word":"proliferate"},"root":"拉丁语「proles」意为后代，加上「ferre」携带、产生，先构成形容词「prolifer」带来后代的，再构成动词「proliferare」产生后代、繁殖；英语十九世纪经植物学引入，二十世纪后期扩为泛指激增。注意同根词「prolific」后半出自「facere」制造，与「ferre」不同。","sensesIntro":{"en":"Eight senses move from pure number to living growth: a sharp rise, wide spread, cell division, breeding, abnormal tissue, a flood of copies, new branches, and a transitive cause.","cn":"八个义项从纯数目走向生命生长：数量激增、广泛扩散、细胞分裂、繁殖增多、组织增生、副本涌现、新生分支，以及及物的使增殖。"},"semanticMap":{"core":{"en":"CORE IMAGE: one patch of algae sends out new shoots until the whole pond is green.","cn":"核心意象：一小片藻类不断分出新芽，直到整片池塘变绿。"},"chain":["OFFSPRING","RAPID INCREASE","WIDE SPREAD","CELL DIVISION","NEW SHOOTS","FLOOD OF COPIES"],"branches":[{"senses":"01","en":"THE PURE SURGE: the number climbs fast, with no stated limit and no stated cause.","cn":"纯数量激增：数目快速上升，既未说明限度，也未说明原因。"},{"senses":"02","en":"THE OUTWARD SPREAD: the same copies also move across space and media.","cn":"向外扩散：同样的副本也在空间与媒介上移动。"},{"senses":"03 · 04","en":"THE LIVING MULTIPLICATION: cells divide, and plants and animals add to their populations.","cn":"生命增殖：细胞分裂，动植物扩大种群。"},{"senses":"05 · 07","en":"THE GROWING BODY: tissue and vessels put out new growth, healthy or not.","cn":"身体生长：组织与血管长出新结构，无论健康与否。"},{"senses":"06 · 08","en":"THE COPY AND THE CAUSE: texts flood a medium, and a cause makes the number rise.","cn":"副本与原因：文本淹没媒介，而某个原因使数目上升。"}]},"affixes":{"intro":{"en":"Proliferate is built from a Latin noun of offspring and a Latin verb of carrying, and its endings are ordinary verb and noun endings.","cn":"这个词由一个表示后代的拉丁名词与一个表示携带的拉丁动词构成，词尾是普通的动词与名词词尾。"},"latinIntro":{"en":"Latin supplies proles, ferre, the adjective prolifer and the verb proliferare; the English forms add only the usual endings.","cn":"拉丁语提供了「proles」「ferre」以及形容词「prolifer」和动词「proliferare」；英语形式只加了常用词尾。"},"items":[{"word":"proles","structure":"Latin noun","meaning":"offspring; descendants","meaningCN":"后代；子孙","example":"The noun names the young of a family or a species.","exampleCN":"这个名词指家庭或物种的幼体。"},{"word":"ferre","structure":"Latin verb","meaning":"to carry; to bring; to produce","meaningCN":"携带；带来；产生","example":"The verb supplies the carrying half of the word.","exampleCN":"这个动词提供了「携带」那一半。"},{"word":"prolifer","structure":"Latin adjective from proles and ferre","meaning":"bringing offspring","meaningCN":"带来后代的","example":"The adjective stands between the noun and the verb.","exampleCN":"这个形容词位于名词与动词之间。"},{"word":"proliferare","structure":"Latin verb from prolifer","meaning":"to produce offspring; to breed","meaningCN":"产生后代；繁殖","example":"The verb is the direct source of the English word.","exampleCN":"这个动词是英语词的直接来源。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or cause","meaningCN":"使……；做……","example":"The ending marks the English verb of action.","exampleCN":"这个词尾标明英语动作动词。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result of multiplying","meaningCN":"增殖的动作或结果","example":"It forms the noun proliferation.","exampleCN":"它构成名词「proliferation」。"},{"word":"-ive","structure":"adjective ending","meaning":"tending to","meaningCN":"有……倾向的","example":"It forms the adjective proliferative.","exampleCN":"它构成形容词「proliferative」。"},{"word":"-ous","structure":"adjective ending","meaning":"full of; having the quality of","meaningCN":"充满……的；具有……性质的","example":"It forms the older adjective proliferous.","exampleCN":"它构成较老的形容词「proliferous」。"}],"latinEntries":[{"word":"proles","structure":"Latin noun","meaning":"offspring, descendants","meaningCN":"后代；子孙"},{"word":"ferre","structure":"Latin verb","meaning":"to carry, bring, produce","meaningCN":"携带；带来；产生"},{"word":"proliferare","structure":"Latin verb from prolifer","meaning":"to produce offspring, breed","meaningCN":"产生后代；繁殖"}],"derivatives":[{"word":"proliferation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「增殖；激增」"},{"word":"proliferative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「增殖性的」"},{"word":"proliferating","pos":"adj.","zh":"由现在分词转作形容词，义为「不断增殖的」"},{"word":"proliferator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「增殖者」"}]}},{"word":"stimulate","ipa_uk":"/ˈstɪmjuleɪt/","ipa_us":"/ˈstɪmjuleɪt/","definition_zh":"刺激；激发；促进；激励；使兴奋","definition_en":"to rouse or increase the activity of something by an external influence","core_image":"赶牛人握着一根顶端带尖的长棒，轻轻点一下牛背，停住的牛群立刻向前走动","scene":"清晨的集市上，赶车人用尖头长棒轻点牛背，原本停住的牛群立刻迈步前行。A sharp prod can stimulate a tired ox to move.","sceneCN":"这里指用外在作用唤起身体或感官的反应（第 1 个义项：刺激感官或身体部位）；句意为一下尖棒的触碰就能刺激疲惫的牛向前走。图中可辨识物件：尖头长棒、牛背、向前迈步的牛群。","pos":[{"tag":"v.","zh":"刺激；激发；促进；激励；使兴奋"}],"collocations":[{"phrase":"stimulate growth","zh":"促进生长"},{"phrase":"stimulate interest","zh":"激发兴趣"},{"phrase":"stimulate demand","zh":"刺激需求"},{"phrase":"stimulate the economy","zh":"刺激经济"},{"phrase":"stimulate the senses","zh":"刺激感官"},{"phrase":"stimulate the nerve","zh":"刺激神经"},{"phrase":"stimulate investment","zh":"促进投资"}],"forms":[{"label":"动词原形","form":"stimulate"},{"label":"第三人称单数","form":"stimulates"},{"label":"过去式","form":"stimulated"},{"label":"过去分词","form":"stimulated"},{"label":"现在分词","form":"stimulating"},{"label":"名词","form":"stimulation"}],"derivatives":[{"word":"stimulation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「刺激；激发」"},{"word":"stimulator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「刺激者；刺激器」"},{"word":"stimulating","pos":"adj.","zh":"由现在分词转作形容词，义为「令人兴奋的；启发思考的」"},{"word":"stimulant","pos":"n.","zh":"由同一拉丁词干加表示物或剂的名词尾构成，义为「兴奋剂；刺激物」"},{"word":"stimulus","pos":"n.","zh":"直接借自拉丁语的名词，义为「刺激物；刺激因素」"}],"senses":[{"no":"01","title":"To rouse a sense or a body part","titleCN":"刺激感官或身体部位","definition":"to produce a reaction in a sense organ or a part of the body","definitionCN":"使感觉器官或身体某部位产生反应","example":"Cold water stimulates the skin and wakes the whole body.","exampleCN":"冷水刺激皮肤，让全身清醒过来。","why":"The Latin word was a pointed stick that touched an animal, and the body remains the most literal target.","whyCN":"这个词在拉丁语里就是触碰牲畜的尖棒，身体始终是最字面的作用对象。"},{"no":"02","title":"To awaken interest or enthusiasm","titleCN":"激发兴趣与热情","definition":"to make someone interested or eager about something","definitionCN":"使某人对某事产生兴趣或热情","example":"The lecture stimulated her interest in geology.","exampleCN":"这场讲座激发了她对地质学的兴趣。","why":"Interest is treated as a sleeping response: a good question prods it into motion.","whyCN":"兴趣被当作一种沉睡的反应：一个好问题就能把它戳醒。"},{"no":"03","title":"To raise growth or demand","titleCN":"促进增长与需求","definition":"to increase the amount of growth, spending or demand for something","definitionCN":"使增长、支出或对某物的需求增加","example":"Lower prices stimulated demand for the device.","exampleCN":"价格下调刺激了这款设备的需求。","why":"An outside push can set a quantity moving upward, which is the same shape as a goad starting a herd.","whyCN":"外部的推动能让数量上升，这与尖棒赶动牛群是同一种形状。"},{"no":"04","title":"To excite a nerve or a muscle","titleCN":"刺激神经或肌肉","definition":"to apply a signal that makes a nerve or a muscle respond","definitionCN":"施加使神经或肌肉产生反应的信号","example":"The electrode stimulates the muscle during therapy.","exampleCN":"治疗时电极刺激肌肉。","why":"Electric current replaced the stick, but the point of contact and the sudden response stayed the same.","whyCN":"电流取代了尖棒，但接触点与突然的反应没有变。"},{"no":"05","title":"To move a person to act","titleCN":"激励某人行动","definition":"to encourage someone to begin or increase an action","definitionCN":"鼓励某人开始行动或加大行动力度","example":"The bonus stimulated the team to finish the work early.","exampleCN":"奖金激励团队提前完成工作。","why":"A reward works like a goad: it is outside the person, and the movement comes from the touch.","whyCN":"奖励的作用像尖棒：它在人之外，而行动由这一触而来。"},{"no":"06","title":"To trigger an immune or physical response","titleCN":"激发免疫或生理反应","definition":"to cause the body to produce an immune or physiological reaction","definitionCN":"使身体产生免疫或生理上的反应","example":"The vaccine stimulates an immune response within two weeks.","exampleCN":"疫苗在两周内激发免疫反应。","why":"Medicine borrowed the verb for anything that switches a bodily system on.","whyCN":"医学借用了这个动词，指任何能开启身体系统的作用。"},{"no":"07","title":"To promote cell and tissue activity","titleCN":"促进细胞与组织活动","definition":"to increase the division, growth or activity of cells and tissue","definitionCN":"使细胞与组织的分裂、生长或活动增强","example":"The hormone stimulates cell growth in the damaged tissue.","exampleCN":"这种激素促进受损组织中的细胞生长。","why":"At the smallest scale the word still means making a living system work harder.","whyCN":"在最小的尺度上，这个词仍然指让生命系统更用力地运转。"},{"no":"08","title":"To boost demand by policy","titleCN":"政策上刺激需求与经济","definition":"to use public measures such as spending or tax cuts to raise demand and growth","definitionCN":"用支出或减税等公共措施提高需求与增长","example":"The government cut taxes to stimulate the economy.","exampleCN":"政府减税以刺激经济。","why":"Economics gave the old goad a new hand: the state prods the whole market at once.","whyCN":"经济学给这根老尖棒换了一只新手：国家一次性戳动整个市场。"}],"etymology":{"intro":{"en":"Stimulate comes from Latin stimulus, a goad or pointed stick used to drive cattle, and the verb stimulare, to prick with such a goad.","cn":"这个词来自拉丁语「stimulus」刺棒、赶牛的尖棒，以及动词「stimulare」用刺棒赶、刺激。"},"items":[{"era":"LATIN STIMULUS","en":"A stimulus was a pointed stick used to drive animals forward.","cn":"这个词指用来驱赶牲畜前进的尖棒。"},{"era":"LATIN STIMULARE","en":"The verb meant to prick with a goad and so to urge an animal on.","cn":"这个动词意为用尖棒戳刺，从而催促牲畜前行。"},{"era":"THE PHYSICAL PROD","en":"The first picture is physical: a point touches a hide and the animal moves.","cn":"最初的画面是物理性的：尖头触到皮肉，牲畜便动起来。"},{"era":"MEDICAL EXTENSION","en":"Later the verb was used for anything that rouses a body part, a nerve or an organ.","cn":"后来这个动词用于任何能唤起身体部位、神经或器官活动的作用。"},{"era":"ENGLISH, 16TH CENTURY","en":"English adopted the verb in the sixteenth century in the sense of rousing or inciting.","cn":"英语在十六世纪引入这个动词，义为唤起或鼓动。"},{"era":"MODERN ECONOMICS","en":"Stimulus and stimulate became routine terms for pushing demand and growth upward.","cn":"「stimulus」与「stimulate」成为推高需求与增长的常用术语。"}]},"similar":{"note":{"en":"The first group looks like stimulate or shares its stem; the second group names neighbouring ideas of urging and rousing.","cn":"第一组在形音上与「stimulate」相近或共享词干；第二组是与「催促、唤起」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stimulation","ipa":"/ˌstɪmjuˈleɪʃn/","tag":"same root","definition":"The noun for the act of rousing or exciting something.","definitionCN":"指唤起或激发某物的行为。"},{"word":"stimulator","ipa":"/ˈstɪmjuleɪtə/","tag":"same root","definition":"A person or device that rouses activity.","definitionCN":"指唤起活动的人或装置。"},{"word":"stimulant","ipa":"/ˈstɪmjələnt/","tag":"same root","definition":"A substance that raises activity in the body.","definitionCN":"指提高身体活动水平的物质。"},{"word":"stimulus","ipa":"/ˈstɪmjələs/","tag":"same root","definition":"Something that causes a response; the Latin word used unchanged in English.","definitionCN":"指引起反应之物；是拉丁原词在英语中的直接沿用。"},{"word":"stimulating","ipa":"/ˈstɪmjuleɪtɪŋ/","tag":"same root","definition":"Adjective for something that rouses interest or activity.","definitionCN":"形容能唤起兴趣或活动的事物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"encourage","ipa":"/ɪnˈkʌrɪdʒ/","tag":"near meaning","definition":"To give support or confidence to someone so that they act.","definitionCN":"指给予支持或信心，使人采取行动。"},{"word":"arouse","ipa":"/əˈraʊz/","tag":"near meaning","definition":"To wake a feeling or a response in someone.","definitionCN":"指在某人身上唤起感觉或反应。"},{"word":"spur","ipa":"/spɜː/","tag":"near meaning","definition":"To urge someone on, originally with a rider's spur.","definitionCN":"指催促某人前进，原指用马刺。"},{"word":"provoke","ipa":"/prəˈvəʊk/","tag":"near meaning","definition":"To cause a reaction, often deliberately and often a strong one.","definitionCN":"指引起反应，常指刻意引起强烈反应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the cattle goad behind the word, its real family and the fields where it is standard.","cn":"正常联想使用这个词背后的赶牛尖棒、真实同族词，以及它的常用领域。"},"normal":[{"en":"A stimulus was a pointed stick, and to stimulate is to touch with that point.","cn":"「stimulus」原是一根尖棒，而「stimulate」就是用那个尖头去碰。"},{"en":"Stimulation, stimulator, stimulant and stimulus all keep the picture of something switched on.","cn":"刺激、刺激器、兴奋剂与刺激物都保留着「某物被开启」的画面。"},{"en":"Stimulate interest and stimulate demand are the two most common abstract pairings.","cn":"「stimulate interest」与「stimulate demand」是两种最常见的抽象搭配。"},{"en":"A stimulating lecture is one that keeps prodding your attention back to the topic.","cn":"一场引人入胜的讲座，就是不断把你的注意力戳回主题的讲座。"},{"en":"The economic stimulus package is the same old stick, held by a government.","cn":"经济刺激方案还是那根老尖棒，只是握在政府手里。"}],"abstract":[{"en":"Nothing moves by itself; the word always implies a hand and a point outside the thing moved.","cn":"没有东西会自己动；这个词总暗示着被推动之物外面有一只手和一个尖头。"},{"en":"Interest is not poured in but poked awake, and that is why the verb suits curiosity so well.","cn":"兴趣不是被灌进去的，而是被戳醒的，这就是这个动词如此适合好奇心的原因。"},{"en":"A stimulus is a small contact with a large consequence, and the gap between them is the whole idea.","cn":"刺激是一次小小的接触带来大大的后果，两者之间的落差正是全部意思。"}]},"examples":[{"en":"The new coach stimulated the players with a short, sharp talk.","cn":"新教练用一番简短有力的讲话激励了球员。"},{"en":"Bright colours stimulate the eyes more than dull grey ones.","cn":"鲜艳的颜色比沉闷的灰色更能刺激眼睛。"},{"en":"Tax cuts were meant to stimulate spending in the region.","cn":"减税意在刺激该地区的消费。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「斯提缪雷特」——尖棒点一下牛背，牛就往前走；人被点一下也来劲：刺激、激发","word":"stimulate"},"root":"拉丁语「stimulus」意为刺棒、赶牛的尖棒，动词「stimulare」意为用刺棒赶、刺激；英语十六世纪引入。词干更早的来源存疑，不作断言。","sensesIntro":{"en":"Eight senses start from a physical prod and widen: a sense organ, an interest, growth and demand, a nerve or muscle, a person moved to act, an immune response, cell activity, and policy demand.","cn":"八个义项从物理性的戳刺出发向外扩展：感官、兴趣、增长与需求、神经或肌肉、被激励的人、免疫反应、细胞活动，以及政策需求。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pointed goad touches an ox, and the still herd starts walking.","cn":"核心意象：尖头刺棒触到牛背，原本停住的牛群开始走动。"},"chain":["POINTED GOAD","ANIMAL MOVES","SENSE ROUSED","INTEREST AWAKENED","DEMAND RAISED","RESPONSE QUICKENED"],"branches":[{"senses":"01 · 04","en":"THE DIRECT PROD: a sense organ or a nerve is roused by contact or current.","cn":"直接戳刺：感官或神经因接触或电流而被唤起。"},{"senses":"02 · 05","en":"THE AWAKENED PERSON: interest is lit, and a person is moved to act.","cn":"被唤醒的人：兴趣被点亮，人被推动着行动。"},{"senses":"03 · 08","en":"THE RAISED DEMAND: prices, taxes and policy push growth and spending upward.","cn":"被抬高的需求：价格、税收与政策把增长和支出往上推。"},{"senses":"06","en":"THE BODY'S ALARM: an immune or physical response is switched on.","cn":"身体的警报：免疫或生理反应被开启。"},{"senses":"07","en":"THE LIVING CELL: division and tissue activity are stepped up.","cn":"活着的细胞：分裂与组织活动被加快。"}]},"affixes":{"intro":{"en":"Stimulate is a Latin verb of driving and pricking, and its English endings build a whole family of nouns and adjectives.","cn":"这是一个表示驱赶与戳刺的拉丁动词，英语词尾围绕它构成一整族名词与形容词。"},"latinIntro":{"en":"Latin supplies stimulus, the goad, and stimulare, to use it; English adds only ordinary endings.","cn":"拉丁语提供了「stimulus」尖棒与「stimulare」使用尖棒；英语只加了普通词尾。"},"items":[{"word":"stimulus","structure":"Latin noun","meaning":"goad; pointed stick","meaningCN":"刺棒；尖棒","example":"The noun names the stick that drives the herd.","exampleCN":"这个名词指驱赶畜群的棒子。"},{"word":"stimulare","structure":"Latin verb from stimulus","meaning":"to prick with a goad; to urge on","meaningCN":"用刺棒戳；催促","example":"The verb names the act of using the goad.","exampleCN":"这个动词指使用刺棒的动作。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or cause","meaningCN":"使……；做……","example":"The ending marks the English action verb.","exampleCN":"这个词尾标明英语动作动词。"},{"word":"-tion","structure":"action-result noun ending","meaning":"the act or result of rousing","meaningCN":"唤起的行为或结果","example":"It forms the noun stimulation.","exampleCN":"它构成名词「stimulation」。"},{"word":"-or","structure":"agent noun ending","meaning":"the one that rouses","meaningCN":"进行刺激的人或物","example":"It forms the noun stimulator.","exampleCN":"它构成名词「stimulator」。"},{"word":"-ant","structure":"adjective and noun ending","meaning":"that which raises activity","meaningCN":"使活动增强的（物）","example":"It forms the word stimulant.","exampleCN":"它构成「stimulant」。"},{"word":"-ing","structure":"adjective ending","meaning":"tending to rouse","meaningCN":"令人振奋的","example":"It forms the adjective stimulating.","exampleCN":"它构成形容词「stimulating」。"},{"word":"-ory","structure":"adjective ending","meaning":"serving to rouse","meaningCN":"起刺激作用的","example":"It forms the adjective stimulatory.","exampleCN":"它构成形容词「stimulatory」。"}],"latinEntries":[{"word":"stimulus","structure":"Latin noun","meaning":"goad, pointed stick","meaningCN":"刺棒；尖棒"},{"word":"stimulare","structure":"Latin verb from stimulus","meaning":"to prick with a goad, urge on","meaningCN":"用刺棒戳；催促"}],"derivatives":[{"word":"stimulation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「刺激；激发」"},{"word":"stimulator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「刺激器；刺激者」"},{"word":"stimulating","pos":"adj.","zh":"由现在分词转作形容词，义为「令人兴奋的」"},{"word":"stimulant","pos":"n.","zh":"由同一词干加表示物或剂的名词尾构成，义为「兴奋剂」"}]}},{"word":"analogous","ipa_uk":"/əˈnæləɡəs/","ipa_us":"/əˈnæləɡəs/","definition_zh":"可类比的；相似的；同功的；类推的","definition_en":"similar in a way that permits a comparison between two different things, especially in structure or function","core_image":"两副骨架并排摆在展台上，一副来自鸟，一副来自飞机，翼形与受力路径一一对应，材料却完全不同","scene":"博物馆展台上并排摆着鸟翼与机翼的剖面，骨架与梁架一一对应，材料却各不相同。A bird's wing is analogous to an aircraft wing in function.","sceneCN":"这里指两种不同事物之间存在可对照的结构关系（第 1 个义项：跨域可类比）；句意为鸟翼在功能上与飞机机翼可以类比。图中可辨识物件：鸟翼剖面、机翼剖面、对应的骨架与梁架。","pos":[{"tag":"adj.","zh":"可类比的；相似的；同功的；类推的"}],"collocations":[{"phrase":"analogous to","zh":"与……类似"},{"phrase":"analogous with","zh":"与……可类比"},{"phrase":"closely analogous","zh":"密切对应"},{"phrase":"broadly analogous","zh":"大体对应"},{"phrase":"analogous structure","zh":"同功结构"},{"phrase":"analogous case","zh":"类似案例"}],"forms":[{"label":"形容词原形","form":"analogous"},{"label":"比较级","form":"more analogous"},{"label":"最高级","form":"most analogous"},{"label":"副词","form":"analogously"},{"label":"名词","form":"analogy"}],"derivatives":[{"word":"analogy","pos":"n.","zh":"由该形容词同族的名词形式，义为「类比；相似」"},{"word":"analogously","pos":"adv.","zh":"由该形容词加副词尾构成，义为「类似地；可类比地」"},{"word":"analogue","pos":"n.","zh":"经法语而来的同族名词，义为「相似物；模拟量」"},{"word":"analog","pos":"adj.","zh":"美式拼写的同族形容词，义为「模拟的」"}],"senses":[{"no":"01","title":"Comparable across different domains","titleCN":"跨域可类比","definition":"able to be compared with something from another field because both answer to the same measure","definitionCN":"因两者符合同一尺度，可以与另一领域的某物相比较","example":"The two economies are analogous in their reliance on exports.","exampleCN":"这两个经济体在依赖出口这一点上可以类比。","why":"The Greek adjective meant proportionate, so the earliest comparison was between things measured on one scale.","whyCN":"这个希腊形容词意为成比例的，因此最早的比较是在同一尺度上衡量两物。"},{"no":"02","title":"Similar in function but not in origin","titleCN":"生物学同功结构","definition":"describing body parts that perform the same job without sharing an evolutionary origin","definitionCN":"指承担相同功能却并非来自同一演化来源的身体结构","example":"A bat's wing is analogous to a bird's wing, though their bones differ.","exampleCN":"蝙蝠的翼与鸟的翼是同功结构，尽管骨骼并不相同。","why":"Biology needed a word for matching jobs, leaving the matching ancestry to the word homologous.","whyCN":"生物学需要一个表示「功能相同」的词，而把「来源相同」留给同源这个词。"},{"no":"03","title":"Reasoning by comparison","titleCN":"类比推理","definition":"reaching a conclusion about one case by comparing it with a known similar case","definitionCN":"通过与已知的类似情形比较，得出关于另一情形的结论","example":"The engineer used an analogous line of reasoning to test the new design.","exampleCN":"工程师用一条类比推理的思路来检验新设计。","why":"If two things answer to one ratio, a step that works for the first can be carried over to the second.","whyCN":"如果两物符合同一比例，对前者有效的一步就可以搬到后者身上。"},{"no":"04","title":"Reasoning across legal cases","titleCN":"法律类推","definition":"applying a rule from one decided case to another case that is not identical but comparable","definitionCN":"把已决案例中的规则用到另一个不完全相同但可比的情形上","example":"Lawyers applied an analogous rule from an earlier case.","exampleCN":"律师们援引了早先案例中一条类似的规则。","why":"Law rests on precedent, and precedent works only if the new case can be matched to the old one.","whyCN":"法律依靠先例，而先例只有在新案件能与旧案件对应时才起作用。"},{"no":"05","title":"Matching in function","titleCN":"功能对应","definition":"serving the same purpose in two different systems, whatever the materials or shapes involved","definitionCN":"在两个不同系统中承担相同的用途，不论材料或形状如何","example":"The two valves are analogous in function but not in shape.","exampleCN":"这两个阀门在功能上相对应，形状却不同。","why":"Function is the measure here: if the job is the same, the parts can be called analogous.","whyCN":"这里的尺度是功能：只要承担的任务相同，这些部件就可以称为对应。"},{"no":"06","title":"The fixed phrase with to","titleCN":"固定搭配「analogous to」","definition":"used in the pattern be analogous to, naming the second term of the comparison","definitionCN":"用于「be analogous to」这一句式，引出比较的另一方","example":"Her role in the firm is analogous to that of a coach.","exampleCN":"她在公司里的角色相当于一名教练。","why":"The preposition to marks the direction of the comparison, and the phrase has become a fixed frame.","whyCN":"介词「to」标出比较的方向，这个短语因而成了固定框架。"},{"no":"07","title":"A likeness drawn for persuasion","titleCN":"修辞比拟","definition":"a comparison used in speech or writing to make an abstract idea vivid rather than to prove a point","definitionCN":"在言语或写作中用比较使抽象概念生动，而不是为了证明论点","example":"The poem draws an analogous image between a river and memory.","exampleCN":"这首诗在河流与记忆之间画出一幅可类比的意象。","why":"Rhetoric borrows the word for comparisons that persuade by resemblance, even when no proof is offered.","whyCN":"修辞学借这个词指靠相似来说服的比较，即使并不提供证明。"},{"no":"08","title":"Correspondence between whole systems","titleCN":"不同系统对应关系","definition":"a pattern in which two separate systems mirror each other in their arrangement or behaviour","definitionCN":"两个独立系统在结构或行为上彼此映照的模式","example":"The two networks show analogous patterns of connection.","exampleCN":"这两个网络显示出可类比的连接模式。","why":"Once the comparison is between whole systems, the word describes a shared architecture rather than single parts.","whyCN":"当比较发生在整个系统之间，这个词描述的是共有的架构，而非单个部件。"}],"etymology":{"intro":{"en":"Analogous comes from Greek analogos, proportionate or corresponding, built from ana-, according to, and logos, ratio, reason or word; it entered English through Latin analogus.","cn":"这个词来自希腊语「analogos」成比例的、相应的，由「ana-」按照与「logos」比例、道理、言词构成；经拉丁语「analogus」进入英语。"},"items":[{"era":"GREEK ANA-","en":"The prefix means according to or in proportion, and it sets the frame of a shared measure.","cn":"这个前缀意为按照或成比例，它给出共同尺度的框架。"},{"era":"GREEK LOGOS","en":"Logos covered ratio, proportion, reason and word, so the comparison was always rational as well as verbal.","cn":"这个词涵盖比例、道理、言词，因此这种比较既是言辞的，也是理性的。"},{"era":"GREEK ANALOGOS","en":"The adjective meant proportionate or corresponding, said of things that answer to the same measure.","cn":"这个形容词意为成比例的、相应的，用于符合同一尺度的事物。"},{"era":"LATIN ANALOGUS","en":"Latin borrowed the Greek adjective unchanged in meaning and passed it on to English.","cn":"拉丁语借入这个希腊形容词，意义不变，再传给英语。"},{"era":"ENGLISH, 16TH CENTURY","en":"English took the adjective in the sixteenth century and formed the noun analogy beside it.","cn":"英语在十六世纪引入这个形容词，并在旁边造出名词「analogy」。"},{"era":"SCIENCE AND LAW","en":"Biology applied it to structures with the same function but a different origin, and law to reasoning across cases.","cn":"生物学用它指功能相同而来源不同的结构，法律用它指跨案例的推理。"}]},"similar":{"note":{"en":"The first group looks like analogous or shares its Greek stem, including analogue and analog; the second group names nearby ideas of likeness. Note that similar merely says two things resemble each other, while analogous claims a correspondence of structure or function across different fields.","cn":"第一组在形音上与「analogous」相近或共享希腊词干，包含「analogue」与「analog」；第二组是与「相似」相邻的说法。要注意「similar」只泛指相像，而「analogous」强调跨领域在结构或功能上的对应。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"analogy","ipa":"/əˈnælədʒi/","tag":"same root","definition":"A comparison that sets two things side by side to show a shared pattern.","definitionCN":"指把两事物并置以显示共同模式的比较。"},{"word":"analogue","ipa":"/ˈænəlɒɡ/","tag":"same root","definition":"A thing that corresponds to another, or a signal that varies continuously.","definitionCN":"指与另一物相对应之物，也指连续变化的模拟信号。"},{"word":"analog","ipa":"/ˈænəlɒɡ/","tag":"same root","definition":"The American spelling of analogue, used especially for continuous signals and clocks.","definitionCN":"「analogue」的美式拼写，尤用于连续信号与钟表。"},{"word":"analogic","ipa":"/ˌænəˈlɒdʒɪk/","tag":"same root","definition":"Adjective for reasoning by comparison rather than by deduction.","definitionCN":"形容以比较而非演绎进行的推理。"},{"word":"ambiguous","ipa":"/æmˈbɪɡjuəs/","tag":"different root","definition":"Open to more than one reading; it looks close but comes from a verb meaning to wander, not from logos.","definitionCN":"指可有多种解释的；形近但出自意为游移的动词，与「logos」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"similar","ipa":"/ˈsɪmələ/","tag":"near meaning","definition":"Resembling another thing in appearance or nature, without claiming any structural match.","definitionCN":"指在外观或性质上相像，并不声称结构上的对应。"},{"word":"comparable","ipa":"/ˈkɒmpərəbl/","tag":"near meaning","definition":"Able to be measured or judged against another on the same scale.","definitionCN":"指可以在同一尺度上与另一物衡量或比较。"},{"word":"parallel","ipa":"/ˈpærəlel/","tag":"near meaning","definition":"Running alongside and matching in pattern, often of lines, trends or lives.","definitionCN":"指并行且在模式上对应，常用于线路、趋势或人生。"},{"word":"equivalent","ipa":"/ɪˈkwɪvələnt/","tag":"near meaning","definition":"Equal in value, force or meaning rather than merely similar in form.","definitionCN":"指在价值、效力或意义上相等，而不只是形式上相像。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Greek measure behind the word, its real family and the fields where the term is standard.","cn":"正常联想使用这个词背后的希腊尺度、真实同族词，以及这个词常用的领域。"},"normal":[{"en":"Greek logos is ratio, so analogous things answer to the same measure even when they are made of different stuff.","cn":"希腊语「logos」是比例，因此可类比之物即使材料不同，也符合同一尺度。"},{"en":"An analogy, an analogue and an analog all keep the idea of one thing answering to another.","cn":"类比、相似物与模拟量都保留着「一物对应另一物」的意思。"},{"en":"Biology calls a bat's wing analogous to a bird's wing because both fly, not because they share ancestors.","cn":"生物学称蝙蝠翼与鸟翼同功，是因为两者都会飞，而不是因为共有祖先。"},{"en":"Lawyers speak of an analogous case when an old rule can be stretched to a new situation.","cn":"当旧规则可以延伸到新情形时，律师会说这是一个类似案例。"},{"en":"Analogous to is the fixed phrase, and it always wants the second term after to.","cn":"「analogous to」是固定搭配，后面总要跟比较的另一方。"}],"abstract":[{"en":"Similarity of shape is easy to see; correspondence of function is what analogous asks you to prove.","cn":"形状相像容易看见，功能对应才是「analogous」要你证明的东西。"},{"en":"Two things made of different materials can still answer to one ratio, and that is the quiet claim of the word.","cn":"材料不同的两样东西仍可符合同一比例，这正是这个词低调的主张。"},{"en":"An analogy is a bridge built from a known bank to an unknown one, and it must be tested before it is trusted.","cn":"类比是一座从已知岸搭向未知岸的桥，信任它之前必须先检验。"}]},"examples":[{"en":"The heart's pumping action is analogous to a mechanical pump.","cn":"心脏的泵血作用类似于一台机械泵。"},{"en":"An analogous problem appeared in the earlier design of the bridge.","cn":"这座桥早先的设计中也出现过类似的问题。"},{"en":"Biologists treat these two organs as analogous rather than homologous.","cn":"生物学家把这两个器官视为同功结构，而不是同源结构。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿那勒格斯」——两样东西材料不同、骨架却对得上，可以横着比一比：可类比的、同功的","word":"analogous"},"root":"希腊语「analogos」意为成比例的、相应的，由「ana-」按照加「logos」比例、道理、言词构成；经拉丁语「analogus」进入英语。它与泛指相像的「similar」不同，强调跨领域在结构或功能上的对应。","sensesIntro":{"en":"Eight senses share one idea of correspondence: across fields, in biology, in reasoning, in law, in function, in the fixed phrase, in rhetoric, and between whole systems.","cn":"八个义项共享一个「对应」的念头：跨领域、生物学、推理、法律、功能、固定搭配、修辞，以及整个系统之间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bird's wing and an aircraft wing lie side by side, bone for strut, with different materials and the same job.","cn":"核心意象：鸟翼与机翼并排摆放，骨骼对梁架，材料不同而功用相同。"},"chain":["TWO DIFFERENT THINGS","A SHARED MEASURE","STRUCTURE MATCHED","FUNCTION MATCHED","INFERENCE ACROSS FIELDS","SYSTEMS IN PARALLEL"],"branches":[{"senses":"01 · 03","en":"THE GENERAL COMPARISON: two separate domains are placed on one measure, and reasoning follows.","cn":"一般比较：两个不同领域被放在同一尺度上，推理随之展开。"},{"senses":"02 · 05","en":"THE MATCHED ORGAN: biology and engineering judge by function rather than by origin.","cn":"对应的器官：生物学与工程学按功能而非来源来判断。"},{"senses":"04 · 06","en":"THE BORROWED RULE AND THE FIXED FRAME: a rule crosses cases, and the phrase takes to.","cn":"借来的规则与固定框架：规则跨案例使用，而短语以「to」引出对象。"},{"senses":"07","en":"THE RHETORICAL FIGURE: a likeness is drawn to persuade, not to prove.","cn":"修辞手法：画出相似是为了说服，而不是为了证明。"},{"senses":"08","en":"THE PAIRED SYSTEMS: whole networks answer to each other's patterns.","cn":"成对的系统：整个网络彼此呼应对方的模式。"}]},"affixes":{"intro":{"en":"Analogous is a Greek adjective built from a prefix of proportion and a noun of ratio, and English keeps the family together.","cn":"这是一个由表示比例的前缀与表示比例的名词构成的希腊形容词，英语把这一族词保留在一起。"},"latinIntro":{"en":"Greek supplies analogos and its parts, and Latin supplies analogia and analogus before English takes them over.","cn":"希腊语提供了「analogos」及其组成部分，拉丁语又提供「analogia」与「analogus」，再由英语接手。"},"items":[{"word":"analogos","structure":"Greek adjective","meaning":"proportionate; corresponding","meaningCN":"成比例的；相应的","example":"The adjective is the direct source of the English word.","exampleCN":"这个形容词是英语词的直接来源。"},{"word":"ana-","structure":"Greek prefix","meaning":"according to; in proportion","meaningCN":"按照；成比例","example":"The prefix sets the shared measure.","exampleCN":"这个前缀设定共同的尺度。"},{"word":"logos","structure":"Greek noun","meaning":"ratio; reason; word","meaningCN":"比例；道理；言词","example":"The noun supplies the measuring half.","exampleCN":"这个名词提供「尺度」那一半。"},{"word":"analogia","structure":"Latin noun from Greek","meaning":"proportion; correspondence","meaningCN":"比例；对应","example":"The noun names the relation itself.","exampleCN":"这个名词指关系本身。"},{"word":"analogus","structure":"Latin adjective","meaning":"analogous; proportionate","meaningCN":"可类比的；成比例的","example":"Latin passed the adjective to English.","exampleCN":"拉丁语把这个形容词传给英语。"},{"word":"-ous","structure":"adjective ending","meaning":"having the quality of","meaningCN":"具有……性质的","example":"It marks the English adjective.","exampleCN":"它标出英语形容词。"},{"word":"-y","structure":"noun ending","meaning":"state or quality","meaningCN":"状态或性质","example":"It forms the noun analogy.","exampleCN":"它构成名词「analogy」。"},{"word":"analogue","structure":"English noun from French","meaning":"a thing corresponding to another","meaningCN":"与另一物对应之物","example":"The word keeps the idea of a matched counterpart.","exampleCN":"这个词保留「对应物」的意思。"}],"latinEntries":[{"word":"analogia","structure":"Latin noun from Greek","meaning":"proportion, correspondence","meaningCN":"比例；对应"},{"word":"analogus","structure":"Latin adjective from Greek","meaning":"analogous, proportionate","meaningCN":"可类比的；成比例的"}],"derivatives":[{"word":"analogy","pos":"n.","zh":"由同一希腊词干构成的名词，义为「类比；相似」"},{"word":"analogously","pos":"adv.","zh":"由该形容词加副词尾构成，义为「类似地」"},{"word":"analogue","pos":"n.","zh":"经法语而来的同族名词，义为「相似物；模拟量」"},{"word":"analog","pos":"adj.","zh":"美式拼写的同族形容词，义为「模拟的」"}]}},{"word":"consecutive","ipa_uk":"/kənˈsekjətɪv/","ipa_us":"/kənˈsekjətɪv/","definition_zh":"连续的；接连的；连贯的；结果性的","definition_en":"following one after another without an interruption, or following as a result","core_image":"日历上六页接连翻过，每一页的日期都紧挨着前一页，中间没有空白的一页","scene":"跑道上电子计时牌一站一站翻过，同一名选手的名字连续出现，中间没有空缺。She won the title for three consecutive seasons.","sceneCN":"这里指一段时间内一次接一次、中间没有断开（第 1 个义项：时间上接连无间断）；句意为她连续三个赛季夺得冠军。图中可辨识物件：电子计时牌、选手名次、连成一列的赛季记录。","pos":[{"tag":"adj.","zh":"连续的；接连的；连贯的；结果性的"}],"collocations":[{"phrase":"consecutive days","zh":"连续几天"},{"phrase":"consecutive years","zh":"连续数年"},{"phrase":"consecutive victories","zh":"连胜"},{"phrase":"consecutive terms","zh":"连任几届"},{"phrase":"consecutive numbers","zh":"连号数字"},{"phrase":"consecutive clause","zh":"结果状语从句"},{"phrase":"consecutive interpreting","zh":"交替传译"}],"forms":[{"label":"形容词原形","form":"consecutive"},{"label":"比较级","form":"more consecutive"},{"label":"最高级","form":"most consecutive"},{"label":"副词","form":"consecutively"},{"label":"名词","form":"consecutiveness"}],"derivatives":[{"word":"consecutively","pos":"adv.","zh":"由该形容词加副词尾构成，义为「连续地；接连地」"},{"word":"consecutiveness","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「连续性」"},{"word":"consecution","pos":"n.","zh":"由同一拉丁词干构成的名词，义为「连续；顺序」"},{"word":"nonconsecutive","pos":"adj.","zh":"由表示否定的前缀加该形容词构成，义为「不连续的」"}],"senses":[{"no":"01","title":"Following in time without a break","titleCN":"时间上接连无间断","definition":"happening in one period after another with nothing missing in between","definitionCN":"一个时段接一个时段地发生，中间没有缺失","example":"The team trained for five consecutive days before the match.","exampleCN":"比赛前，这支队伍连续训练了五天。","why":"The Latin verb meant to follow closely, so the word begins with one thing pressing right behind another.","whyCN":"这个拉丁动词意为紧跟，因此这个词最初就是一物紧贴另一物之后。"},{"no":"02","title":"Counting in an unbroken run","titleCN":"连续计数","definition":"used of numbers or amounts that follow in an unbroken order","definitionCN":"用于按不间断次序相随的数字或数量","example":"Write the consecutive numbers from one to ten.","exampleCN":"写出一到十的连续数字。","why":"Counting is the plainest example of following on, with no value skipped between two terms.","whyCN":"计数是「依次相随」最朴素的例子，两个数之间没有跳过的值。"},{"no":"03","title":"A run of wins","titleCN":"连胜","definition":"describing victories or successes that come one after another without a defeat between them","definitionCN":"指一场接一场的胜利或成功，中间没有失败","example":"The club recorded four consecutive victories in the league.","exampleCN":"这家俱乐部在联赛中取得四连胜。","why":"Sport counts streaks, and a streak is exactly a series with no gap in it.","whyCN":"体育要数连续纪录，而连续纪录正是一个没有缺口的序列。"},{"no":"04","title":"Adjacent in a series","titleCN":"序列相邻或连号","definition":"placed next to each other in an ordered set, as with numbers or seats","definitionCN":"在有序集合中彼此相邻，如号码或座位","example":"The tickets bear consecutive serial numbers.","exampleCN":"这些票的编号是连号的。","why":"When items are numbered, following on means occupying the very next place.","whyCN":"当物件被编号时，依次相随便意味着占据紧接着的那一位。"},{"no":"05","title":"A chain of linked events","titleCN":"一连串因果相承事件","definition":"describing events in which each one follows from the one before it","definitionCN":"指每个事件都由前一个事件引出的情形","example":"The report describes a consecutive chain of failures.","exampleCN":"报告描述了一连串前后相承的失误。","why":"The Latin verb also meant to result from, so following in time can become following as a consequence.","whyCN":"这个拉丁动词也意为「由……导致」，因此时间上的相随可以变成因果上的相承。"},{"no":"06","title":"The grammar of result","titleCN":"语法结果从句","definition":"naming a clause that expresses the result of what the main clause states","definitionCN":"指表达主句所述内容之结果的从句","example":"The grammar book explains how a consecutive clause expresses result.","exampleCN":"这本语法书讲解结果从句如何表达结果。","why":"Grammarians borrowed the adjective for clauses where the second statement follows from the first.","whyCN":"语法学家借这个形容词指第二个陈述由第一个陈述引出的从句。"},{"no":"07","title":"Unbroken shifts or operation","titleCN":"连续班次或连续作业","definition":"describing work periods that run one after another without a pause","definitionCN":"指一个接一个运行、中间不停顿的工作时段","example":"The plant runs three consecutive shifts during the peak season.","exampleCN":"生产旺季，工厂连续开三个班次。","why":"Industry measures time in shifts, and consecutive shifts leave no idle gap between them.","whyCN":"工业以班次计量时间，而连续班次之间没有空闲的间隔。"},{"no":"08","title":"Year-after-year climate records","titleCN":"连续年份气候统计","definition":"used of weather or climate data gathered over an unbroken series of years","definitionCN":"用于在连续多年中收集的天气或气候数据","example":"Records show three consecutive dry years in the region.","exampleCN":"记录显示该地区连续三年干旱。","why":"Climate science compares year to year, and a run of years with no break is the basic unit of a trend.","whyCN":"气候科学逐年比较，而一段没有中断的年份正是趋势的基本单位。"}],"etymology":{"intro":{"en":"Consecutive comes from Latin consequi, to follow closely, from con-, together, and sequi, to follow; the past participle consecutus produced Late Latin consecutivus, which English borrowed in the seventeenth century.","cn":"这个词来自拉丁语「consequi」紧跟、随后，由「con-」一起与「sequi」跟随构成；过去分词「consecutus」产生晚期拉丁语「consecutivus」，英语在十七世纪借入。"},"items":[{"era":"LATIN SEQUI","en":"To follow is the core of the word, and the same verb stands behind sequence and sequel.","cn":"跟随是这个词的核心，同一个动词也构成「sequence」与「sequel」的词源。"},{"era":"LATIN CON-","en":"The prefix means together or along with, so following becomes following on.","cn":"这个前缀意为一起或随之，于是「跟随」变成「紧跟着」。"},{"era":"LATIN CONSEQUI","en":"The verb meant to follow closely, to come after, and also to result from something.","cn":"这个动词意为紧跟、随后，也意为由某事物导致。"},{"era":"LATIN CONSECUTUS","en":"The past participle described what has followed, and it is the stem before the English ending.","cn":"这个过去分词描述已经跟随而来的事物，是英语词尾之前的词干。"},{"era":"LATE LATIN CONSECUTIVUS","en":"The later adjective named things that follow in order or form a series.","cn":"这个晚期形容词指按次序相随或构成序列的事物。"},{"era":"ENGLISH, 17TH CENTURY","en":"English took the adjective in the seventeenth century for things coming one after another.","cn":"英语在十七世纪引入这个形容词，用于一个接一个到来的事物。"}]},"similar":{"note":{"en":"The first group looks like consecutive or shares its Latin stem; the second group names neighbouring ideas of things following in order. Note that successive stresses the order of items, from Latin sub- and cedere, to come after, while consecutive stresses that no gap separates them.","cn":"第一组在形音上与「consecutive」相近或共享拉丁词干；第二组是与「依次跟随」相邻的说法。要注意「successive」强调各项的次序，出自拉丁语「sub-」与「cedere」跟随在后；而「consecutive」强调中间没有间隔。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"consecutively","ipa":"/kənˈsekjətɪvli/","tag":"same root","definition":"In an unbroken order, one after another.","definitionCN":"指不间断地依次发生。"},{"word":"consecution","ipa":"/ˌkɒnsɪˈkjuːʃn/","tag":"same root","definition":"The state of following in sequence, a rare noun from the same stem.","definitionCN":"指依次相随的状态，是同一词干的罕见名词。"},{"word":"consecutiveness","ipa":"/kənˈsekjətɪvnəs/","tag":"same root","definition":"The quality of being unbroken in sequence.","definitionCN":"指序列不中断的性质。"},{"word":"consequence","ipa":"/ˈkɒnsɪkwəns/","tag":"same root","definition":"A result that follows from an action; it shares the Latin verb but not the sense of sequence.","definitionCN":"指由行为引出的结果；共享拉丁动词，但没有「连续」之义。"},{"word":"consecrate","ipa":"/ˈkɒnsɪkreɪt/","tag":"different root","definition":"To set something apart as sacred; it looks close but belongs to a word for making sacred.","definitionCN":"指把某物定为神圣；形近但属于「使神圣」那一系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"successive","ipa":"/səkˈsesɪv/","tag":"near meaning","definition":"Following in order, one after another, with emphasis on the sequence rather than on gaps.","definitionCN":"指依次相随，强调次序，而不强调有无间隔。"},{"word":"sequential","ipa":"/sɪˈkwenʃl/","tag":"near meaning","definition":"Arranged in a fixed order, one step or item after another.","definitionCN":"指按固定次序排列，一步或一项接一项。"},{"word":"continuous","ipa":"/kənˈtɪnjuəs/","tag":"near meaning","definition":"Going on without any stop or break, often of time or movement.","definitionCN":"指不停顿、不中断，常用于时间或运动。"},{"word":"uninterrupted","ipa":"/ˌʌnɪntəˈrʌptɪd/","tag":"near meaning","definition":"Not broken off at any point, used of a stretch of time or activity.","definitionCN":"指一段时间或活动在任何节点都未被打断。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin follow verb behind the word, its real family and the everyday things counted in runs.","cn":"正常联想使用这个词背后的拉丁语「跟随」动词、真实同族词，以及日常中成串计数的事物。"},"normal":[{"en":"The Latin sequi is to follow, and con- adds the sense of coming right along after.","cn":"拉丁语「sequi」是跟随，「con-」加上「紧随其后」的意思。"},{"en":"Consecutive days, consecutive years and consecutive wins all count things with no gap.","cn":"连续几天、连续数年与连胜，数的都是没有缺口的事物。"},{"en":"Consecutive numbers are neighbours on the number line, like adjacent seats in a row.","cn":"连号数字是数轴上的邻居，就像一排里相邻的座位。"},{"en":"A consecutive clause is named for the result that follows from the main statement.","cn":"结果从句得名于由主句陈述引出的结果。"},{"en":"Consecutive interpreting follows speech in chunks, one stretch after another.","cn":"交替传译跟着讲话分段进行，一段接一段。"}],"abstract":[{"en":"A gap is the only enemy of this word: if one day is missing, the run is broken.","cn":"缺口是这个词唯一的敌人：只要缺了一天，连续就断了。"},{"en":"Time is not a line but a stack of pages, and consecutive means no page was torn out.","cn":"时间不是一条线，而是一叠纸页，连续就意味着没有一页被撕掉。"},{"en":"A streak is fragile because it is counted backwards; one loss erases the whole series.","cn":"连续纪录之所以脆弱，是因为它被倒着数；一场失利就抹掉整串。"}]},"examples":[{"en":"The region suffered three consecutive summers of drought.","cn":"该地区连续三个夏天遭遇干旱。"},{"en":"Her consecutive victories surprised the whole circuit.","cn":"她的连胜让整个巡回赛都感到意外。"},{"en":"Number the pages in consecutive order from front to back.","cn":"把书页从前往后按连续顺序编号。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「肯塞丘提夫」——一个接一个，中间不空档：连续的、接连的","word":"consecutive"},"root":"拉丁语「consequi」意为紧跟、随后，由「con-」一起加「sequi」跟随构成，过去分词「consecutus」，晚期拉丁语「consecutivus」；英语十七世纪引入。它与「secare」切无关，因此与「section」「sector」不同源。","sensesIntro":{"en":"Eight senses run from time to counting to sport: unbroken time, counting, a run of wins, adjacent items, a chain of causes, the result clause, unbroken shifts, and year-by-year climate records.","cn":"八个义项从时间走到计数再走到体育：不间断的时间、连续计数、连胜、相邻项、因果链、结果从句、连续班次，以及逐年气候记录。"},"semanticMap":{"core":{"en":"CORE IMAGE: calendar pages turn in a stack, each date touching the next with no blank page between.","cn":"核心意象：日历一叠页接连翻过，每个日期都紧贴下一个，中间没有空白页。"},"chain":["ONE AFTER ANOTHER","NO GAP BETWEEN","COUNTING IN ORDER","RUN OF WINS","CAUSE FOLLOWS CAUSE","RESULT CLAUSE"],"branches":[{"senses":"01 · 02","en":"THE UNBROKEN STRETCH: time or a count runs on with nothing missing.","cn":"不间断的一段：时间或计数一路延续，什么都不缺。"},{"senses":"03 · 04","en":"THE RUN AND THE SERIES: wins stack up, and neighbouring items share an edge.","cn":"连续纪录与序列：胜利层层累积，相邻各项共用一条边。"},{"senses":"05","en":"THE CHAIN OF CAUSES: one event follows another as its outcome.","cn":"因果链：一个事件作为结果跟随另一个事件。"},{"senses":"06","en":"THE GRAMMATICAL RESULT: a clause states what follows from the main clause.","cn":"语法上的结果：从句陈述由主句引出的内容。"},{"senses":"07 · 08","en":"THE WORKING AND CLIMATE RECORD: unbroken shifts, and statistics over year after year.","cn":"作业与气候记录：连续的班次，以及逐年累积的统计。"}]},"affixes":{"intro":{"en":"Consecutive is a Latin adjective of following, and its endings and prefixes keep the sense of a series with no break.","cn":"这是一个表示跟随的拉丁形容词，它的词尾与前缀都保留着「序列不断」的意思。"},"latinIntro":{"en":"Latin supplies sequi, to follow, and consequi, to follow closely; the adjective consecutivus comes from the past participle.","cn":"拉丁语提供了「sequi」跟随与「consequi」紧跟；形容词「consecutivus」来自其过去分词。"},"items":[{"word":"sequi","structure":"Latin verb","meaning":"to follow","meaningCN":"跟随","example":"The verb is the root of sequence and sequel as well.","exampleCN":"这个动词也是「sequence」与「sequel」的词根。"},{"word":"con-","structure":"Latin prefix","meaning":"together; along with","meaningCN":"一起；随之","example":"The prefix makes following into following on.","exampleCN":"这个前缀把「跟随」变成「紧跟着」。"},{"word":"consequi","structure":"Latin verb from con- and sequi","meaning":"to follow closely; to result","meaningCN":"紧跟；由……导致","example":"The verb joins the two halves of the idea.","exampleCN":"这个动词把这一意思的两半合在一起。"},{"word":"consecutus","structure":"Latin past participle","meaning":"having followed","meaningCN":"已经跟随的","example":"The participle supplies the stem of the adjective.","exampleCN":"这个分词提供了形容词的词干。"},{"word":"consecutivus","structure":"Late Latin adjective","meaning":"following in order","meaningCN":"按次序相随的","example":"The form passed through French into English.","exampleCN":"这一形式经法语进入英语。"},{"word":"-ive","structure":"adjective ending","meaning":"tending to; serving as","meaningCN":"有……倾向的；起……作用的","example":"It marks the English adjective consecutive.","exampleCN":"它标出英语形容词「consecutive」。"},{"word":"-ly","structure":"adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb consecutively.","exampleCN":"它构成副词「consecutively」。"},{"word":"-ness","structure":"noun ending","meaning":"state or quality","meaningCN":"状态或性质","example":"It forms the noun consecutiveness.","exampleCN":"它构成名词「consecutiveness」。"}],"latinEntries":[{"word":"sequi","structure":"Latin verb","meaning":"to follow","meaningCN":"跟随"},{"word":"consequi","structure":"Latin verb from con- and sequi","meaning":"to follow closely, result","meaningCN":"紧跟；由……导致"}],"derivatives":[{"word":"consecutively","pos":"adv.","zh":"由该形容词加副词尾构成，义为「连续地」"},{"word":"consecution","pos":"n.","zh":"由同一拉丁词干构成的名词，义为「连续；顺序」"},{"word":"consecutiveness","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「连续性」"},{"word":"nonconsecutive","pos":"adj.","zh":"由表示否定的前缀加该形容词构成，义为「不连续的」"}]}},{"word":"discrete","ipa_uk":"/dɪˈskriːt/","ipa_us":"/dɪˈskriːt/","definition_zh":"离散的；分开的；独立的；不连续的；分段式的","definition_en":"separate and distinct, existing as individual units rather than as one continuous whole","core_image":"实验台上摆着一排互不相连的方块灯，每两盏之间留着一指宽的暗缝，各自有独立的开关","scene":"实验台上摆着一排互不相连的方块灯，每两盏之间留出一道暗缝，每盏灯都有自己的开关。Each reading comes from a discrete sensor with its own wire.","sceneCN":"这里指彼此分开、各自独立的单元（第 1 个义项：分离独立）；句意为每个读数都来自一个自带线路的独立传感器。图中可辨识物件：方块灯、暗缝、独立开关。","pos":[{"tag":"adj.","zh":"离散的；分开的；独立的"}],"collocations":[{"phrase":"discrete units","zh":"离散单元"},{"phrase":"discrete steps","zh":"离散步骤"},{"phrase":"discrete points","zh":"离散点"},{"phrase":"discrete data","zh":"离散数据"},{"phrase":"discrete signal","zh":"离散信号"},{"phrase":"discrete event","zh":"离散事件"},{"phrase":"discrete population","zh":"分离种群"}],"forms":[{"label":"原级","form":"discrete"},{"label":"比较级","form":"more discrete"},{"label":"最高级","form":"most discrete"},{"label":"派生副词","form":"discretely"},{"label":"派生名词","form":"discreteness"},{"label":"派生动词","form":"discretize"}],"derivatives":[{"word":"discretely","pos":"adv.","zh":"由该形容词加副词尾构成，义为「分开地；离散地」"},{"word":"discreteness","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「离散性；分离性」"},{"word":"discretize","pos":"v.","zh":"由该形容词加动词尾构成，义为「使离散化；离散处理」"},{"word":"discretization","pos":"n.","zh":"由离散化动词加名词尾构成，义为「离散化」"},{"word":"indiscrete","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「未分开的；不分明的」"}],"senses":[{"no":"01","title":"Separate and distinct","titleCN":"分离而独立","definition":"existing as a separate unit that is clearly apart from others and not merged with them","definitionCN":"作为与其他事物明显分开、不被合并的独立单元存在","example":"The two faults are discrete and need separate repairs.","exampleCN":"这两处故障彼此独立，需要分别修理。","why":"Latin discretus meant separated or distinguished, and this plain sense of standing apart is the base of every later use; the same participle also produced the homophone discreet, the word for cautious behaviour.","whyCN":"拉丁语「discretus」意为分开的或辨别出来的，这种「各自分开」的本义是后来一切用法的根基；同一个分词还产生了同音词「discreet」，即言行谨慎之义。"},{"no":"02","title":"Taking separate values","titleCN":"取分离的数值","definition":"changing only in separate countable values rather than over a smooth and unbroken range","definitionCN":"只在可数的分离数值之间变化，而不是在平滑连续的区间上变化","example":"A discrete variable can take only whole numbers.","exampleCN":"离散变量只能取整数。","why":"Mathematics took the word's core idea of separate units and applied it to quantities that jump from one value to the next.","whyCN":"数学借用了这个词「分离单元」的核心意思，用来指从一个数值跳到下一个数值的量。"},{"no":"03","title":"Data kept as separate items","titleCN":"以分离条目保存的数据","definition":"stored as individual records or categories rather than as one continuous stream","definitionCN":"以一条条独立记录或类别保存，而不是作为一条连续的数据流","example":"The survey collects discrete data on each household.","exampleCN":"这项调查收集每户的离散数据。","why":"Once values are counted separately, the records themselves are called discrete, and computing made this sense common.","whyCN":"数值一旦被分开计数，记录本身也就被称为离散的，计算机领域使这一义项流行起来。"},{"no":"04","title":"Divided into separate stages","titleCN":"分成互不相连的阶段","definition":"broken into separate parts or stages with clear gaps between them","definitionCN":"被切分为彼此有明显间隔的部分或阶段","example":"The training runs in discrete stages of four weeks.","exampleCN":"培训分为每期四周的独立阶段。","why":"A process cut at fixed points looks like a row of separate blocks, so the word also describes anything divided into stages.","whyCN":"过程在固定节点被切开，看起来就像一排分开的块，因此这个词也形容被分成阶段的事物。"},{"no":"05","title":"Individual and particular","titleCN":"单独个别的","definition":"considered one by one as a particular case, apart from the rest of its class","definitionCN":"作为特定个案逐个考虑，与其同类中的其余部分分开","example":"Each discrete case was reviewed by a different judge.","exampleCN":"每个单独的案例都由不同的法官审理。","why":"If units are separate, attention can fall on one alone; this sense stresses the single item rather than the gap between items, while discreet still keeps its own meaning of caution.","whyCN":"单元既然分开，注意力就可以只落在一个上面；这个义项强调单个个体，而不是个体之间的间隔，而「discreet」仍保留谨慎这一独立含义。"},{"no":"06","title":"A signal defined at separate instants","titleCN":"在分离时刻取值的信号","definition":"a signal whose value is defined only at separate moments, as in digital or sampled systems","definitionCN":"只在分离时刻才有确定取值的信号，如数字系统或采样系统中的信号","example":"The receiver converts the wave into a discrete signal.","exampleCN":"接收机把波转换成离散信号。","why":"Electronics borrowed the mathematical sense: a sampled wave exists as a series of separate points, not as a smooth line.","whyCN":"电子学借用了数学义：采样后的波是一串分离的点，而不是一条平滑的线。"},{"no":"07","title":"An isolated group of one species","titleCN":"生态上分离的种群","definition":"a group of organisms of one species that is separated from other groups and breeds mainly within itself","definitionCN":"同一物种中与其他群体隔开、主要在群体内部繁殖的一群生物","example":"The valley holds a discrete population of frogs.","exampleCN":"这条山谷里有一个分离的蛙类种群。","why":"Ecology reused the notion of a bounded unit: a population with a clear edge is separate from its neighbours.","whyCN":"生态学沿用了「有边界的单元」这一概念：边界清楚的种群与邻近种群分开。"},{"no":"08","title":"A model that jumps between events","titleCN":"离散事件模拟","definition":"a computer model in which the state changes only at separate scheduled events rather than continuously","definitionCN":"一种计算机模型，其状态只在分离的预定事件发生时改变，而不是连续变化","example":"The airport model is a discrete simulation of gate use.","exampleCN":"这个机场模型是对登机口使用情况的离散模拟。","why":"Simulation inherited the word from mathematics and computing, because the model steps from one event to the next.","whyCN":"模拟技术从数学与计算领域继承了这个词，因为模型是从一个事件跳到下一个事件。"}],"etymology":{"intro":{"en":"Discrete comes from Latin discretus, the past participle of discernere, to separate or distinguish, formed from dis-, apart, and cernere, to sift. The same participle also produced discreet, the word for cautious behaviour, so the two English adjectives are homophones with different meanings.","cn":"这个词来自拉丁语「discretus」，是动词「discernere」（分开、辨别）的过去分词，由「dis-」（分开）加「cernere」（筛、辨别）构成。同一个分词也演化出表示言行谨慎的「discreet」，因此这两个英语形容词同音而异义。"},"items":[{"era":"LATIN DIS-","en":"The prefix meant apart or away, and it marks the act of putting things at a distance from one another.","cn":"这个前缀表示分开、离开，标记把事物彼此拉开距离的动作。"},{"era":"LATIN CERNERE","en":"The verb meant to sift, to separate and to distinguish, the image behind a sieve or a screen.","cn":"这个动词意为筛、分开、辨别，其意象来自筛子或筛网。"},{"era":"LATIN DISCERNERE","en":"With the prefix added, the verb meant to separate apart and hence to tell one thing from another.","cn":"加上前缀之后，这个动词意为分开，进而指把一事物与另一事物辨别开来。"},{"era":"LATIN DISCRETUS","en":"The past participle meant separated or distinguished, and it became the direct source of the English adjective.","cn":"这个过去分词意为被分开的或被辨别出的，后来成为这个英语形容词的直接来源。"},{"era":"ENGLISH DISCRETE","en":"English adopted the form for things that stand apart, especially in mathematics and later in computing.","cn":"英语采用这一形式表示彼此分开的事物，尤见于数学，后来又用于计算领域。"},{"era":"THE DISCREET SPLIT","en":"The same Latin participle also gave English discreet, meaning careful in speech or behaviour; the two words sound alike but must not be confused.","cn":"同一个拉丁分词还给了英语「discreet」，意为言行谨慎；两个词读音相同，但不可混淆。"}]},"similar":{"note":{"en":"The first group gathers forms that look or sound like discrete; the second group gathers words for separation and difference.","cn":"第一组收录在形音上与「discrete」相近的形式；第二组收录表示分开与差异的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"discreet","ipa":"/dɪˈskriːt/","tag":"homophone, different meaning","definition":"Careful and prudent in speech or behaviour; it sounds the same as discrete but belongs to a different sense of the same Latin participle.","definitionCN":"指说话或举止谨慎小心；与「discrete」读音相同，但属于同一拉丁分词的另一义。"},{"word":"discreetly","ipa":"/dɪˈskriːtli/","tag":"homophone family","definition":"In a careful and prudent manner, with no relation to separate units.","definitionCN":"指以谨慎小心的方式，与「分离的单元」无关。"},{"word":"discretion","ipa":"/dɪˈskreʃn/","tag":"same root","definition":"The freedom or power to decide, and the quality of being careful about what one says.","definitionCN":"指决定权或裁量权，也指说话谨慎的品质。"},{"word":"discern","ipa":"/dɪˈsɜːn/","tag":"same root","definition":"To perceive or distinguish something that is not obvious.","definitionCN":"指察觉或辨别不明显的事物。"},{"word":"discrepancy","ipa":"/dɪsˈkrepənsi/","tag":"different root","definition":"A difference between two things that should agree; it looks close but comes from another Latin verb.","definitionCN":"指本应一致的两事物之间的差异；形近但来自另一个拉丁动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"separate","ipa":"/ˈsepərət/","tag":"near meaning","definition":"Apart from others, not joined or shared.","definitionCN":"指与他人分开、不连接或不共有的。"},{"word":"distinct","ipa":"/dɪˈstɪŋkt/","tag":"near meaning","definition":"Clearly different and easily told apart from something else.","definitionCN":"指明显不同、容易与其他事物区分开的。"},{"word":"individual","ipa":"/ˌɪndɪˈvɪdʒuəl/","tag":"near meaning","definition":"Single and considered on its own, apart from the group.","definitionCN":"指单个的、单独看待而不计入群体的。"},{"word":"discontinuous","ipa":"/ˌdɪskənˈtɪnjuəs/","tag":"near meaning","definition":"Broken off and not continuing without a gap.","definitionCN":"指中断的、不能无间隔延续的。"},{"word":"detached","ipa":"/dɪˈtætʃt/","tag":"near meaning","definition":"Separated from something it was once connected to.","definitionCN":"指与原先把连在一起的事物分开的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin sieve behind the word, the real spelling contrast with discreet, and the real technical phrases.","cn":"正常联想使用这个词背后的拉丁筛子、与「discreet」的真实拼写差别，以及真实的技术搭配。"},"normal":[{"en":"Cernere is to sift: discrete things have already been sifted apart.","cn":"「cernere」是筛，离散的事物已经被筛分开。"},{"en":"In discrete the two e letters are separated by t, which is exactly what the word means.","cn":"「discrete」里的两个「e」被「t」隔开，正好就是这个词的意思。"},{"en":"In discreet the two e letters sit together, a neat sign that the word is not about separation.","cn":"「discreet」里的两个「e」挨在一起，正好提示这个词与分离无关。"},{"en":"Discrete data, discrete points and discrete steps are ordinary terms in statistics and computing.","cn":"离散数据、离散点与离散步骤是统计与计算领域的常用说法。"},{"en":"A discrete event happens at one scheduled moment, so the model jumps from event to event.","cn":"离散事件在某个预定时刻发生，因此模型从一个事件跳到下一个事件。"}],"abstract":[{"en":"A discrete thing is a bead on a string: the string is continuous, the beads are not.","cn":"离散之物像线上的珠子：线是连续的，珠子不是。"},{"en":"Separateness can be a virtue: clear units are easier to count, store and compare.","cn":"分开也可以是一种优点：清楚的单元更容易计数、保存与比较。"},{"en":"The quiet danger is the homophone: the careful adviser is discreet, the separate unit is discrete.","cn":"无声的危险在同音：谨慎的顾问是「discreet」，分开的单元是「discrete」。"}]},"examples":[{"en":"The samples fall into three discrete groups.","cn":"样本分成三个彼此独立的组。"},{"en":"She keeps her work and home life discrete.","cn":"她把工作与家庭生活分开。"},{"en":"The software records each keystroke as a discrete event.","cn":"该软件把每次按键记录为一个离散事件。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迪斯克瑞特」——两段彼此断开叫分开，信号只在点上取值叫离散：分开、离散","word":"discrete"},"root":"拉丁语「discretus」←「discernere」「分开、辨别」←「dis-」「分开」+「cernere」「筛、辨别」；同一个分词又演化出「discreet」「谨慎的」，二者同音异义，具体派生年代各家标注不一。","sensesIntro":{"en":"Eight senses move from simple separation to technical modelling: separate units, mathematical values, stored data, broken stages, individual cases, sampled signals, isolated populations, and event-driven simulation.","cn":"八个义项从简单分开走向技术建模：分离的单元、数学取值、存储数据、分段阶段、个别案例、采样信号、隔离种群、事件驱动模拟。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of lamps stands apart, each with its own switch and its own dark gap.","cn":"核心意象：一排灯各自独立，每盏都有自己的开关与暗缝。"},"chain":["SEPARATE UNIT","COUNTED VALUE","STORED RECORD","BROKEN STAGE","SAMPLED SIGNAL","SCHEDULED EVENT"],"branches":[{"senses":"01 · 05","en":"THE SEPARATE ITEM: one unit stands apart, and attention can rest on that single case.","cn":"分开的个体：一个单元独立存在，注意力也可以落在这单个案例上。"},{"senses":"02 · 03","en":"THE COUNTED VALUE: numbers and records exist as separate points rather than a smooth range.","cn":"计数的值：数值与记录以分离的点存在，而不是平滑区间。"},{"senses":"04","en":"THE CUT PROCESS: a whole is divided into stages with clear gaps between them.","cn":"切分的过程：整体被分成有明显间隔的阶段。"},{"senses":"06","en":"THE SAMPLED WAVE: a signal lives only at separate instants in a digital system.","cn":"采样的波：信号在数字系统中只存在于分离的时刻。"},{"senses":"07 · 08","en":"THE BOUNDED MODEL: an isolated population and a simulation that steps from event to event.","cn":"有边界的模型：隔离的种群，以及逐个事件推进的模拟。"}]},"affixes":{"intro":{"en":"Discrete is the adjective of a Latin verb of separating, and its family includes both the technical words and the dangerous homophone.","cn":"这个形容词出自一个表示分开的拉丁动词，其词族既包括技术词，也包括那个危险的同音词。"},"latinIntro":{"en":"Latin supplies cernere, discernere and the participle discretus; the last form is the immediate source of the English adjective.","cn":"拉丁语提供了「cernere」、「discernere」与分词「discretus」；最后一个形式是这个英语形容词的直接来源。"},"items":[{"word":"dis-","structure":"Latin prefix","meaning":"apart, away","meaningCN":"分开；离开","example":"The prefix pulls the two units apart.","exampleCN":"这个前缀把两个单元拉开。"},{"word":"cernere","structure":"Latin verb","meaning":"to sift, to separate, to distinguish","meaningCN":"筛；分开；辨别","example":"The sieve image sits at the centre of the family.","exampleCN":"筛子的意象处在这个词族的中心。"},{"word":"discernere","structure":"Latin verb from dis- and cernere","meaning":"to separate apart, to distinguish","meaningCN":"分开；辨别","example":"The verb names the act of telling things apart.","exampleCN":"这个动词指把事物辨别开来的动作。"},{"word":"discretus","structure":"Latin past participle of discernere","meaning":"separated, distinguished","meaningCN":"被分开的；被辨别出的","example":"The participle became the English adjective.","exampleCN":"这个分词变成了这个英语形容词。"},{"word":"-tus","structure":"Latin participle ending","meaning":"having been made or done","meaningCN":"已经被……的","example":"The ending marks a completed act.","exampleCN":"这个词尾标记已完成的动作。"},{"word":"discrete","structure":"English adjective from discretus","meaning":"separate, not continuous","meaningCN":"分开的；不连续的","example":"English kept the meaning of standing apart.","exampleCN":"英语保留了「彼此分开」的意思。"},{"word":"discreet","structure":"English adjective from the same participle","meaning":"careful in speech or behaviour","meaningCN":"言行谨慎的","example":"The same source split into two English words.","exampleCN":"同一来源分成了两个英语词。"},{"word":"discretion","structure":"English noun from Latin discretio","meaning":"the power to decide; cautious judgement","meaningCN":"裁量权；谨慎判断","example":"The noun belongs with the cautious branch.","exampleCN":"这个名词属于「谨慎」那一支。"},{"word":"indiscrete","structure":"English adjective with a negative prefix","meaning":"not separated or divided","meaningCN":"未分开的；不分明的","example":"The negation returns to the literal idea of separation.","exampleCN":"否定前缀回到字面上的「分开」之意。"}],"latinEntries":[{"word":"cernere","structure":"Latin verb","meaning":"to sift, to separate","meaningCN":"筛；分开"},{"word":"discernere","structure":"Latin verb from dis- and cernere","meaning":"to separate apart, to distinguish","meaningCN":"分开；辨别"},{"word":"discretus","structure":"Latin past participle","meaning":"separated, distinguished","meaningCN":"被分开的；被辨别出的"},{"word":"discretio","structure":"Latin noun from discernere","meaning":"a separation, a distinction","meaningCN":"分离；区分"}],"derivatives":[{"word":"discretely","pos":"adv.","zh":"由该形容词加副词尾构成，义为「分开地；离散地」"},{"word":"discreteness","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「离散性」"},{"word":"discretize","pos":"v.","zh":"由该形容词加动词尾构成，义为「使离散化」"},{"word":"discretization","pos":"n.","zh":"由离散化动词加名词尾构成，义为「离散化」"},{"word":"indiscrete","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「未分开的」"}]}},{"word":"account for","ipa_uk":"/əˈkaʊnt fɔː(r)/","ipa_us":"/əˈkaʊnt fɔːr/","definition_zh":"解释；说明；占比例；报账；对行为负责；清点；计入","definition_en":"to explain or answer for something, to form a part of a total, or to give a reckoning of money, goods or conduct","core_image":"账房桌上摊开一本账簿，左页记进项，右页记去向，掌柜用笔逐条对上","scene":"月底账房把账簿摊在桌上，左边记进项，右边记去向，掌柜用笔逐条对上。The manager must account for every sum in the ledger.","sceneCN":"这里指对每一笔款项作出说明（第 1 个义项：解释原因）；句意为经理必须对账簿里的每一笔金额作出交代。图中可辨识物件：账簿、毛笔、封存的票据。","pos":[{"tag":"phr.","zh":"解释；说明；占比例；报账；负责"}],"collocations":[{"phrase":"account for the difference","zh":"解释差异"},{"phrase":"account for a large share","zh":"占很大比例"},{"phrase":"account for the delay","zh":"说明延误原因"},{"phrase":"account for all spending","zh":"报清全部开支"},{"phrase":"account for one's actions","zh":"为行为负责"},{"phrase":"account for the missing items","zh":"清点缺失物品"},{"phrase":"account for rising costs","zh":"把成本上升计入考虑"}],"forms":[{"label":"原形短语","form":"account for"},{"label":"第三人称单数","form":"accounts for"},{"label":"过去式","form":"accounted for"},{"label":"过去分词","form":"accounted for"},{"label":"现在分词","form":"accounting for"},{"label":"名词形式","form":"account"}],"derivatives":[{"word":"account","pos":"n. / v.","zh":"短语的核心名词兼动词，义为「账目；说明」"},{"word":"accountable","pos":"adj.","zh":"由短语核心词加形容词尾构成，义为「负有交代责任的」"},{"word":"accountability","pos":"n.","zh":"由该形容词加名词尾构成，义为「问责；责任」"},{"word":"accounting","pos":"n.","zh":"由核心动词加名词尾构成，义为「会计；记账」"},{"word":"accountant","pos":"n.","zh":"由核心词加表示施动者的名词尾构成，义为「会计员」"}],"senses":[{"no":"01","title":"To explain a cause","titleCN":"解释原因","definition":"to give a reason or explanation for something that happened","definitionCN":"为已经发生的事给出理由或解释","example":"The engineer can account for the delay in the schedule.","exampleCN":"工程师能够解释进度延误的原因。","why":"The word began as a reckoning of money, and a reckoning is first of all a statement that answers a question.","whyCN":"这个词最初指银钱的清算，而清算首先就是一份回答问题的交代。"},{"no":"02","title":"To explain a difference or phenomenon","titleCN":"说明差异或现象","definition":"to show why two things differ or why an observed fact is as it is","definitionCN":"说明两件事为何不同，或说明观察到的现象为何如此","example":"The new model will account for the gap between the two readings.","exampleCN":"新模型将说明两次读数之间差距的由来。","why":"An account must balance two sides, so the phrase naturally covers explaining a gap rather than only naming a cause.","whyCN":"账目必须两边对得上，因此这个短语自然可以说明差距的由来，而不只是指出一个原因。"},{"no":"03","title":"To form a share of a total","titleCN":"占总量的一个比例","definition":"to be a particular part of a whole, usually expressed as a number or percentage","definitionCN":"构成整体中的某个部分，通常用数字或百分比表示","example":"Renewable sources may account for a third of the grid.","exampleCN":"可再生能源可能占电网供应的三分之一。","why":"In a ledger each entry has a size, and that size as a share of the total became the modern statistical sense.","whyCN":"账簿里每一笔都有大小，而它占总数的份额就成了现代统计义。"},{"no":"04","title":"To make up a total","titleCN":"构成总量的组成部分","definition":"to be the substance or component of a whole, considered as one of its parts","definitionCN":"作为一个部分，构成整体的实质或成分","example":"Small firms can account for most of the new jobs.","exampleCN":"小企业可能构成大部分新增岗位。","why":"The same arithmetic picture is read from the other side: the part does not merely occupy a share, it makes up the whole.","whyCN":"同一幅算术图从另一侧读：部分不只是占了份额，而是把整体组成起来。"},{"no":"05","title":"To give a reckoning of money","titleCN":"报账说明资金","definition":"to record and explain how money received or spent has been used","definitionCN":"记录并说明收到或花出的钱是如何使用的","example":"The treasurer must account for the funds received in March.","exampleCN":"财务主管必须说明三月收到的资金去向。","why":"This is the oldest sense: an account is a written reckoning presented to someone who has the right to check it.","whyCN":"这是最古老的义项：账目就是呈交给有权核查者的一份书面清算。"},{"no":"06","title":"To answer for one's conduct","titleCN":"为行为负责交代","definition":"to take responsibility for an action and accept that one may be questioned or blamed for it","definitionCN":"对某一行为承担责任，并接受因此受到质询或责备","example":"The officer will account for his decision to the board.","exampleCN":"这名官员将向董事会为自己的决定作出交代。","why":"Money and conduct are both things that can be rendered up to another person, so the financial phrase extended to moral duty.","whyCN":"钱和行为都是可以向他人交出的东西，因此这个财务短语扩展到了道义责任。"},{"no":"07","title":"To check goods one by one","titleCN":"清点核对","definition":"to list and check every item or unit so that the record matches what is present","definitionCN":"逐项列出并核对每个物品或单位，使记录与实际相符","example":"Two clerks can account for every item in the store.","exampleCN":"两名职员能够把仓库里的每件物品清点清楚。","why":"A shopkeeper counts stock before writing the account, so counting and accounting share one verb.","whyCN":"店主先清点存货再记账，因此清点与记账共用同一个动词。"},{"no":"08","title":"To include in a calculation or plan","titleCN":"计入考虑","definition":"to include something as a factor when judging, planning or calculating","definitionCN":"在判断、计划或计算时把某事物作为一个因素纳入","example":"The budget should account for the rise in fuel costs.","exampleCN":"预算应当把燃料成本上升计入考虑。","why":"The modern planning sense treats every relevant factor as an entry that must appear on the ledger.","whyCN":"现代规划义把每个相关因素都当作账簿上必须出现的一笔。"}],"etymology":{"intro":{"en":"Account comes through Old French acont, a reckoning, from the verb conter, to count, which goes back to Latin computare, to reckon together, formed from com-, together, and putare, to reckon or estimate. For is a native English preposition, and the phrase settled in the sixteenth and seventeenth centuries.","cn":"这个词经古法语「acont」「算账」而来，源头是动词「conter」「计数」，再往前是拉丁语「computare」「一起清算」，由「com-」「一起」和「putare」「清算、估算」构成。「for」是英语本族介词，这个短语在十六至十七世纪固定下来。"},"items":[{"era":"LATIN PUTARE","en":"The verb meant to reckon, to estimate and also to prune, and the reckoning image runs through the whole family.","cn":"这个动词意为清算、估算，也有修剪之意，清算的意象贯穿整个词族。"},{"era":"LATIN COMPUTARE","en":"With com-, together, the verb meant to reckon things up together, the source of count, compute and account.","cn":"加上表示「一起」的「com-」，动词意为把各项一起清算，是「count」「compute」「account」的共同来源。"},{"era":"OLD FRENCH CONTER","en":"French kept the counting sense and used it both for numbers and for telling a story.","cn":"法语保留了计数义，既用于数字，也用于讲述一件事。"},{"era":"OLD FRENCH ACONT","en":"The noun meant a reckoning or a statement of what was owed, and English borrowed it as account.","cn":"这个名词意为清算或应付账款的说明，英语把它借入为「account」。"},{"era":"ENGLISH ACCOUNT","en":"English used the noun for a financial record and the verb for giving an explanation or a report.","cn":"英语把这一名词用于财务记录，把动词用于作出解释或报告。"},{"era":"THE PHRASE FIXES","en":"From the sixteenth century, account for was used for answering for money and conduct, and by the seventeenth century for explaining and for forming a share.","cn":"自十六世纪起，「account for」用于为钱财和行为作出交代，到十七世纪又用于解释原因和构成比例。"}]},"similar":{"note":{"en":"The first group gathers forms built on the same counting word; the second group gathers verbs that explain, compose or answer.","cn":"第一组收录建立在同一个计数词上的形式；第二组收录表示解释、构成或交代的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"account","ipa":"/əˈkaʊnt/","tag":"same root","definition":"A record of money, or a spoken report; the core noun and verb behind the phrase.","definitionCN":"指账目或口头说明；是该短语背后的核心名词与动词。"},{"word":"accountable","ipa":"/əˈkaʊntəbl/","tag":"same root","definition":"Required to explain and answer for one's actions.","definitionCN":"指有责任为自己的行为作出解释与交代的。"},{"word":"accounting","ipa":"/əˈkaʊntɪŋ/","tag":"same root","definition":"The work of keeping and checking financial records.","definitionCN":"指记录与核查财务账目的工作。"},{"word":"discount","ipa":"/ˈdɪskaʊnt/","tag":"different prefix","definition":"A reduction in price; the opposite prefix pulls the counting word in another direction.","definitionCN":"指价格减免；相反的前缀把计数词引向另一方向。"},{"word":"count","ipa":"/kaʊnt/","tag":"same root","definition":"To say numbers in order or to find how many there are.","definitionCN":"指按顺序数数，或求出一共有多少。"}]},{"heading":"NEAR MEANING","entries":[{"word":"explain","ipa":"/ɪkˈspleɪn/","tag":"near meaning","definition":"To make something clear by giving details or reasons.","definitionCN":"指通过给出细节或理由使某事物清楚。"},{"word":"constitute","ipa":"/ˈkɒnstɪtjuːt/","tag":"near meaning","definition":"To be the parts that make up a whole.","definitionCN":"指构成整体的各部分。"},{"word":"comprise","ipa":"/kəmˈpraɪz/","tag":"near meaning","definition":"To consist of or be made up of particular parts.","definitionCN":"指由某些部分构成。"},{"word":"justify","ipa":"/ˈdʒʌstɪfaɪ/","tag":"near meaning","definition":"To show that an action or claim has a good reason.","definitionCN":"指证明某一行为或说法有正当理由。"},{"word":"report","ipa":"/rɪˈpɔːt/","tag":"near meaning","definition":"To give a formal spoken or written account of something.","definitionCN":"指对某事作正式的口头或书面报告。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the ledger behind the word, its counting family, and the real phrases of money and share.","cn":"正常联想使用这个词背后的账簿、它的计数词族，以及钱财与比例的真实搭配。"},"normal":[{"en":"An account is first a ledger, and to account for is to make the ledger balance.","cn":"账目首先是一本账簿，而「account for」就是让账簿对得上。"},{"en":"Count, compute, account and accountant all descend from the same Latin reckoning word.","cn":"「count」「compute」「account」与「accountant」都出自同一个拉丁清算词。"},{"en":"To account for money is to say where it went; to account for a delay is to say why it happened.","cn":"为钱财作出交代是说钱去了哪里；为延误作出交代是说明它为何发生。"},{"en":"In a report, a group that accounts for a third is one of three equal parts.","cn":"在报告里，占三分之一的群体就是三等份中的一份。"},{"en":"Account for every item is the stocktaker's phrase: nothing may be left off the list.","cn":"「把每件物品都清点清楚」是盘点人的说法：清单上不能漏掉任何一项。"}],"abstract":[{"en":"Every explanation is a small ledger: cause on one side, effect on the other, and the two must balance.","cn":"每一种解释都是一本小账簿：一边是原因，一边是结果，两边必须对得上。"},{"en":"A share is a number with a seat in the whole; accounting for it is giving that seat a name.","cn":"份额是整体中占一个位置的数字；说明它，就是给那个位置一个名字。"},{"en":"Responsibility begins when someone asks you to account for what you did, not for what you meant.","cn":"责任始于别人要求你交代做了什么，而不是交代你想做什么。"}]},"examples":[{"en":"The audit must account for the missing fuel.","cn":"审计必须说明缺失燃料的去向。"},{"en":"Women can account for nearly half of the workforce.","cn":"女性可能占劳动力的近一半。"},{"en":"He could not account for the broken seal.","cn":"他无法解释封条为何破损。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿康特·佛」——账要对得上，原因要说得出：解释、占比、报账","word":"account for"},"root":"古法语「acont」「算账」←「conter」「计数」← 拉丁语「computare」「一起清算」=「com-」「一起」+「putare」「清算、估算」；「for」为英语本族介词，短语于十六至十七世纪固定。","sensesIntro":{"en":"Eight senses fan out from the ledger: explaining a cause, explaining a difference, taking a share, making up a total, reporting money, answering for conduct, checking stock, and including a factor in a plan.","cn":"八个义项从账簿向外展开：解释原因、说明差异、占比例、构成总量、报账、为行为负责、清点存货、把因素计入计划。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ledger lies open, entries on both sides, and a brush moves down the column until the sums agree.","cn":"核心意象：账簿摊开，两边都是条目，笔沿着栏目往下走，直到数目相符。"},"chain":["LEDGER OPENED","ENTRY WRITTEN","SUM CHECKED","REASON GIVEN","SHARE COUNTED","DUTY ANSWERED"],"branches":[{"senses":"01 · 02","en":"THE EXPLANATION: a cause is named, and a puzzling difference is made to balance.","cn":"解释：指出一个原因，并让令人困惑的差异对得上。"},{"senses":"03 · 04","en":"THE SHARE: a part is measured against the whole, and then treated as what makes the whole up.","cn":"份额：部分被放在整体中衡量，随后又被视为构成整体的成分。"},{"senses":"05 · 07","en":"THE RECKONING: money is reported and stock is counted until the record matches the shelf.","cn":"清算：报告款项并清点存货，直到记录与货架相符。"},{"senses":"06","en":"THE ANSWER: conduct is handed over to someone with the right to question it.","cn":"交代：行为被交给有权质询的人。"},{"senses":"08","en":"THE FACTOR: a future cost or condition becomes an entry that the plan must include.","cn":"因素：未来的成本或条件成为计划必须列入的一笔。"}]},"affixes":{"intro":{"en":"The phrase is built from a Latin counting word and a native English preposition, and its family is full of money words.","cn":"这个短语由一个拉丁计数词和一个英语本族介词构成，其词族里满是与钱有关的词。"},"latinIntro":{"en":"Latin supplies putare and computare; Old French shortened the verb to conter and the noun to acont before English took them.","cn":"拉丁语提供了「putare」与「computare」；古法语把动词缩短为「conter」、名词缩短为「acont」，英语随后借用。"},"items":[{"word":"com-","structure":"Latin prefix","meaning":"together, with","meaningCN":"一起；共同","example":"The prefix gathers separate sums into one total.","exampleCN":"这个前缀把分开的数目聚成一个总数。"},{"word":"putare","structure":"Latin verb","meaning":"to reckon, to estimate, to prune","meaningCN":"清算；估算；修剪","example":"The verb is the seed of the whole counting family.","exampleCN":"这个动词是整个计数词族的种子。"},{"word":"computare","structure":"Latin verb from com- and putare","meaning":"to reckon together, to calculate","meaningCN":"一起清算；计算","example":"It is the source of count and compute.","exampleCN":"它是「count」与「compute」的来源。"},{"word":"conter","structure":"Old French verb from computare","meaning":"to count, to tell","meaningCN":"计数；讲述","example":"French used one verb for numbers and for narrative.","exampleCN":"法语用同一个动词表示数字与叙述。"},{"word":"acont","structure":"Old French noun from conter","meaning":"a reckoning, a statement of what is owed","meaningCN":"清算；应付账款的说明","example":"The noun came into English as account.","exampleCN":"这个名词进入英语成为「account」。"},{"word":"for","structure":"English preposition","meaning":"with respect to, on behalf of","meaningCN":"关于；为","example":"The native preposition marks what the account is about.","exampleCN":"这个本族介词标出账目所涉及的对象。"},{"word":"account","structure":"English noun and verb","meaning":"a record of money; to explain","meaningCN":"账目；说明","example":"English split the borrowed noun and verb.","exampleCN":"英语把借来的名词与动词兼用。"},{"word":"-able","structure":"English adjective ending","meaning":"capable of being","meaningCN":"能够被……的","example":"It forms the word for being answerable.","exampleCN":"它构成表示「应被交代」的词。"},{"word":"-ing","structure":"English noun ending","meaning":"the act or process","meaningCN":"动作或过程","example":"It names the work of keeping books.","exampleCN":"它指记账这项工作。"}],"latinEntries":[{"word":"putare","structure":"Latin verb","meaning":"to reckon, to estimate","meaningCN":"清算；估算"},{"word":"computare","structure":"Latin verb from com- and putare","meaning":"to reckon together, to calculate","meaningCN":"一起清算；计算"},{"word":"computatio","structure":"Latin noun from computare","meaning":"a reckoning, a calculation","meaningCN":"清算；计算"},{"word":"imputare","structure":"Latin verb from in- and putare","meaning":"to charge to an account","meaningCN":"记入账上；归账"}],"derivatives":[{"word":"accountable","pos":"adj.","zh":"由短语核心词加形容词尾构成，义为「负有交代责任的」"},{"word":"accountability","pos":"n.","zh":"由该形容词加名词尾构成，义为「问责；责任」"},{"word":"accounting","pos":"n.","zh":"由核心动词加名词尾构成，义为「会计；记账」"},{"word":"accountant","pos":"n.","zh":"由核心词加表示施动者的名词尾构成，义为「会计员」"},{"word":"account","pos":"n.","zh":"短语核心词的名词形式，义为「账目；说明」"}]}},{"word":"adapt to","ipa_uk":"/əˈdæpt tuː/","ipa_us":"/əˈdæpt tuː/","definition_zh":"适应；使适应；改编；调整以适合；改装","definition_en":"to change or be changed so as to fit new conditions, a new medium or a new purpose","core_image":"苗圃里一排幼苗从温室搬到露天，头几天盖着遮阳网，叶片慢慢转向新的光照","scene":"苗圃把温室里的幼苗搬到露天，头几天盖着遮阳网，叶片慢慢转向新的光照。Young plants can adapt to stronger light within a week.","sceneCN":"这里指生物对新光照条件逐渐适应（第 1 个义项：适应环境气候）；句意为幼苗能在一周内适应更强的光照。图中可辨识物件：幼苗、遮阳网、温室门。","pos":[{"tag":"phr.","zh":"适应；使适应；改编；调整"}],"collocations":[{"phrase":"adapt to the climate","zh":"适应气候"},{"phrase":"adapt to new conditions","zh":"适应新条件"},{"phrase":"adapt to change","zh":"适应变化"},{"phrase":"adapt to local customs","zh":"顺应当地习俗"},{"phrase":"adapt to a new job","zh":"适应新工作"},{"phrase":"adapt to the environment","zh":"适应环境"},{"phrase":"adapt to the equipment","zh":"适应设备"}],"forms":[{"label":"原形短语","form":"adapt to"},{"label":"第三人称单数","form":"adapts to"},{"label":"过去式","form":"adapted to"},{"label":"过去分词","form":"adapted to"},{"label":"现在分词","form":"adapting to"},{"label":"派生名词","form":"adaptation"}],"derivatives":[{"word":"adaptation","pos":"n.","zh":"由该动词加名词尾构成，义为「适应；改编作品」"},{"word":"adaptable","pos":"adj.","zh":"由该动词加形容词尾构成，义为「能适应的；可改编的」"},{"word":"adaptability","pos":"n.","zh":"由该形容词加名词尾构成，义为「适应性；可改编性」"},{"word":"adapter","pos":"n.","zh":"由该动词加表示器具或施动者的名词尾构成，义为「适配器；改编者」"},{"word":"adaptive","pos":"adj.","zh":"由该动词加形容词尾构成，义为「适应的；有适应性的」"}],"senses":[{"no":"01","title":"To suit a climate or habitat","titleCN":"适应气候与生境","definition":"to become suited to the temperature, light, water or other conditions of a place","definitionCN":"逐渐适合某地的温度、光照、水分或其他条件","example":"Polar plants can adapt to extreme cold.","exampleCN":"极地植物能够适应极度寒冷。","why":"The Latin verb meant to fit, and the first thing a living thing must fit is the place it lives in.","whyCN":"这个拉丁动词意为使合适，而生物首先要合适的就是它所居住的地方。"},{"no":"02","title":"To adjust to a new situation","titleCN":"适应新情况","definition":"to change one's habits or expectations so as to work within new circumstances","definitionCN":"改变习惯或预期，以便在新环境中运转","example":"The staff will adapt to the new timetable.","exampleCN":"员工将会适应新的时间表。","why":"Once fitting is applied to human arrangements, it covers shifts in work, rules and daily rhythm.","whyCN":"一旦「使合适」用于人的安排，就涵盖了工作、规则与日常节奏的变化。"},{"no":"03","title":"To make something fit","titleCN":"使某物适合","definition":"to alter a person or thing so that it fits a requirement or a group","definitionCN":"改变人或事物，使其符合某项要求或某一群体","example":"A good teacher can adapt to mixed abilities in one class.","exampleCN":"好老师能够适应一个班里参差不齐的能力。","why":"The verb is transitive in Latin, so English can put the thing being fitted either as its object or behind the phrase.","whyCN":"这个动词在拉丁语里是及物的，因此英语既可把被调整之物放在宾语位置，也可放在短语之后。"},{"no":"04","title":"To adapt a work for another medium","titleCN":"把作品改编成另一形式","definition":"to change a story, play or piece of music so that it can be presented in a different medium or for a different audience","definitionCN":"改动故事、戏剧或音乐，使其能以另一种媒介呈现或面向另一批受众","example":"The studio can adapt to television by splitting the novel into six parts.","exampleCN":"制片方可以把这部小说拆成六集，以改编成电视作品。","why":"A work must fit a new stage, screen or page, and the word for fitting became the word for rewriting.","whyCN":"作品必须适合新的舞台、银幕或版面，于是「使适合」这个词变成了「改编」。"},{"no":"05","title":"To adjust a plan so that it fits","titleCN":"调整计划使其适合","definition":"to change a plan, budget or design so that it meets a limit or a need","definitionCN":"改动计划、预算或设计，使其符合某项限制或需求","example":"We can adapt to a smaller budget by cutting travel.","exampleCN":"我们可以削减差旅，以调整方案适应更小的预算。","why":"Planning repeats the same fit: means are trimmed until they match the available resources.","whyCN":"规划重复着同一个「合适」：手段被削减，直到与可用资源相配。"},{"no":"06","title":"To adjust bodily to a stimulus","titleCN":"生理上适应刺激","definition":"to undergo a bodily change that reduces the response to a repeated stimulus","definitionCN":"身体发生变化，使对重复刺激的反应减弱","example":"Eyes can adapt to dim light after a few minutes.","exampleCN":"眼睛几分钟后就能适应昏暗的光线。","why":"The body fits itself to its surroundings without conscious design, and physiology kept the same verb.","whyCN":"身体无需有意的设计就能使自己适合环境，生理学沿用了同一个动词。"},{"no":"07","title":"To conform to customs and rules","titleCN":"顺应习俗与规范","definition":"to change one's behaviour so that it agrees with the customs or expectations of a group","definitionCN":"改变自身行为，使其与某群体的习俗或期待相符","example":"Newcomers may adapt to local customs within a year.","exampleCN":"新来者可能一年之内就顺应了当地习俗。","why":"Social life asks people to fit a pattern, and the verb covers that quiet conformity as well as physical change.","whyCN":"社会生活要求人符合某种模式，这个动词既指身体变化，也指这种不声张的顺应。"},{"no":"08","title":"To modify equipment for a new use","titleCN":"改装设备以适应新用途","definition":"to change a device or machine so that it works with new parts, fuel or conditions","definitionCN":"改动装置或机器，使其能配合新的零件、燃料或条件","example":"The workshop can adapt to metric parts by machining new fittings.","exampleCN":"车间可以加工新的接头，使设备适应公制零件。","why":"Tools are fitted to tasks, and a machine altered for a new task is literally made suitable.","whyCN":"工具要被适合任务，为新技术任务而改动的机器正是字面意义上的「被使合适」。"}],"etymology":{"intro":{"en":"Adapt comes from Latin adaptare, to fit something to something, from ad-, to or towards, and aptare, to make fit, from aptus, fit or fastened. English took the verb in the seventeenth century, and the phrase adapt to followed the verb's own construction.","cn":"这个词来自拉丁语「adaptare」「使某物适合某物」，由「ad-」「朝向」和「aptare」「使合适」构成，而「aptare」又出自「aptus」「合适的、系紧的」。英语在十七世纪引入这个动词，短语「adapt to」沿用了动词本身的搭配。"},"items":[{"era":"LATIN APTUS","en":"The adjective meant fit, suitable and also fastened, so fitness and attachment were one idea.","cn":"这个形容词意为合适的、适宜的，也有系紧之意，因此「合适」与「连接」是同一个概念。"},{"era":"LATIN APTARE","en":"The verb meant to make fit or to fasten, and it gave the action of putting a thing into its proper place.","cn":"这个动词意为使合适或系紧，给出了把事物放到恰当位置的动作。"},{"era":"LATIN AD-","en":"The prefix meant towards, and it turned the fitting into a movement towards a particular condition.","cn":"这个前缀意为朝向，把「使合适」变成了朝某一特定条件靠拢的动作。"},{"era":"LATIN ADAPTARE","en":"The compound meant to fit one thing to another, and it is the direct source of the English verb.","cn":"这个复合词意为使一事物适合另一事物，是这个英语动词的直接来源。"},{"era":"ENGLISH ADAPT","en":"English borrowed the verb in the seventeenth century for fitting, and soon for rewriting a work for a new medium.","cn":"英语在十七世纪借入这个动词表示使适合，很快又用于把作品改写以适合新媒介。"},{"era":"THE PHRASE ADAPT TO","en":"The preposition to marks the condition or purpose that is being fitted, and the phrase became fixed in ordinary and technical English.","cn":"介词「to」标出所适合的条件或目的，这个短语在普通英语与技术英语中固定下来。"}]},"similar":{"note":{"en":"The first group gathers forms that look or sound like adapt; the second group gathers verbs of fitting and changing.","cn":"第一组收录在形音上与「adapt」相近的形式；第二组收录表示使适合与改变的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adapt","ipa":"/əˈdæpt/","tag":"same root","definition":"To fit or be fitted to new conditions; the base verb of the phrase.","definitionCN":"指使适合或被适合新条件；是该短语的基础动词。"},{"word":"adaptation","ipa":"/ˌædæpˈteɪʃn/","tag":"same root","definition":"The process or result of fitting, including a work rewritten for a new medium.","definitionCN":"指适合的过程或结果，也包括为新媒介改写的作品。"},{"word":"adaptable","ipa":"/əˈdæptəbl/","tag":"same root","definition":"Able to be changed so as to fit different conditions.","definitionCN":"指能够被改变以适合不同条件的。"},{"word":"adopt","ipa":"/əˈdɒpt/","tag":"different root","definition":"To take a child or an idea as one's own; it looks close but its Latin verb means to choose.","definitionCN":"指收养孩子或采纳想法；形近但其拉丁动词意为选择。"},{"word":"adept","ipa":"/əˈdept/","tag":"different root","definition":"Highly skilled at something; it looks close but comes from a Latin word for having attained.","definitionCN":"指在某事上非常熟练；形近但出自拉丁语表示「已达到」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adjust","ipa":"/əˈdʒʌst/","tag":"near meaning","definition":"To change something slightly so that it works or fits better.","definitionCN":"指稍作改动使某物运作更好或更合适。"},{"word":"accommodate","ipa":"/əˈkɒmədeɪt/","tag":"near meaning","definition":"To change in order to meet the needs of someone or something.","definitionCN":"指为满足某人或某物的需要而作出改变。"},{"word":"acclimatize","ipa":"/əˈklaɪmətaɪz/","tag":"near meaning","definition":"To become used to a new climate or environment over time.","definitionCN":"指随着时间逐渐习惯新的气候或环境。"},{"word":"modify","ipa":"/ˈmɒdɪfaɪ/","tag":"near meaning","definition":"To change something, often to improve it or give it a new purpose.","definitionCN":"指改动某物，常为改进或赋予新用途。"},{"word":"tailor","ipa":"/ˈteɪlə/","tag":"near meaning","definition":"To make or change something so that it suits a particular person or purpose.","definitionCN":"指制作或改动某物，使其适合特定的人或目的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin sense of fitting, the real family of the verb, and the real phrases of climate, work and equipment.","cn":"正常联想使用拉丁语「使合适」之义、这个动词的真实词族，以及气候、工作与设备的真实搭配。"},"normal":[{"en":"Aptus meant fit and fastened, so adapt began as the act of putting a thing where it belongs.","cn":"「aptus」意为合适的、系紧的，因此「adapt」最初就是把事物放到它该在的位置。"},{"en":"Adapt, adapter, adaptation and adaptable all carry the same idea of fitting.","cn":"「adapt」「adapter」「adaptation」与「adaptable」都带着同一个「使合适」的意思。"},{"en":"The phrase adapt to always needs a target: a climate, a timetable, a budget or a medium.","cn":"短语「adapt to」总需要一个目标：气候、时间表、预算或媒介。"},{"en":"An adapter is a small piece that makes one plug fit another socket, the word's meaning made visible.","cn":"适配器是一个让小插头适合另一插座的小物件，正是这个词的意思变得可见。"},{"en":"Eyes adapt to dim light, workers adapt to new rules, and both are the same quiet fitting.","cn":"眼睛适应暗光，员工适应新规，两者都是同一种不声张的适合。"}],"abstract":[{"en":"To adapt is to keep one's aim while changing one's shape, like water taking the shape of its cup.","cn":"适应就是保持目的而改变形状，像水取杯子的形状。"},{"en":"A species and a story survive by the same move: the form bends so that the core may continue.","cn":"物种与故事靠同一个动作存活：外形弯一弯，核心才能继续。"},{"en":"The deepest adaptation is invisible: the change has finished before anyone notices that it was needed.","cn":"最深的适应是看不见的：变化在别人察觉需要之前就已经完成。"}]},"examples":[{"en":"Desert animals can adapt to heat by resting in shade.","cn":"沙漠动物可以通过在阴凉处休息来适应炎热。"},{"en":"The director will adapt to a smaller stage by cutting two scenes.","cn":"导演会删去两场戏，以适应更小的舞台。"},{"en":"Older workers may adapt to the software after a short course.","cn":"年长员工上完短期课程后可能就适应这款软件了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿达普特·图」——把自己调到合适的位置：适应、改编、改装","word":"adapt to"},"root":"拉丁语「adaptare」「使适合」=「ad-」「朝向」+「aptare」「使合适」←「aptus」「合适的、系紧的」；英语十七世纪引入，短语沿用动词自身搭配。","sensesIntro":{"en":"Eight senses extend the idea of fitting: fitting a climate, fitting a new situation, fitting another person, fitting a work to a medium, fitting a plan to a limit, fitting the body to a stimulus, fitting behaviour to custom, and fitting a machine to new parts.","cn":"八个义项延伸「使合适」这一观念：适合气候、适合新情况、使他人适合、把作品改为另一媒介、让计划适合限制、身体适应刺激、行为顺应习俗、设备配合新零件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a seedling is moved into stronger light, and its leaves turn until they face the new source.","cn":"核心意象：幼苗被移到更强的光下，叶片转动，直到朝向新的光源。"},"chain":["FIT TO A PLACE","TURN TO THE LIGHT","REACH A NEW BALANCE","CHANGE THE FORM","KEEP THE CORE","WORK UNDER NEW RULES"],"branches":[{"senses":"01 · 02","en":"THE LIVING FIT: a plant or a person settles into a climate and a new daily arrangement.","cn":"生命的适合：植物或人安顿进一种气候与新的日常安排。"},{"senses":"03 · 05","en":"THE DELIBERATE FIT: a teacher or a planner alters means until a requirement is met.","cn":"有意的适合：教师或规划者调整手段，直到满足要求。"},{"senses":"04","en":"THE WORK IN A NEW MEDIUM: a story is reshaped for stage, screen or page.","cn":"新媒介中的作品：故事为舞台、银幕或版面重新塑形。"},{"senses":"06","en":"THE BODY'S QUIET FIT: the senses dull their response to a repeated stimulus.","cn":"身体的静默适合：感官对重复刺激的反应逐渐减弱。"},{"senses":"07 · 08","en":"THE SOCIAL AND MECHANICAL FIT: behaviour follows custom, and a machine takes new parts.","cn":"社会与机械的适合：行为随习俗调整，机器换上新的零件。"}]},"affixes":{"intro":{"en":"Adapt is a Latin verb of fitting, and its family covers both the living and the mechanical sides of the idea.","cn":"这是一个表示「使合适」的拉丁动词，其词族涵盖这一观念的生物与机械两面。"},"latinIntro":{"en":"Latin supplies aptus, aptare and adaptare; the adjective aptus is the seed of the whole family.","cn":"拉丁语提供了「aptus」、「aptare」与「adaptare」；形容词「aptus」是整个词族的种子。"},"items":[{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"朝向；向","example":"The prefix points the fitting at a target.","exampleCN":"这个前缀把「使合适」指向一个目标。"},{"word":"aptus","structure":"Latin adjective","meaning":"fit, suitable, fastened","meaningCN":"合适的；适宜的；系紧的","example":"The adjective joins fitness with attachment.","exampleCN":"这个形容词把合适与连接合在一起。"},{"word":"aptare","structure":"Latin verb from aptus","meaning":"to make fit, to fasten","meaningCN":"使合适；系紧","example":"The verb turns the adjective into an action.","exampleCN":"这个动词把形容词变成动作。"},{"word":"adaptare","structure":"Latin verb from ad- and aptare","meaning":"to fit one thing to another","meaningCN":"使一物适合另一物","example":"The compound is the direct source of the English verb.","exampleCN":"这个复合词是这个英语动词的直接来源。"},{"word":"apt","structure":"English adjective from aptus","meaning":"suitable, quick to learn","meaningCN":"合适的；聪敏的","example":"English kept the adjective beside the longer verb.","exampleCN":"英语在较长的动词旁保留了这一形容词。"},{"word":"adapt","structure":"English verb from adaptare","meaning":"to fit or be fitted","meaningCN":"使适合；适应","example":"English shortened the Latin compound.","exampleCN":"英语缩短了这个拉丁复合词。"},{"word":"-ation","structure":"noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms the noun for the process and the rewritten work.","exampleCN":"它构成表示过程与改写作品的名词。"},{"word":"-able","structure":"adjective ending","meaning":"capable of being","meaningCN":"能够被……的","example":"It forms the word for being able to fit.","exampleCN":"它构成表示「能够适合」的词。"},{"word":"-ive","structure":"adjective ending","meaning":"tending to","meaningCN":"倾向于……的","example":"It forms the word for the fitting tendency.","exampleCN":"它构成表示「有适应倾向」的词。"}],"latinEntries":[{"word":"aptus","structure":"Latin adjective","meaning":"fit, suitable","meaningCN":"合适的；适宜的"},{"word":"aptare","structure":"Latin verb from aptus","meaning":"to make fit, to fasten","meaningCN":"使合适；系紧"},{"word":"adaptare","structure":"Latin verb from ad- and aptare","meaning":"to fit one thing to another","meaningCN":"使一物适合另一物"},{"word":"adaptatio","structure":"Latin noun from adaptare","meaning":"a fitting, an adjustment","meaningCN":"适合；调整"}],"derivatives":[{"word":"adaptation","pos":"n.","zh":"由该动词加名词尾构成，义为「适应；改编作品」"},{"word":"adaptable","pos":"adj.","zh":"由该动词加形容词尾构成，义为「能适应的；可改编的」"},{"word":"adaptability","pos":"n.","zh":"由该形容词加名词尾构成，义为「适应性；可改编性」"},{"word":"adapter","pos":"n.","zh":"由该动词加表示器具或施动者的名词尾构成，义为「适配器；改编者」"},{"word":"adaptive","pos":"adj.","zh":"由该动词加形容词尾构成，义为「适应的；有适应性的」"}]}},{"word":"attribute to","ipa_uk":"/əˈtrɪbjuːt tuː/","ipa_us":"/əˈtrɪbjuːt tuː/","definition_zh":"归因于；归功于；认为出自；把……归属于；归咎于","definition_en":"to say that something is caused by, produced by, or belongs to a particular person, thing or circumstance","core_image":"修谱的桌上摊开一卷世系，一支朱笔把新添的名字画回祖辈的方格，旁边注明这一支的来处","scene":"修谱人把新抄的名字放回旧格，再用一支朱笔把名字画回祖辈的方框，并在旁边注明这一支的来处。Historians can attribute to the workshop a set of unsigned panels.","sceneCN":"这里指把一组作品认定出自某个作坊（第 3 个义项：认定作品出自某人）；句意为史学家可以把一组没有署名的画板认定出自那个作坊。图中可辨识物件：世系卷、朱笔、方格、批注。","pos":[{"tag":"phr.","zh":"归因于；归功于；认为出自；归咎于"}],"collocations":[{"phrase":"attribute to climate change","zh":"归因于气候变化"},{"phrase":"attribute to human error","zh":"归因于人为失误"},{"phrase":"attribute to a virus","zh":"归因于病毒"},{"phrase":"attribute to the author","zh":"认为出自该作者"},{"phrase":"attribute to poor planning","zh":"归因于规划不当"},{"phrase":"attribute to a lack of funds","zh":"归因于资金不足"},{"phrase":"attribute to luck","zh":"归功于运气"}],"forms":[{"label":"原形短语","form":"attribute to"},{"label":"第三人称单数","form":"attributes to"},{"label":"过去式","form":"attributed to"},{"label":"过去分词","form":"attributed to"},{"label":"现在分词","form":"attributing to"},{"label":"派生名词","form":"attribution"}],"derivatives":[{"word":"attribution","pos":"n.","zh":"由该动词加名词尾构成，义为「归因；归属；出处」"},{"word":"attributable","pos":"adj.","zh":"由该动词加形容词尾构成，义为「可归因的；可归功的」"},{"word":"attributive","pos":"adj.","zh":"由同一词干加形容词尾构成，义为「定语性的」"},{"word":"attribute","pos":"n.","zh":"短语核心词的名词形式，义为「属性；特征」"},{"word":"misattribute","pos":"v.","zh":"由表示「错误」的前缀加该动词构成，义为「错归；误认为出自」"}],"senses":[{"no":"01","title":"To name a cause","titleCN":"归因于某一原因","definition":"to say that an event or condition was caused by a particular factor","definitionCN":"指出某一事件或状况由某个特定因素造成","example":"Scientists can attribute to volcanic ash the sudden cooling.","exampleCN":"科学家可以把突然降温归因于火山灰。","why":"The Latin verb meant to assign a share, and a cause is the share of responsibility assigned to one factor.","whyCN":"这个拉丁动词意为分派一份，而原因就是分派给某个因素的那一份责任。"},{"no":"02","title":"To credit a person for something good","titleCN":"把好事归功于某人","definition":"to say that a good result was produced by a particular person or group","definitionCN":"认为某个好结果是由某个特定的人或群体带来的","example":"The coach will attribute to the captain the team's revival.","exampleCN":"教练会把球队的复苏归功于队长。","why":"Credit is a share of honour, and the same verb that assigns a cause also assigns praise.","whyCN":"功劳是一份荣誉，分派原因的那个动词也分派赞扬。"},{"no":"03","title":"To name the author of a work","titleCN":"认定作品出自某人","definition":"to say that a painting, book or other work was made by a particular person","definitionCN":"认定一幅画、一部书或其他作品由某个特定的人创作","example":"Scholars may attribute to Titian the unsigned portrait.","exampleCN":"学者可能认为那幅未署名的肖像出自提香。","why":"A work has an origin, and the verb that assigns a cause to a factor also assigns a work to a hand.","whyCN":"作品有其来处，把原因分派给因素的那个动词也把作品分派给某一双手。"},{"no":"04","title":"To assign a quality to someone","titleCN":"把某种特征归属于某人","definition":"to say that a person or thing has a particular quality or characteristic","definitionCN":"认为某人或某物具有某种特定的品质或特征","example":"People can attribute to the breed a calm temperament.","exampleCN":"人们可以把温和的性情归属于这一品种。","why":"A quality is treated as a share laid on a subject, the same arithmetic of assignment as a cause.","whyCN":"品质被当作放在某个主体身上的一份，与原因的分派是同一套算法。"},{"no":"05","title":"To trace a symptom to its cause","titleCN":"把症状归到某个病因","definition":"to say that a symptom or illness was produced by a particular pathogen or condition","definitionCN":"认为某种症状或疾病由某个特定病原体或状况引起","example":"Doctors may attribute to the tick the sudden fever.","exampleCN":"医生可能把突然发热归到蜱虫身上。","why":"Medical tracing repeats the general pattern: an effect is handed back to the thing that produced it.","whyCN":"医学溯源重复着同一模式：结果被交还给产生它的东西。"},{"no":"06","title":"To link a climate effect to warming","titleCN":"把气候现象归因于变暖","definition":"in climate science, to state that a particular weather or ice change was made more likely by global warming","definitionCN":"在气候科学中，指认定某一特定天气或冰情变化因全球变暖而更可能发生","example":"The panel will attribute to warming the shrinking glacier.","exampleCN":"专家组会把冰川退缩归因于变暖。","why":"Climate research made attribution a technical term: the share of risk assigned to a named driver.","whyCN":"气候研究把「归因」变成了术语：把风险的一份分派给某个被指名的驱动因素。"},{"no":"07","title":"To trace something to an origin","titleCN":"溯源到某一源流","definition":"to show that a word, custom or lineage belongs to a particular source or family","definitionCN":"表明一个词、一种习俗或一支血脉属于某个特定源头或族系","example":"Linguists can attribute to the same root two distant dialects.","exampleCN":"语言学家可以把两种相距很远的方言都追溯到同一个词根。","why":"Origin is a place on a family tree, and the verb places a thing on that tree by assigning it a branch.","whyCN":"源头是谱系树上的一个位置，这个动词通过分派一个枝系把事物放到那棵树上。"},{"no":"08","title":"To blame a fault on someone","titleCN":"把过错归咎于某人","definition":"to say that a fault, failure or bad outcome was caused by a particular person","definitionCN":"认为某个过失、失败或坏结果由某个特定的人造成","example":"The inquiry may attribute to the pilot the final error.","exampleCN":"调查可能把最后的失误归咎于飞行员。","why":"When the assigned share is blame, the same neutral verb takes on a hostile edge without changing its structure.","whyCN":"当被分派的那一份是责难时，同一个中性的动词就带上敌意，而结构并未改变。"}],"etymology":{"intro":{"en":"Attribute comes from Latin attribuere, to assign or allot, formed from ad-, to, and tribuere, to divide or give, which goes back to tributum, a tax. The same root produced tribute, contribute and distribute. English took the verb in the sixteenth century, and attribute to became the usual frame for naming a cause, an author or a fault.","cn":"这个词来自拉丁语「attribuere」「分派、给予」，由「ad-」「朝向」和「tribuere」「分配、给予」构成，而「tribuere」出自「tributum」「税」。同一词根还产生「tribute」、「contribute」与「distribute」。英语在十六世纪引入这个动词，短语「attribute to」成为指出原因、作者或过错的常用框架。"},"items":[{"era":"LATIN TRIBUTUM","en":"The noun meant a tax or a payment divided among people, the concrete image of parting out a sum.","cn":"这个名词意为税或按人分摊的款项，是「把钱分出去」的具体意象。"},{"era":"LATIN TRIBUERE","en":"The verb meant to divide, allot or grant, and it named the act of giving each party its share.","cn":"这个动词意为分配、分给、授予，指给每一方一份的动作。"},{"era":"LATIN AD-","en":"The prefix meant to or towards, and it directed the share towards a particular recipient.","cn":"这个前缀意为朝向，把那一份指向某个特定的接受者。"},{"era":"LATIN ATTRIBUERE","en":"The compound meant to assign or impute something to a person or thing, the direct source of the English verb.","cn":"这个复合词意为把某物分派或归到某人某物身上，是这个英语动词的直接来源。"},{"era":"ENGLISH ATTRIBUTE","en":"English borrowed the verb in the sixteenth century and used it for assigning causes, qualities, authors and blame.","cn":"英语在十六世纪借入这个动词，用于分派原因、品质、作者与过错。"},{"era":"THE MODERN PHRASE","en":"The phrase attribute to fixed the target of the assignment, and it now appears in science, law, art history and ordinary argument.","cn":"短语「attribute to」固定了分派的目标，如今出现在科学、法律、艺术史与日常论辩中。"}]},"similar":{"note":{"en":"The first group gathers words built with the same root or a neighbouring prefix; the second group gathers verbs of assigning a cause, an author or a fault.","cn":"第一组收录由同一词根或相近前缀构成的形式；第二组收录表示分派原因、作者或过错的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"attribution","ipa":"/ˌætrɪˈbjuːʃn/","tag":"same root","definition":"The act of saying who or what something comes from, and the name given to that origin.","definitionCN":"指认定某物来自谁或什么的动作，也指由此给出的出处。"},{"word":"attributable","ipa":"/əˈtrɪbjətəbl/","tag":"same root","definition":"Able to be explained by or credited to a particular cause.","definitionCN":"指能够由某一特定原因解释或归于其名下的。"},{"word":"contribute","ipa":"/kənˈtrɪbjuːt/","tag":"same root, different prefix","definition":"To give money, effort or ideas towards a common purpose.","definitionCN":"指为共同目的拿出钱财、努力或想法。"},{"word":"distribute","ipa":"/dɪˈstrɪbjuːt/","tag":"same root, different prefix","definition":"To divide something and give it out among several people or places.","definitionCN":"指把某物分开并分发给若干人或地方。"},{"word":"tribute","ipa":"/ˈtrɪbjuːt/","tag":"same root","definition":"A payment made by one ruler or group to another as a sign of submission.","definitionCN":"指一方统治者或群体向另一方缴纳以示臣服的贡品。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ascribe","ipa":"/əˈskraɪb/","tag":"near meaning","definition":"To say that something belongs to or is caused by a particular person or thing.","definitionCN":"指认为某物属于或由某个特定的人或物引起。"},{"word":"credit","ipa":"/ˈkredɪt/","tag":"near meaning","definition":"To say that someone is responsible for a good result.","definitionCN":"指认为某人应对某个好结果负责。"},{"word":"blame","ipa":"/bleɪm/","tag":"near meaning","definition":"To say that someone or something is at fault for a bad result.","definitionCN":"指认为某人或某物应对坏结果负责。"},{"word":"assign","ipa":"/əˈsaɪn/","tag":"near meaning","definition":"To give a particular role, cause or value to someone or something.","definitionCN":"指把某个角色、原因或数值分派给某人或某物。"},{"word":"impute","ipa":"/ɪmˈpjuːt/","tag":"near meaning","definition":"To say that a fault or quality belongs to someone, often unfairly.","definitionCN":"指把过失或品质归到某人身上，常含不公之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Latin act of handing out a share, the real prefix family, and the real phrases of cause, credit and fault.","cn":"正常联想使用拉丁语中「分出一份」的动作、真实的前缀词族，以及原因、功劳与过错的真实搭配。"},"normal":[{"en":"Tribuere is to divide and give out, so attribute to is to hand a share back to its source.","cn":"「tribuere」是分开并发放，因此「attribute to」就是把一份交还给它该去的地方。"},{"en":"Contribute, distribute and tribute all carry the same offering of a share.","cn":"「contribute」「distribute」与「tribute」都带着同一个「献出一份」的意思。"},{"en":"People attribute a painting to a painter, a fever to a tick, and a failure to a pilot; the frame never changes.","cn":"人们把画归给画家，把发热归给蜱虫，把失败归给飞行员；框架始终不变。"},{"en":"The word often takes the cause as its target: attribute to the storm the delay.","cn":"这个词常把原因放在短语之后：把延误归因于暴风雨。"},{"en":"In climate reports, attribution means the share of risk that a named factor can claim.","cn":"在气候报告里，归因指某个被指名的因素可以认领的那一份风险。"}],"abstract":[{"en":"Attribution is a family tree drawn on the fly: every effect gets a branch, every work gets a hand.","cn":"归因是随手画出的谱系树：每个结果都得到一根枝，每件作品都得到一双手。"},{"en":"The verb is neutral until the share is shame; then assigning a cause becomes assigning blame.","cn":"这个动词本中性，直到那一份是羞耻；此时分派原因就变成分派责难。"},{"en":"To attribute well is to resist the nearest hand: distance makes the difference between evidence and blame.","cn":"善加归因就是抵抗最近的那双手：距离划出证据与责难之间的界线。"}]},"examples":[{"en":"The report will attribute to bad wiring the loss of power.","cn":"报告会把断电归因于线路不良。"},{"en":"Many readers attribute to Homer the whole epic.","cn":"许多读者认为整部史诗出自荷马。"},{"en":"Officials may attribute to heavy rain the closed road.","cn":"官员可能把道路封闭归因于大雨。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿特崔比优特·图」——按份派回去，功劳或错处落到该去的人头上：归因、归功","word":"attribute to"},"root":"拉丁语「attribuere」「分派、给予」=「ad-」「朝向」+「tribuere」「分配、给予」←「tributum」「税」；同根有「contribute」「distribute」「tribute」。","sensesIntro":{"en":"Eight senses share one frame of assignment: naming a cause, crediting a person, naming an author, assigning a quality, tracing a symptom, attributing a climate effect, tracing an origin, and placing blame.","cn":"八个义项共享同一个「分派」框架：指出原因、把功劳归于某人、认定作者、归属品质、追溯症状、归因气候现象、溯源系属、分派过错。"},"semanticMap":{"core":{"en":"CORE IMAGE: a brush draws a new name back to an older branch on a family scroll and marks where that branch comes from.","cn":"核心意象：朱笔把新添的名字画回家谱上较老的枝，并标明这一枝的来处。"},"chain":["SHARE DIVIDED","SHARE GIVEN","TARGET NAMED","ORIGIN TRACED","CREDIT BESTOWED","BLAME PLACED"],"branches":[{"senses":"01 · 06","en":"THE CAUSE: a factor receives its share of responsibility, whether a local event or a warming climate.","cn":"原因：某个因素得到它的一份责任，无论是局部事件还是气候变暖。"},{"senses":"02 · 08","en":"THE PERSON: the same share becomes honour for a captain or shame for a pilot.","cn":"人：同一份既可成为队长的荣誉，也可成为飞行员的羞耻。"},{"senses":"03 · 04","en":"THE WORK AND THE QUALITY: a creation is given a hand, and a trait is given a subject.","cn":"作品与品质：创作被配上一双手，特征被配上一个主体。"},{"senses":"05","en":"THE SYMPTOM: a fever is sent back to the creature that caused it.","cn":"症状：发热被送回到引起它的生物。"},{"senses":"07","en":"THE LINEAGE: a word or custom is set on a branch of a larger family tree.","cn":"谱系：一个词或习俗被放到更大谱系树的某一枝上。"}]},"affixes":{"intro":{"en":"Attribute is built from a Latin verb of dividing and giving, and its family spreads across money, praise and blame.","cn":"这个词由一个表示分配与给予的拉丁动词构成，其词族散布在钱财、赞誉与责难之间。"},"latinIntro":{"en":"Latin supplies tribuere and attribuere, with tributum behind them; the same root reaches English through tribute, contribute and distribute.","cn":"拉丁语提供了「tribuere」与「attribuere」，它们背后是「tributum」；同一词根经「tribute」、「contribute」与「distribute」进入英语。"},"items":[{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"朝向；向","example":"The prefix sends the share to a target.","exampleCN":"这个前缀把那一份送往一个目标。"},{"word":"tributum","structure":"Latin noun","meaning":"tax, a payment divided among people","meaningCN":"税；按人分摊的款项","example":"The concrete image is a sum parted out.","exampleCN":"这一具体意象是把一笔钱分出去。"},{"word":"tribuere","structure":"Latin verb from tributum","meaning":"to divide, allot, grant","meaningCN":"分配；分给；授予","example":"The verb names the act of giving each its share.","exampleCN":"这个动词指给每一方一份的动作。"},{"word":"attribuere","structure":"Latin verb from ad- and tribuere","meaning":"to assign, to impute","meaningCN":"分派；归到……身上","example":"The compound is the direct source of the English verb.","exampleCN":"这个复合词是这个英语动词的直接来源。"},{"word":"tribute","structure":"English noun from tributum","meaning":"a payment to a stronger power","meaningCN":"贡品；贡金","example":"English kept the concrete payment.","exampleCN":"英语保留了具体的缴纳物。"},{"word":"contribute","structure":"English verb from com- and tribuere","meaning":"to give towards a common purpose","meaningCN":"贡献；捐助","example":"The prefix com- gathers the shares together.","exampleCN":"前缀「com-」把各份聚到一起。"},{"word":"distribute","structure":"English verb from dis- and tribuere","meaning":"to give out in separate shares","meaningCN":"分发；分配","example":"The prefix dis- scatters the shares apart.","exampleCN":"前缀「dis-」把各份散开。"},{"word":"attribution","structure":"English noun from attribuere","meaning":"the act of naming a source","meaningCN":"归因；归属","example":"The noun names the whole act of assignment.","exampleCN":"这个名词指整个分派行为。"},{"word":"-able","structure":"English adjective ending","meaning":"capable of being","meaningCN":"能够被……的","example":"It forms the word for what can be attributed.","exampleCN":"它构成表示「可被归因」的词。"}],"latinEntries":[{"word":"tributum","structure":"Latin noun","meaning":"tax, payment","meaningCN":"税；款项"},{"word":"tribuere","structure":"Latin verb from tributum","meaning":"to divide, allot, give","meaningCN":"分配；给予"},{"word":"attribuere","structure":"Latin verb from ad- and tribuere","meaning":"to assign, to impute","meaningCN":"分派；归到……身上"},{"word":"attributio","structure":"Latin noun from attribuere","meaning":"an assignment, an allotment","meaningCN":"分派；分配"}],"derivatives":[{"word":"attribution","pos":"n.","zh":"由该动词加名词尾构成，义为「归因；归属；出处」"},{"word":"attributable","pos":"adj.","zh":"由该动词加形容词尾构成，义为「可归因的；可归功的」"},{"word":"attributive","pos":"adj.","zh":"由同一词干加形容词尾构成，义为「定语性的」"},{"word":"attribute","pos":"n.","zh":"短语核心词的名词形式，义为「属性；特征」"},{"word":"misattribute","pos":"v.","zh":"由表示「错误」的前缀加该动词构成，义为「错归；误认为出自」"}]}},{"word":"be associated with","ipa_uk":"/biː əˈsəʊsieɪtɪd wɪð/","ipa_us":"/biː əˈsoʊsieɪtɪd wɪð/","definition_zh":"与……有关联；与……有联系；伴随出现；与……共事交往；与……结盟联合；是……的风险因素；使人联想到；与……有牵连；与……相对应","definition_en":"to be connected with something or someone, whether by a statistical link, a shared setting, a personal or institutional tie, a risk factor, a memory, a suspicion or a conceptual correspondence","core_image":"一张统计图上两条曲线同向起落，旁边用一条细线把它们连到同一个坐标点，却没有标出箭头方向","scene":"保险公司把十年的理赔记录摊在桌上，两条曲线在图上同向起落，分析员用红笔把它们连到同一个点。Smoking can be associated with a higher risk of lung disease in long-term studies.","sceneCN":"保险公司的桌上摊着成叠的理赔单（第 1 个义项：统计相关）；句意为在长期研究中，吸烟可能与更高的肺病风险相关。图中可辨识物件：理赔记录、两条同向起伏的曲线、坐标纸、红笔。","pos":[{"tag":"phr.","zh":"与……有关联；与……有联系；伴随出现；与……有牵连"}],"collocations":[{"phrase":"be associated with","zh":"与……有关联"},{"phrase":"be closely associated with","zh":"与……密切相关"},{"phrase":"be strongly associated with","zh":"与……强相关"},{"phrase":"be statistically associated with","zh":"在统计上与……相关"},{"phrase":"be associated with risk","zh":"与风险相关"},{"phrase":"be associated with a disease","zh":"与某种疾病相关"},{"phrase":"be associated with a scandal","zh":"与丑闻有牵连"}],"forms":[{"label":"原形","form":"be associated with"},{"label":"现在时","form":"is / are associated with"},{"label":"过去时","form":"was / were associated with"},{"label":"情态","form":"can be associated with"},{"label":"名词形式","form":"association with"},{"label":"分词形容词","form":"associated"}],"derivatives":[{"word":"associate","pos":"v./n.","zh":"由拉丁动词「associare」经分词形式而来，义为「使关联；结交；同事」"},{"word":"association","pos":"n.","zh":"加表示动作结果的名词尾构成，义为「协会；联想；关联」"},{"word":"associative","pos":"adj.","zh":"加形容词尾构成，义为「联想的；结合的」"},{"word":"social","pos":"adj.","zh":"同出「socius」，义为「社会的；社交的」"},{"word":"society","pos":"n.","zh":"同出「socius」，义为「社会；社团」"}],"senses":[{"no":"01","title":"Statistical correlation","titleCN":"统计上的相关","definition":"to show a measurable statistical link with another variable, without showing that one causes the other","definitionCN":"与另一个变量之间存在可测量的统计联系，且不表示一方导致另一方","example":"Higher income can be associated with longer life expectancy in national surveys.","exampleCN":"在各国调查中，较高的收入可能与更长的预期寿命相关。","why":"The passive frame came from the idea of joining two things, and statistics uses it for two quantities that rise and fall together.","whyCN":"被动框架来自「把两样东西连在一起」的观念，统计学用它指两个同时起落的量。"},{"no":"02","title":"Co-occurrence","titleCN":"伴随同时出现","definition":"to appear at the same time or in the same setting as something else, without a claim about cause","definitionCN":"与另一事物在同一时间或同一场合出现，不带因果断言","example":"Swallows can be associated with the arrival of warm spring weather.","exampleCN":"燕子可能与温暖春天气息的到来同时出现。","why":"If two things are seen together often enough, the mind joins them before any proof of cause exists.","whyCN":"两样东西若常被一起看到，人会在有因果证据之前先把它们连起来。"},{"no":"03","title":"Working or mixing with people","titleCN":"与某人共事交往","definition":"to spend time, work or cooperate with a person, especially in a professional or social setting","definitionCN":"与某人在职业或社交场合相处、共事或合作","example":"Junior researchers may be associated with senior scholars on a long project.","exampleCN":"年轻研究者可能在长期项目中与资深学者共事。","why":"The oldest sense of the Latin word is companionship, so the phrase still covers people who keep company.","whyCN":"这个拉丁词最古老的意思是伙伴关系，因此该短语仍指与人交往共事。"},{"no":"04","title":"Alliance with an organisation","titleCN":"与组织结盟联合","definition":"to be formally linked to an institution as a member, partner or ally","definitionCN":"作为成员、伙伴或盟友与某个机构建立正式联系","example":"The new clinic can be associated with a teaching hospital in the same city.","exampleCN":"这家新诊所能与同城的一家教学医院建立联合关系。","why":"Institutions join the way people do, and the same passive phrase marks the partnership.","whyCN":"机构之间的联合与人之间的结交同构，同一个被动短语标出这种伙伴关系。"},{"no":"05","title":"A risk factor for disease","titleCN":"作为疾病风险因素","definition":"to be statistically linked to a disease as a factor that raises its likelihood","definitionCN":"作为提高患病可能性的因素，与某种疾病存在统计联系","example":"Poor sleep can be associated with heart disease in middle age.","exampleCN":"睡眠不足可能与中年时期的心脏病相关。","why":"Medicine borrowed the statistical frame and turned a measured link into a warning about risk.","whyCN":"医学借用了统计框架，把测得的联系变成了关于风险的提醒。"},{"no":"06","title":"Bringing a memory to mind","titleCN":"唤起记忆联想","definition":"to call up a remembered person, place or feeling through resemblance or past pairing","definitionCN":"通过相似或过去的配对，唤起记忆中的人、地点或感受","example":"For many listeners, that tune can be associated with childhood summers.","exampleCN":"对许多听众来说，那段旋律可能让人联想到童年的夏天。","why":"The mind stores things in pairs, so one item becomes the cue that summons the other.","whyCN":"心智把事物成对存放，于是一个事物成为唤起另一个的线索。"},{"no":"07","title":"Implication in a scandal","titleCN":"与丑闻有牵连","definition":"to be connected to wrongdoing or a scandal, usually with damage to reputation","definitionCN":"与不当行为或丑闻扯上关系，通常伴随名誉受损","example":"Two officials may be associated with the contract scandal.","exampleCN":"两名官员可能与这起合同丑闻有牵连。","why":"A name placed next to a scandal is enough to stain it, even before any charge is proved.","whyCN":"名字只要与丑闻并排出现就足以染上污点，哪怕指控尚未证实。"},{"no":"08","title":"Conceptual correspondence","titleCN":"概念上的对应","definition":"to correspond to another item within a model, mapping or system of symbols","definitionCN":"在模型、映射或符号系统中与另一项相对应","example":"In this model, each symbol can be associated with one physical quantity.","exampleCN":"在这个模型中，每个符号可以与一个物理量相对应。","why":"A model is a set of paired entries, and the phrase names the link between the two columns.","whyCN":"模型就是一组成对的条目，该短语指两列之间的对应关系。"}],"etymology":{"intro":{"en":"Associate comes from Latin associare, to join together, built from ad-, toward, and socius, a companion or ally. The same socius underlies social, society and sociable, and English later fixed the passive frame be associated with for every kind of link.","cn":"这个词来自拉丁语的「associare」「联合」，由「ad-」「朝向」与「socius」「同伴、盟友」构成。同一个「socius」也是「social」「society」「sociable」的来源；英语后来固定了被动框架「be associated with」，用来表示各种联系。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant a companion, ally or partner, someone who shares something with another person.","cn":"「socius」指同伴、盟友或伙伴，即与他人共享某物的人。"},{"era":"LATIN AD-","en":"The prefix ad- meant toward, and before a word it marked direction or attachment.","cn":"前缀「ad-」意为朝向，加在词前表示方向或附着。"},{"era":"LATIN ASSOCIARE","en":"Joining ad- to socius produced associare, to unite with or keep company with another.","cn":"把「ad-」与「socius」合起来得到「associare」，意为与……联合或与……为伴。"},{"era":"LATIN ASSOCIATUS","en":"Its past participle associatus meant joined or united, and it supplied the shape of the English adjective.","cn":"其过去分词「associatus」意为已联合的，为英语的形容词形式提供了形状。"},{"era":"ENGLISH ASSOCIATE","en":"English adopted associate as a verb for joining with another, and as a noun for a colleague or partner.","cn":"英语把「associate」用作动词表示与人结交，也用作名词表示同事或伙伴。"},{"era":"THE PASSIVE FRAME","en":"The passive phrase be associated with later became the standard wording for statistical, medical and social links.","cn":"被动短语「be associated with」后来成为统计、医学与社会联系的通用说法。"}]},"similar":{"note":{"en":"The first group looks and sounds like associate; the second group contrasts three ways of linking things: associated with reports a link that may be statistical, social or accidental, characterized by names the defining mark of a thing, and composed of names the parts that make a whole.","cn":"第一组在形音上与「associate」相近；第二组对照三种连接方式：「associated with」表示可能是统计、社交或偶然的联系，「characterized by」指出事物的定义性标志，「composed of」指出构成整体的各个部分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"associate","ipa":"/əˈsəʊsieɪt/","tag":"same root","definition":"To join with another as a colleague, partner or companion, or such a colleague.","definitionCN":"指作为同事、伙伴或同伴与人结交，也指这样的同事。"},{"word":"association","ipa":"/ˌæsəʊsiˈeɪʃn/","tag":"same root","definition":"The noun for a society, a partnership or a mental link between ideas.","definitionCN":"指协会、伙伴关系，或观念之间的心理联系。"},{"word":"associative","ipa":"/əˌsəʊsiˈeɪtɪv/","tag":"same root","definition":"Relating to mental connection between one idea and another.","definitionCN":"指一个观念与另一个观念之间的心理联系。"},{"word":"dissociate","ipa":"/ˌdɪsəˈsəʊsieɪt/","tag":"same root","definition":"To separate one thing from another in the mind or in law, the opposite direction of association.","definitionCN":"指在心里或法律上把一事物与另一事物分开，是关联的反方向。"},{"word":"social","ipa":"/ˈsəʊʃl/","tag":"same root","definition":"Concerning people living together; it comes from socius but no longer carries a link in the phrase.","definitionCN":"指人们共同生活的；同出「socius」，但在短语中已不表示具体联系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"be linked to","ipa":"/biː lɪŋkt tuː/","tag":"near meaning","definition":"To be connected with something, often without the statistical or personal shades of associated with.","definitionCN":"指与某事物相连，通常不带「associated with」的统计或人际色彩。"},{"word":"be correlated with","ipa":"/biː ˌkɒrəˈleɪtɪd wɪð/","tag":"near meaning","definition":"To vary together in a measured way; narrower than associated with, because it demands a statistical measure.","definitionCN":"指以可测量的方式共同变化；比「associated with」窄，因为它要求统计度量。"},{"word":"be characterized by","ipa":"/biː kəˈræktəraɪzd baɪ/","tag":"near meaning","definition":"To have a defining mark that identifies the thing; it states a feature, not a statistical link.","definitionCN":"指具有可识别事物的定义性标志；它陈述特征，而非统计联系。"},{"word":"be composed of","ipa":"/biː kəmˈpəʊzd ɒv/","tag":"near meaning","definition":"To consist of parts that make up a whole; it answers what the thing is made of, not what it is linked to.","definitionCN":"指由构成整体的各个部分组成；它回答事物由什么做成，而非与什么相连。"},{"word":"be affiliated with","ipa":"/biː əˈfɪlieɪtɪd wɪð/","tag":"near meaning","definition":"To be officially attached to an organisation, a narrower institutional version of associated with.","definitionCN":"指正式隶属于某机构，是「associated with」较窄的机构版本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real family of socius and the everyday settings where the phrase appears.","cn":"正常联想使用「socius」的真实同族词，以及该短语出现的日常场景。"},"normal":[{"en":"Socius is the Latin companion behind social, society and sociable.","cn":"「socius」是拉丁语里的同伴，也是「social」「society」「sociable」的来源。"},{"en":"A shared office, a shared project and a shared surname all make two things associated.","cn":"共用的办公室、共同的项目、共同的姓氏，都会让两样东西产生关联。"},{"en":"Statistics says associated, never causes, when two curves only move together.","cn":"两条曲线只是同向移动时，统计学只说「associated」，从不说「causes」。"},{"en":"Doctors say a habit can be associated with a disease when the link holds across many studies.","cn":"当联系在多份研究中都成立时，医生会说某种习惯可能与某种疾病相关。"},{"en":"In memory, one smell can be associated with a whole kitchen from childhood.","cn":"在记忆里，一种气味可能让人联想到童年整间厨房。"}],"abstract":[{"en":"Association is a line drawn between two things before anyone knows which way cause runs.","cn":"关联是在还没人知道因果方向时，先在两样东西之间画的一条线。"},{"en":"The same phrase serves a colleague, a hospital and a risk factor, because all three are names joined to another name.","cn":"同一个短语可指同事、医院与风险因素，因为这三者都是与另一个名字并排的名字。"},{"en":"A scandal spreads by adjacency: one name beside another is already a stain.","cn":"丑闻靠相邻关系扩散：一个名字挨着另一个名字，就已经是污点。"}]},"examples":[{"en":"The survey shows that long commutes can be associated with stress.","cn":"这项调查显示，长时间通勤可能与压力相关。"},{"en":"Her early papers can be associated with a research group in Kyoto.","cn":"她早期的论文可能与京都的一个研究小组有关联。"},{"en":"In the story, the broken watch can be associated with his lost brother.","cn":"在故事里，那只坏掉的手表可能让人联想到他失踪的弟弟。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「比 呃搜西埃提德 威兹」——把两样东西并排写在同一行，中间画一道细线：有关联、有来往","word":"be associated with"},"root":"拉丁语「associare」「联合」由「ad-」「朝向」与「socius」「同伴、盟友」构成；同族词有「social」「society」「sociable」。英语用被动框架「be associated with」把统计相关、伴随出现、人际交往、机构结盟、疾病风险、记忆联想、丑闻牵连与概念对应都收进同一个短语。注意它只说明「有联系」，既不说明因果，也不说明构成。","sensesIntro":{"en":"Eight senses share one frame: the link may be measured, observed, social, institutional, medical, remembered, suspected or conceptual.","cn":"八个义项共用一个框架：这种联系可以是测量出来的、观察到的、人际的、机构的、医学的、记忆的、被怀疑的或概念上的。"},"semanticMap":{"core":{"en":"CORE IMAGE: two names are written side by side and a thin line joins them, with no arrow of cause.","cn":"核心意象：两个名字并排写着，一条细线把它们连起来，却没有表示因果的箭头。"},"chain":["LATIN SOCIUS","COMPANION LINK","JOINED NAME","SHARED SETTING","MEASURED LINK","PASSIVE FRAME"],"branches":[{"senses":"01 · 05","en":"THE MEASURED LINK: two quantities move together, and medicine reads the same frame as risk.","cn":"测量的联系：两个量一起变动，医学把同一框架读作风险。"},{"senses":"02","en":"THE SHARED SETTING: two things appear in the same place or time, with no cause claimed.","cn":"共同场合：两样东西在同一地点或时间出现，不断言因果。"},{"senses":"03 · 04","en":"THE JOINED PARTY: a person keeps company with another, or an institution joins an ally.","cn":"联合的一方：一个人与另一个人交往，或一个机构与盟友结盟。"},{"senses":"06","en":"THE MEMORY CUE: one thing summons another that was stored beside it.","cn":"记忆线索：一个事物唤起曾与它一起存放的另一个。"},{"senses":"07 · 08","en":"THE SUSPECTED OR MAPPED LINK: a name beside a scandal, or a symbol matched to a quantity.","cn":"被怀疑或映射的联系：名字挨着丑闻，或符号对应某个量。"}]},"affixes":{"intro":{"en":"The phrase is built from a Latin verb whose core is socius, a companion, and the family still runs through English social vocabulary.","cn":"这个短语由一个拉丁动词构成，其核心是「socius」「同伴」，这一族词仍贯穿英语的社会类词汇。"},"latinIntro":{"en":"Latin supplies socius, the prefix ad- and the verb associare; English adds the passive frame and the noun and adjective endings.","cn":"拉丁语提供了「socius」、前缀「ad-」与动词「associare」；英语加上了被动框架以及名词与形容词词尾。"},"items":[{"word":"socius","structure":"Latin noun","meaning":"companion, ally","meaningCN":"同伴；盟友","example":"Socius named a person who shares something with another.","exampleCN":"「socius」指与他人共享某物的人。"},{"word":"ad-","structure":"Latin prefix","meaning":"toward","meaningCN":"朝向","example":"The prefix points the action toward another party.","exampleCN":"这个前缀把动作指向另一方。"},{"word":"associare","structure":"Latin verb from ad- and socius","meaning":"to join together","meaningCN":"联合；结交","example":"The verb joins two parties in one act.","exampleCN":"这个动词把两方连在一个动作里。"},{"word":"associatus","structure":"Latin past participle","meaning":"joined, united","meaningCN":"已联合的","example":"The participle describes the state of being joined.","exampleCN":"这个分词描述已联合的状态。"},{"word":"associate","structure":"English verb and noun","meaning":"to link or join; a colleague","meaningCN":"关联；同事","example":"English uses it for linking ideas and for a work partner.","exampleCN":"英语用它表示连接观念，也指工作伙伴。"},{"word":"association","structure":"English noun from associate","meaning":"a society or a mental link","meaningCN":"协会；联想","example":"The noun names both an organisation and a mental connection.","exampleCN":"这个名词既指组织，也指心理联系。"},{"word":"associative","structure":"English adjective","meaning":"relating to connection","meaningCN":"联想的；结合的","example":"The adjective describes thinking that works by connection.","exampleCN":"这个形容词描述靠联系运作的思维。"},{"word":"social","structure":"English adjective from socius","meaning":"concerning people together","meaningCN":"社会的；社交的","example":"The adjective describes life with other people.","exampleCN":"这个形容词描述与他人共同的生活。"},{"word":"society","structure":"English noun from socius","meaning":"an organised community","meaningCN":"社会","example":"The noun names a community held together by shared rules.","exampleCN":"这个名词指由共同规则维系的人群。"},{"word":"sociable","structure":"English adjective from socius","meaning":"fond of company","meaningCN":"好交际的","example":"The adjective describes a person who enjoys the company of others.","exampleCN":"这个形容词指喜欢与他人相处的人。"}],"latinEntries":[{"word":"socius","structure":"Latin noun","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"ad-","structure":"Latin prefix","meaning":"toward","meaningCN":"朝向"},{"word":"associare","structure":"Latin verb","meaning":"to join together, unite","meaningCN":"联合；结交"}],"derivatives":[{"word":"associate","pos":"v./n.","zh":"由拉丁动词「associare」经分词形式而来，义为「使关联；结交；同事」"},{"word":"association","pos":"n.","zh":"加表示动作结果的名词尾构成，义为「协会；联想；关联」"},{"word":"associative","pos":"adj.","zh":"加形容词尾构成，义为「联想的；结合的」"},{"word":"social","pos":"adj.","zh":"同出「socius」，义为「社会的；社交的」"},{"word":"society","pos":"n.","zh":"同出「socius」，义为「社会；社团」"}]}},{"word":"be characterized by","ipa_uk":"/biː kəˈræktəraɪzd baɪ/","ipa_us":"/biː ˈkærəktəraɪzd baɪ/","definition_zh":"以……为特征；具有……特征；表现为……；以……为标志；由……主导；以……为典型；材料具有……特性；被刻画为……","definition_en":"to have a particular feature as the mark that identifies, defines or typifies the thing described","core_image":"一块木牌上刻着一道深痕，检验员不看整块木料，只凭这道痕就认出它属于哪一批","scene":"地质队员站在一处河谷前，向导指着两岸的红色岩壁，说认出这套地层靠的是颗粒粗细与胶结物的颜色。The red beds can be characterized by coarse grains and iron cement.","sceneCN":"向导在河谷边讲解地层（第 1 个义项：以某事物为主要特征）；句意为这套红色地层以粗颗粒与铁质胶结物为特征。图中可辨识物件：红色岩壁、地质锤、放大镜、记录本。","pos":[{"tag":"phr.","zh":"以……为特征；具有……特征；表现为……；以……为标志"}],"collocations":[{"phrase":"be characterized by","zh":"以……为特征"},{"phrase":"be characterized by simplicity","zh":"以简约为特征"},{"phrase":"be characterized by accuracy","zh":"以精准为特征"},{"phrase":"be characterized by rapid growth","zh":"以快速增长为特征"},{"phrase":"be characterized by mild symptoms","zh":"以轻微症状为表现"},{"phrase":"be characterized by high strength","zh":"以高强度为特征"},{"phrase":"be characterized by low rainfall","zh":"以少雨为特征"}],"forms":[{"label":"原形","form":"be characterized by"},{"label":"现在时","form":"is / are characterized by"},{"label":"过去时","form":"was / were characterized by"},{"label":"情态","form":"can be characterized by"},{"label":"动词","form":"characterize"},{"label":"名词","form":"characterization"}],"derivatives":[{"word":"character","pos":"n.","zh":"由希腊「kharaktēr」经拉丁「character」而来，义为「性格；字符；特征」"},{"word":"characteristic","pos":"adj./n.","zh":"加形容词与名词词尾构成，义为「典型的；特征」"},{"word":"characterize","pos":"v.","zh":"加动词词尾构成，义为「以……为特征；刻画」"},{"word":"characterization","pos":"n.","zh":"加表示动作结果的名词尾构成，义为「刻画；描述」"},{"word":"characterless","pos":"adj.","zh":"加表示「缺少」的形容词尾构成，义为「无特征的；平淡的」"}],"senses":[{"no":"01","title":"The main distinguishing feature","titleCN":"以某事物为主要特征","definition":"to have a particular feature as the most noticeable or identifying quality of the thing","definitionCN":"以某个特征作为事物最显著或最具识别力的性质","example":"The old town can be characterized by narrow lanes and stone arches.","exampleCN":"这座老城以窄巷与石拱为主要特征。","why":"The Greek word behind the phrase meant an engraved mark, so a feature is treated as a mark cut into the thing.","whyCN":"这个短语背后的希腊词意为刻下的印记，因此特征被当作刻在事物上的一道痕。"},{"no":"02","title":"Defining a class or type","titleCN":"用于定义某类","definition":"to have a feature that defines a category and separates it from neighbouring categories","definitionCN":"具有某个特征，该特征定义一个类别并把它与相邻类别区分开","example":"The plant family can be characterized by four petals and a square stem.","exampleCN":"这个植物科以四枚花瓣与方形茎为定义特征。","why":"In taxonomy a mark is used to sort specimens, so the phrase became a tool for definition rather than description.","whyCN":"在分类学里标记用来分拣标本，于是这个短语成为定义的工具，而不只是描写。"},{"no":"03","title":"Showing signs or symptoms","titleCN":"表现为症状现象","definition":"to present a visible sign or symptom that indicates a condition","definitionCN":"表现出某种可见迹象或症状，从而提示某种状况","example":"The early stage can be characterized by mild fever and fatigue.","exampleCN":"早期阶段表现为轻微发热与乏力。","why":"A symptom is a mark the body displays, and diagnosis reads marks the way an inspector reads a stamp.","whyCN":"症状是身体显示出来的印记，诊断读这些印记，就像检验员读一枚戳记。"},{"no":"04","title":"A mark of a period or style","titleCN":"以某事物为标志（时期风格）","definition":"to be marked by a style or practice that typifies a historical period","definitionCN":"以某种典型化某个历史时期的风尚或做法为标志","example":"That period can be characterized by rapid urban growth and cheap printing.","exampleCN":"那个时期以快速的城市扩张与廉价印刷为标志。","why":"Historians pick one trait as the stamp of an age, and the phrase turns a period into a marked object.","whyCN":"历史学家挑出一个特征作为时代的戳记，这个短语就把一个时期变成带印记的对象。"},{"no":"05","title":"Dominated by a factor","titleCN":"由某因素主导（气候区）","definition":"to have one dominant factor that shapes the conditions of a region or zone","definitionCN":"由某个主导因素塑造一个地区或地带的状况","example":"The region can be characterized by long dry summers and mild winters.","exampleCN":"这个地区以漫长干燥的夏季与温和的冬季为特征。","why":"A climate zone is named by its controlling factor, so the feature is not a detail but the ruling condition.","whyCN":"气候带以控制性因素命名，因此这里的特征不是细节，而是主导条件。"},{"no":"06","title":"A typical method","titleCN":"以某方法为典型","definition":"to have a method or approach that is typical of a person, school or discipline","definitionCN":"具有某种典型体现某个人、学派或学科的方法","example":"His fieldwork can be characterized by patient observation rather than quick sampling.","exampleCN":"他的田野工作以耐心观察而非快速取样为典型。","why":"A method leaves the same kind of fingerprint as a style, so the phrase extends from objects to ways of working.","whyCN":"方法留下的指纹与风格相同，于是这个短语从对象扩展到工作方式。"},{"no":"07","title":"A property of a material","titleCN":"材料具有某特性","definition":"to have a measurable property that distinguishes a material or substance","definitionCN":"具有某种可测量的性质，从而区分一种材料或物质","example":"The alloy can be characterized by high strength at low weight.","exampleCN":"这种合金以低重量下的高强度为特性。","why":"Materials testing records numbers as marks, and a distinctive property becomes the signature of the substance.","whyCN":"材料检测把数值记为标记，而独特性质就成为这种物质的签名。"},{"no":"08","title":"Depicted by a trait in literature","titleCN":"文学中被刻画为","definition":"to be portrayed in a story through one defining trait or habit","definitionCN":"在故事中通过某一项定义性特质或习惯被刻画出来","example":"In the novel, the hero can be characterized by stubborn loyalty.","exampleCN":"在小说里，主人公以固执的忠诚为刻画特征。","why":"A fictional person is also a character, a marked figure, and one trait can serve as the engraving.","whyCN":"虚构人物也是一个「角色」，一个带印记的形象，一项特质就足以充当那道刻痕。"}],"etymology":{"intro":{"en":"Characterize comes from Greek kharaktēr, an engraved mark or stamp, from kharassein, to scratch or engrave. The word reached English through Latin character, and the verb was formed with -ize.","cn":"这个词来自希腊语「kharaktēr」「刻痕、印记」，更早出自「kharassein」「刻、雕」。它经拉丁语「character」进入英语，再加「-ize」构成动词。"},"items":[{"era":"GREEK KHARAKTER","en":"Kharaktēr named a mark cut or stamped into a surface, a distinctive imprint rather than a general quality.","cn":"「kharaktēr」指刻在或压印在表面上的痕迹，是可辨认的印记，而非笼统的性质。"},{"era":"GREEK KHARASSEIN","en":"The verb kharassein meant to scratch, engrave or carve, and it supplied the action behind the mark.","cn":"动词「kharassein」意为抓刻、雕琢或雕刻，为这道印记提供了动作来源。"},{"era":"LATIN CHARACTER","en":"Latin took character for a mark, stamp or distinctive sign, and the sense of a written sign survived in English.","cn":"拉丁语用「character」表示记号、戳记或独特标志，书写符号的意思在英语里保留下来。"},{"era":"ENGLISH CHARACTER","en":"English character came to mean a distinguishing trait of a person, and later a person in a story.","cn":"英语「character」进而指一个人的独特特质，后来又指故事里的人物。"},{"era":"THE -IZE VERB","en":"Characterize was formed on character with -ize, meaning to mark out or describe the distinctive quality of something.","cn":"「characterize」由「character」加「-ize」构成，意为标出或描述某事物的独特性质。"},{"era":"THE PASSIVE FRAME","en":"The passive phrase be characterized by became a standard frame in science, history and literary description.","cn":"被动短语「be characterized by」成为科学、历史与文学描写的标准框架。"}]},"similar":{"note":{"en":"The first group looks like character and shares its root; the second group contrasts three ways of linking things: characterized by names a defining mark, associated with reports a link that may be statistical or social, and composed of names the parts of a whole.","cn":"第一组与「character」形近且同源；第二组对照三种连接方式：「characterized by」指出定义性标志，「associated with」表示可能是统计或社交的联系，「composed of」指出构成整体的部分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"character","ipa":"/ˈkærəktə/","tag":"same root","definition":"A distinguishing trait of a person, a written sign, or a figure in a story.","definitionCN":"指一个人的独特特质、书写符号，或故事里的人物。"},{"word":"characteristic","ipa":"/ˌkærəktəˈrɪstɪk/","tag":"same root","definition":"A feature that marks out a person or thing, or the adjective for such a feature.","definitionCN":"指标出一个事物或人的特征，也指具有这种特征的。"},{"word":"characterize","ipa":"/kəˈræktəraɪz/","tag":"same root","definition":"To describe or identify the distinctive quality of something.","definitionCN":"指描述或识别某事物的独特性质。"},{"word":"characterization","ipa":"/ˌkærəktəraɪˈzeɪʃn/","tag":"same root","definition":"The act of describing a thing's features, or the portrayal of a figure in a story.","definitionCN":"指描述事物特征的行为，或故事中对人物的刻画。"},{"word":"caricature","ipa":"/ˌkærɪkəˈtjuːə/","tag":"different root","definition":"A comic exaggeration of a person; it looks close but comes from a different Italian word for loading.","definitionCN":"指对人物的滑稽夸张；形近但来自另一个表示装载的意大利语词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"be marked by","ipa":"/biː ˈmɑːkt baɪ/","tag":"near meaning","definition":"To show a visible sign of something; closer to a physical mark than to a defining rule.","definitionCN":"指显示出某事物的可见迹象；更接近物理印记，而非定义规则。"},{"word":"be defined by","ipa":"/biː dɪˈfaɪnd baɪ/","tag":"near meaning","definition":"To have something as the condition that fixes the identity of a thing.","definitionCN":"指以某事物作为确定事物身份的条件。"},{"word":"be associated with","ipa":"/biː əˈsəʊsieɪtɪd wɪð/","tag":"near meaning","definition":"To be merely linked, often statistically or socially; a link may exist without being a defining mark.","definitionCN":"指仅仅存在联系，常是统计或社交上的；这种联系未必构成定义性标志。"},{"word":"be composed of","ipa":"/biː kəmˈpəʊzd ɒv/","tag":"near meaning","definition":"To consist of parts; it names the material or members, not the identifying feature.","definitionCN":"指由部分组成；它说明材料或成员，而非识别特征。"},{"word":"be typified by","ipa":"/biː ˈtɪpɪfaɪd baɪ/","tag":"near meaning","definition":"To be represented by a typical example or feature of a whole class.","definitionCN":"指以一个典型例子或特征来代表整个类别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Greek mark behind the word and the settings where the phrase does its work.","cn":"正常联想使用这个词背后真实的希腊「刻痕」，以及该短语真正发挥作用的场景。"},"normal":[{"en":"The Greek word meant a groove cut into a surface, so a feature is a mark you can point to.","cn":"希腊词意为刻在表面的一道槽，因此特征就是你能指出来的一道痕。"},{"en":"Character, characteristic, characterize and characterization all keep the same engraved mark.","cn":"「character」「characteristic」「characterize」「characterization」都保留着同一道刻痕。"},{"en":"A stamp on a wooden tag tells an inspector which batch the timber belongs to.","cn":"木牌上的戳记告诉检验员这批木料属于哪一批。"},{"en":"In biology the phrase sorts specimens, while in statistics the neighbouring phrase only records a link.","cn":"在生物学里这个短语用来分拣标本，而在统计学里相邻的那个短语只记录联系。"},{"en":"A character in a novel can be characterized by one habit, the way a person is known by one scar.","cn":"小说人物可以一个习惯为刻画特征，就像一个人靠一道疤被认出来。"}],"abstract":[{"en":"A feature is evidence that someone could read the thing before meeting it.","cn":"特征是那件东西还没露面时，别人就已能读出它的证据。"},{"en":"To name the mark of a thing is to claim that the mark and the thing cannot be separated.","cn":"说出一个事物的标志，就是声称这个标志与事物无法分开。"},{"en":"Characterization is engraving done after the fact: the trait is chosen, then cut in.","cn":"刻画是事后的雕刻：先挑出特质，再把它刻进去。"}]},"examples":[{"en":"Desert plants can be characterized by thick leaves and deep roots.","cn":"沙漠植物以厚叶与深根为特征。"},{"en":"The second movement can be characterized by a slow, repeated rhythm.","cn":"第二乐章以缓慢重复的节奏为特征。"},{"en":"The patient's condition can be characterized by fever and a dry cough.","cn":"病人的状况表现为发热与干咳。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「比 克拉克特莱兹德 拜」——木板上刻一道痕，靠这道痕认整批木料：以……为特征","word":"be characterized by"},"root":"希腊语「kharaktēr」「刻痕、印记」来自「kharassein」「刻、雕」；经拉丁语「character」进入英语，加「-ize」构成「characterize」，再加被动框架「be ... by」。它的核心是「可辨认的印记」，说的是识别标志，而不是组成部分，也不是统计关联。","sensesIntro":{"en":"Eight senses move from a single visible feature to classification, symptoms, period style, climate, method, material property and literary portrayal.","cn":"八个义项从一个可见特征，扩展到分类、症状、时期风格、气候、方法、材料属性与文学刻画。"},"semanticMap":{"core":{"en":"CORE IMAGE: a deep groove cut into a wooden tag lets an inspector name the whole batch at a glance.","cn":"核心意象：木牌上刻着一道深痕，检验员一眼就能叫出整批木料的名字。"},"chain":["GREEK MARK","CUT GROOVE","STAMPED SIGN","ENGLISH CHARACTER","DEFINING FEATURE","PASSIVE FRAME"],"branches":[{"senses":"01 · 02","en":"THE IDENTIFYING MARK: a feature that names the thing or sorts it into a class.","cn":"识别标志：一个特征为事物命名，或把它归入某类。"},{"senses":"03","en":"THE VISIBLE SIGN: symptoms and phenomena that show what is happening.","cn":"可见迹象：症状与现象显示出正在发生什么。"},{"senses":"04 · 05","en":"THE PERIOD AND CLIMATE MARK: a style of an age, or the dominant factor of a zone.","cn":"时期与气候标志：一个时代的风尚，或一个地带的主导因素。"},{"senses":"06 · 07","en":"THE TYPICAL METHOD AND MATERIAL: a way of working, or a property of a substance.","cn":"典型方法与材料：一种工作方式，或一种材料的属性。"},{"senses":"08","en":"THE LITERARY PORTRAIT: a character drawn by one defining trait.","cn":"文学肖像：用一项定义性特质刻画的人物。"}]},"affixes":{"intro":{"en":"The word is built on a Greek noun for an engraved mark, carried into Latin and then fitted with English endings.","cn":"这个词建立在一个表示「刻痕」的希腊名词上，经拉丁语传入后再装上英语词尾。"},"latinIntro":{"en":"Greek supplies kharaktēr and kharassein, Latin supplies character, and English adds -ize, -istic and -ation.","cn":"希腊语提供了「kharaktēr」与「kharassein」，拉丁语提供了「character」，英语再加上「-ize」「-istic」与「-ation」。"},"items":[{"word":"kharaktēr","structure":"Greek noun","meaning":"engraved mark, stamp","meaningCN":"刻痕；印记","example":"The mark was cut in so that it could be read later.","exampleCN":"这道痕迹被刻进去，以便日后辨认。"},{"word":"kharassein","structure":"Greek verb","meaning":"to scratch, engrave","meaningCN":"刻；雕","example":"The verb names the cutting that makes the mark.","exampleCN":"这个动词指造成痕迹的刻划动作。"},{"word":"character","structure":"Latin noun from Greek","meaning":"a mark, distinctive sign","meaningCN":"记号；独特标志","example":"Latin kept the sense of a stamped or written sign.","exampleCN":"拉丁语保留了压印或书写符号的意思。"},{"word":"character","structure":"English noun","meaning":"personality; written symbol; figure in a story","meaningCN":"性格；字符；故事人物","example":"The English noun widened from a sign to a person.","exampleCN":"这个英语名词从符号扩展到了人。"},{"word":"characteristic","structure":"English adjective and noun","meaning":"typical; a distinguishing feature","meaningCN":"典型的；特征","example":"It names the feature that marks the thing.","exampleCN":"它指那个标出事物的特征。"},{"word":"characterize","structure":"English verb from character","meaning":"to mark out or describe the nature of","meaningCN":"标出或描述……的性质","example":"The verb turns the mark into an act of description.","exampleCN":"这个动词把印记变成描述的行为。"},{"word":"characterization","structure":"English noun from characterize","meaning":"description; literary portrayal","meaningCN":"刻画；描述","example":"The noun names the finished portrait.","exampleCN":"这个名词指完成的肖像。"},{"word":"-ize","structure":"verb-forming suffix","meaning":"to make or give a quality","meaningCN":"使成为；使具有","example":"The suffix turns a noun of quality into a verb.","exampleCN":"这个词尾把表示性质的名词变成动词。"},{"word":"-istic","structure":"adjective-forming suffix","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The suffix builds the adjective from the same stem.","exampleCN":"这个词尾用同一词干构成形容词。"}],"latinEntries":[{"word":"character","structure":"Latin noun borrowed from Greek","meaning":"a mark, stamp, distinctive sign","meaningCN":"记号；戳记；独特标志"}],"derivatives":[{"word":"character","pos":"n.","zh":"由希腊「kharaktēr」经拉丁「character」而来，义为「性格；字符；特征」"},{"word":"characteristic","pos":"adj./n.","zh":"加形容词与名词词尾构成，义为「典型的；特征」"},{"word":"characterize","pos":"v.","zh":"加动词词尾构成，义为「以……为特征；刻画」"},{"word":"characterization","pos":"n.","zh":"加表示动作结果的名词尾构成，义为「刻画；描述」"},{"word":"characterless","pos":"adj.","zh":"加表示「缺少」的形容词尾构成，义为「无特征的；平淡的」"}]}},{"word":"be composed of","ipa_uk":"/biː kəmˈpəʊzd ɒv/","ipa_us":"/biː kəmˈpoʊzd əv/","definition_zh":"由……组成；由……构成；由（材料）制成；由（人员）组成；含有（化学成分）；由（地层）构成；由（部分）构成；由（词汇、物种）构成","definition_en":"to consist of particular materials, parts, members or elements that together make up the whole","core_image":"一只陶罐被轻轻敲开，断口露出三层颜色不同的泥料，每一层都能单独叫出名字","scene":"修复师把碎陶片按颜色和颗粒分成几堆，摆在白纸上，再一层层拼回罐身，最后指出它由三种泥料烧成。The ancient jar can be composed of three distinct clay layers.","sceneCN":"修复师在案上拼合陶片（第 1 个义项：由材料组成）；句意为这只古罐可能由三层不同的泥料构成。图中可辨识物件：陶片、白纸、放大镜、颜色标签。","pos":[{"tag":"phr.","zh":"由……组成；由……构成；由（若干部分）组成"}],"collocations":[{"phrase":"be composed of","zh":"由……组成"},{"phrase":"be composed of several parts","zh":"由若干部分组成"},{"phrase":"be composed of three layers","zh":"由三层构成"},{"phrase":"be composed of experts","zh":"由专家组成"},{"phrase":"be composed of carbon and hydrogen","zh":"由碳和氢构成"},{"phrase":"be composed of stone and timber","zh":"由石料与木材构成"},{"phrase":"be composed of local species","zh":"由本地物种组成"}],"forms":[{"label":"原形","form":"be composed of"},{"label":"现在时","form":"is / are composed of"},{"label":"过去时","form":"was / were composed of"},{"label":"情态","form":"can be composed of"},{"label":"动词","form":"compose"},{"label":"名词","form":"composition"}],"derivatives":[{"word":"compose","pos":"v.","zh":"由拉丁「componere」经法语「composer」而来，义为「组成；创作」"},{"word":"composition","pos":"n.","zh":"加表示动作结果的名词尾构成，义为「构成；作品；作文」"},{"word":"composer","pos":"n.","zh":"加表示施动者的名词尾构成，义为「作曲家」"},{"word":"component","pos":"n.","zh":"由同一拉丁词干而来，义为「组成部分；部件」"},{"word":"composite","pos":"adj./n.","zh":"由同一拉丁分词而来，义为「复合的；复合材料」"}],"senses":[{"no":"01","title":"Made of materials","titleCN":"由材料组成","definition":"to be made from particular materials that are mixed or combined","definitionCN":"由若干被混合或结合起来的特定材料制成","example":"The mortar can be composed of sand, lime and water.","exampleCN":"这种砂浆可以由砂、石灰与水组成。","why":"The Latin verb meant to place things together, so the phrase begins with material laid beside material.","whyCN":"这个拉丁动词意为把东西放在一起，因此该短语从材料与材料并排摆放开始。"},{"no":"02","title":"Parts forming a whole","titleCN":"部分构成整体","definition":"to consist of separate parts that together make one complete structure","definitionCN":"由若干分开的部分组成，这些部分合起来构成一个完整结构","example":"The roof can be composed of six prefabricated panels.","exampleCN":"这个屋顶可以由六块预制板构成。","why":"Placing parts together is the literal picture, and the finished structure is the result of that placement.","whyCN":"把部件放在一起就是字面画面，而完成的结构正是这种摆放的结果。"},{"no":"03","title":"People forming a body","titleCN":"人员组成团队或委员会","definition":"to consist of named members who together form a team, board or committee","definitionCN":"由指明的成员组成，他们合起来构成团队、董事会或委员会","example":"The review board can be composed of five independent experts.","exampleCN":"评审委员会可以由五位独立专家组成。","why":"A committee is a whole assembled from people, so the same verb that builds objects also builds bodies.","whyCN":"委员会是由人装配成的整体，因此造物的动词也用来造组织。"},{"no":"04","title":"Chemical composition","titleCN":"化学成分","definition":"to consist of chemical elements or compounds in fixed proportions","definitionCN":"由按一定比例存在的化学元素或化合物构成","example":"The mineral can be composed of calcium carbonate and traces of iron.","exampleCN":"这种矿物可以由碳酸钙与微量铁构成。","why":"Chemistry lists ingredients the way a recipe does, and the phrase names that list.","whyCN":"化学像食谱一样列出成分，这个短语指的就是这份清单。"},{"no":"05","title":"Layered rock or strata","titleCN":"地层分层","definition":"to consist of beds or layers stacked in a definite order","definitionCN":"由按确定次序叠置的层或岩层构成","example":"The cliff face can be composed of alternating shale and sandstone beds.","exampleCN":"这处崖面可以由页岩与砂岩层交替构成。","why":"Geology reads a cliff as a stack of placed layers, which is the Latin verb taken literally.","whyCN":"地质学把崖壁读成一叠摆放好的层，这正是那个拉丁动词的字面用法。"},{"no":"06","title":"Structure of a work","titleCN":"作品结构","definition":"to consist of sections or movements arranged into a larger artistic whole","definitionCN":"由若干段落或乐章排列成一个更大的艺术整体","example":"The symphony can be composed of four contrasting movements.","exampleCN":"这部交响曲可以由四个对比鲜明的乐章构成。","why":"To compose music and to compose a whole use the same arranging gesture, so structure and creation share the phrase.","whyCN":"谱写音乐与组合整体使用同一个排列动作，因此结构与创作共用这个短语。"},{"no":"07","title":"Words forming a corpus","titleCN":"词汇语料构成","definition":"to consist of texts or words collected into a body of language data","definitionCN":"由收集起来构成语言数据总体的文本或词语组成","example":"The learner corpus can be composed of essays written by secondary students.","exampleCN":"这个学习者语料库可以由中学生撰写的文章构成。","why":"A corpus is a body built from many texts, and the phrase treats each text as a placed piece.","whyCN":"语料库是由许多文本建成的整体，这个短语把每篇文本当作摆放进去的一块。"},{"no":"08","title":"Members of an ecological community","titleCN":"生态群落组成","definition":"to consist of species or populations that together form a community","definitionCN":"由若干物种或种群组成，它们合起来构成一个群落","example":"The reef community can be composed of corals, algae and grazing fish.","exampleCN":"这个珊瑚礁群落可以由珊瑚、藻类与食草鱼类组成。","why":"An ecosystem is an assembly of living parts, so the phrase extends the placed-together image to species.","whyCN":"生态系统是活体部件的装配，于是该短语把「放在一起」的画面扩展到物种。"}],"etymology":{"intro":{"en":"Compose comes from Latin componere, to put together, from com-, together, and ponere, to place. Its past participle compositus passed through French composer into English, and the passive frame be composed of was added later.","cn":"这个词来自拉丁语「componere」「组合」，由「com-」「一起」与「ponere」「放置」构成。其过去分词「compositus」经法语「composer」进入英语，后来再加上被动框架「be composed of」。"},"items":[{"era":"LATIN PONERE","en":"Ponere meant to place, put or set something down, and it supplied the core of the verb.","cn":"「ponere」意为放置、放下或安置，是该动词的核心。"},{"era":"LATIN COM-","en":"The prefix com- meant together or with, and it took the form com- before a p.","cn":"前缀「com-」意为一起或共同，在「p」之前取「com-」这一形式。"},{"era":"LATIN COMPONERE","en":"Putting com- before ponere produced componere, to place things together and so to arrange or compose.","cn":"把「com-」放在「ponere」前得到「componere」，意为把东西放在一起，进而指排列或组合。"},{"era":"LATIN COMPOSITUS","en":"The past participle compositus meant put together or arranged, and English took that shape for the adjective composed.","cn":"过去分词「compositus」意为已组合的、已排列的，英语的形容词「composed」就取了这个形状。"},{"era":"FRENCH COMPOSER","en":"The verb passed through French composer, which still meant to put together and also to produce a work.","cn":"这个动词经法语「composer」传入，仍指把东西放在一起，也指创作作品。"},{"era":"ENGLISH COMPOSE","en":"English compose covers making up a whole, writing a text and writing music, all from the same placing-together image.","cn":"英语「compose」既指构成整体，也指写作与作曲，都来自同一个「放在一起」的画面。"}]},"similar":{"note":{"en":"The first group looks like compose and shares its root; the second group contrasts three ways of linking things: composed of names the parts that make a whole, characterized by names the mark that identifies it, and associated with reports only a statistical or accompanying link.","cn":"第一组与「compose」形近且同源；第二组对照三种连接方式：「composed of」指出构成整体的各个部分，「characterized by」指出识别事物的标志，「associated with」只表示统计或伴随的联系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compose","ipa":"/kəmˈpəʊz/","tag":"same root","definition":"To make up a whole, to arrange parts, or to write a text or a piece of music.","definitionCN":"指构成整体、排列部分，或写作、作曲。"},{"word":"composition","ipa":"/ˌkɒmpəˈzɪʃn/","tag":"same root","definition":"The act of putting parts together, the resulting structure, or a written work.","definitionCN":"指把部分组合起来的行为、由此形成的结构，或一篇作品。"},{"word":"composer","ipa":"/kəmˈpəʊzə/","tag":"same root","definition":"A person who writes music, one who arranges parts into a whole.","definitionCN":"指创作音乐的人，即把部分排列成整体的人。"},{"word":"component","ipa":"/kəmˈpəʊnənt/","tag":"same root","definition":"One of the parts that together make up a larger whole.","definitionCN":"指合起来构成更大整体的部件之一。"},{"word":"composite","ipa":"/kəmˈpɒzɪt/","tag":"same root","definition":"Made of separate parts combined into one, or such a combined material.","definitionCN":"指由分开的部分合成一体的，也指这样的合成材料。"}]},{"heading":"NEAR MEANING","entries":[{"word":"consist of","ipa":"/kənˈsɪst ɒv/","tag":"near meaning","definition":"To be made up of parts; it comes from a different Latin verb meaning to stand, so it is not the same root.","definitionCN":"指由部分组成；它来自另一个意为「站立」的拉丁动词，并非同一词源。"},{"word":"comprise","ipa":"/kəmˈpraɪz/","tag":"near meaning","definition":"To include or be made up of; it comes from a Latin verb meaning to grasp together, a different root.","definitionCN":"指包含或由……构成；它来自一个意为「抓在一起」的拉丁动词，词源不同。"},{"word":"be made up of","ipa":"/biː meɪd ʌp ɒv/","tag":"near meaning","definition":"To be formed from parts, the plain everyday version of the same idea.","definitionCN":"指由部分组成，是同一意思的日常平实说法。"},{"word":"be associated with","ipa":"/biː əˈsəʊsieɪtɪd wɪð/","tag":"near meaning","definition":"To be linked to something, often statistically; it does not say what the thing is made of.","definitionCN":"指与某事物相联系，常是统计上的；它并不说明事物由什么构成。"},{"word":"be characterized by","ipa":"/biː kəˈræktəraɪzd baɪ/","tag":"near meaning","definition":"To have a defining mark; it names an identifying feature, not the parts.","definitionCN":"指具有定义性标志；它说明识别特征，而非组成部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the literal placing-together picture and the many wholes the phrase can inventory.","cn":"正常联想使用字面上「放在一起」的画面，以及该短语能清点出的各种整体。"},"normal":[{"en":"Com- means together and ponere means to place, so compose is literally to place together.","cn":"「com-」意为一起，「ponere」意为放置，因此「compose」字面上就是把东西放在一起。"},{"en":"Composition, composer, component and composite all keep the same placed-together picture.","cn":"「composition」「composer」「component」「composite」都保留着同一个「放在一起」的画面。"},{"en":"A committee is composed of members, a cake is composed of layers, and a poem is composed of lines.","cn":"委员会由成员组成，蛋糕由层组成，诗由行组成。"},{"en":"Be composed of names the parts; it does not name the mark that identifies them.","cn":"「be composed of」点出部分，并不点出识别这些部分的标志。"},{"en":"Consist of and comprise are close in meaning but come from different Latin verbs.","cn":"「consist of」与「comprise」意思接近，却来自不同的拉丁动词。"}],"abstract":[{"en":"A whole is a promise that its parts can be listed, and the phrase keeps that promise.","cn":"整体是一种承诺，承诺它的部分可以被列出来，而这个短语兑现了这份承诺。"},{"en":"The same word builds a jar from clay, a board from people and a reef from species.","cn":"同一个词用陶土造罐、用人组成委员会、用物种组成珊瑚礁。"},{"en":"Composition is neither a feature nor a statistical link; it is the inventory of what is inside.","cn":"构成既不是特征，也不是统计联系；它是内部东西的清单。"}]},"examples":[{"en":"The wall can be composed of local stone and lime mortar.","cn":"这面墙可以由本地石料与石灰砂浆构成。"},{"en":"The committee can be composed of teachers, parents and doctors.","cn":"这个委员会可以由教师、家长与医生组成。"},{"en":"The atmosphere can be composed of several layers with different temperatures.","cn":"大气可以由若干温度不同的层构成。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「比 康剖兹德 欧夫」——把几块料放进一只罐里，再数清里面有几样：由……组成","word":"be composed of"},"root":"拉丁语「com-」「一起」加「ponere」「放置」构成「componere」「组合」，过去分词「compositus」，经法语「composer」进入英语，再加被动框架「be composed of」。要注意：它与「comprise」（来自「comprehendere」「抓在一起」）和「consist」（来自「sistere」「站立」）形近而来源不同，不可混为一谈。","sensesIntro":{"en":"Eight senses follow the same inventory: material, parts, members, elements, layers, movements, texts and species are all counted as what the whole contains.","cn":"八个义项遵循同一份清单：材料、部件、成员、元素、岩层、乐章、文本与物种都被算作整体所含的内容。"},"semanticMap":{"core":{"en":"CORE IMAGE: a jar is broken open and three coloured clay layers are counted one by one inside the wall.","cn":"核心意象：陶罐被敲开，罐壁里三层颜色不同的泥料被一层层数出来。"},"chain":["LATIN PONERE","PLACE TOGETHER","JOINED PARTS","WHOLE MADE","LISTED INGREDIENTS","ORGANISED BODY"],"branches":[{"senses":"01 · 04","en":"THE MATERIAL MIX: clay, sand or chemical elements named as what the thing contains.","cn":"材料配比：陶土、砂石或化学元素，用来说明事物含有什么。"},{"senses":"02 · 05","en":"THE LAYERED WHOLE: prefabricated panels or rock beds stacked into a structure.","cn":"层叠整体：预制板或岩层叠合成一个结构。"},{"senses":"03 · 08","en":"THE MEMBER BODY: a board of people or a community of species that fills the whole.","cn":"成员整体：由人组成的委员会，或由物种组成的群落。"},{"senses":"06","en":"THE BUILT WORK: movements of a symphony arranged into a larger composition.","cn":"构建的作品：交响曲的乐章排列成更大的作品。"},{"senses":"07","en":"THE WORD INVENTORY: a corpus filled by essays from many writers.","cn":"词汇清单：由众多作者的文章填充起来的语料库。"}]},"affixes":{"intro":{"en":"The phrase is a Latin verb of placing, fitted with an English passive frame; its parts are com-, ponere and the participle ending.","cn":"这个短语是一个表示「放置」的拉丁动词，装上英语被动框架；其构件是「com-」「ponere」与分词词尾。"},"latinIntro":{"en":"Latin supplies ponere, com- and componere with its participle compositus; French passes the verb on, and English adds compose and its family.","cn":"拉丁语提供了「ponere」「com-」与「componere」及其分词「compositus」；法语把动词传下来，英语再加上「compose」及其同族词。"},"items":[{"word":"ponere","structure":"Latin verb","meaning":"to place, put, set down","meaningCN":"放置；放下","example":"The verb names the act of laying something in position.","exampleCN":"这个动词指把某物放在某一位置的动作。"},{"word":"com-","structure":"Latin prefix","meaning":"together, with","meaningCN":"一起；共同","example":"The prefix adds the idea of several things meeting.","exampleCN":"这个前缀加上若干事物会合的意思。"},{"word":"componere","structure":"Latin verb from com- and ponere","meaning":"to put together, arrange","meaningCN":"组合；排列","example":"The verb places parts side by side into one thing.","exampleCN":"这个动词把部件并排摆成一个东西。"},{"word":"compositus","structure":"Latin past participle","meaning":"put together, arranged","meaningCN":"已组合的；已排列的","example":"The participle describes the finished whole.","exampleCN":"这个分词描述已完成组合的整体。"},{"word":"compose","structure":"English verb through French","meaning":"to make up, arrange, write","meaningCN":"组成；排列；创作","example":"The English verb covers both structure and creation.","exampleCN":"这个英语动词既指结构，也指创作。"},{"word":"composition","structure":"English noun from compose","meaning":"the way parts are put together","meaningCN":"构成方式；作品","example":"The noun names the arrangement and its result.","exampleCN":"这个名词指排列方式及其结果。"},{"word":"composer","structure":"English agent noun","meaning":"one who writes music","meaningCN":"作曲家","example":"The ending names the person who arranges the parts.","exampleCN":"这个词尾指排列部件的人。"},{"word":"component","structure":"English noun from the same stem","meaning":"a part of a larger whole","meaningCN":"部件；组成部分","example":"Each component can be named separately.","exampleCN":"每个部件都能单独命名。"},{"word":"composite","structure":"English adjective and noun","meaning":"combined from parts","meaningCN":"复合的；复合材料","example":"The word describes a whole built from separate pieces.","exampleCN":"这个词描述由分开的块件建成的整体。"},{"word":"compound","structure":"English noun and adjective","meaning":"a combination of elements","meaningCN":"化合物；复合的","example":"It names a substance made by combining others.","exampleCN":"它指由其他物质结合而成的物质。"}],"latinEntries":[{"word":"ponere","structure":"Latin verb","meaning":"to place, put","meaningCN":"放置；放下"},{"word":"componere","structure":"Latin verb from com- and ponere","meaning":"to put together, arrange","meaningCN":"组合；排列"},{"word":"compositus","structure":"Latin past participle of componere","meaning":"put together, arranged","meaningCN":"已组合的；已排列的"}],"derivatives":[{"word":"compose","pos":"v.","zh":"由拉丁「componere」经法语「composer」而来，义为「组成；创作」"},{"word":"composition","pos":"n.","zh":"加表示动作结果的名词尾构成，义为「构成；作品；作文」"},{"word":"composer","pos":"n.","zh":"加表示施动者的名词尾构成，义为「作曲家」"},{"word":"component","pos":"n.","zh":"由同一拉丁词干而来，义为「组成部分；部件」"},{"word":"composite","pos":"adj./n.","zh":"由同一拉丁分词而来，义为「复合的；复合材料」"}]}}]);
